INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (1, '关于我', 'about', '一些能透露的信息', '# 我的一些信息\n\n---\n\n## 👋 你好，我是立里可\n\n一名来自江西某本科大学的软件工程学生，热衷于全栈开发与技术分享。\n\n> 🎯 目前状态：**2027届毕业生，寻求Java后端实习岗位**\n\n---\n\n## 📋 基本信息\n\n| 项目               | 内容                                              |\n| ------------------ | ------------------------------------------------- |\n| **姓名**     | 立里可                                            |\n| **学历**     | 江西某院校                                        |\n| **毕业时间** | 2027年6月                                         |\n| **邮箱**     | lilicould@qq.com                                  |\n| **电话**     | ***                                               |\n| **个人网站** | [lilicould.cn](https://lilicould.cn)                 |\n| **GitHub**   | [github.com/LiliCould](https://github.com/LiliCould) |\n\n---\n\n## 💻 技术栈\n\n### 前端\n\n![Vue](https://img.shields.io/badge/-Vue3-4FC08D?style=flat-square&logo=vue.js&logoColor=ffffff)![JavaScript](https://img.shields.io/badge/-JavaScript-F7DF1E?style=flat-square&logo=javascript&logoColor=000000)![TypeScript](https://img.shields.io/badge/-TypeScript-3178C6?style=flat-square&logo=typescript&logoColor=ffffff)![HTML/CSS](https://img.shields.io/badge/-HTML%2FCSS-E34F26?style=flat-square&logo=html5&logoColor=ffffff)\n\n### 后端\n\n![Java](https://img.shields.io/badge/-Java-007396?style=flat-square&logo=java&logoColor=ffffff)![Spring Boot](https://img.shields.io/badge/-Spring%20Boot-6DB33F?style=flat-square&logo=springboot&logoColor=ffffff)\n\n### 工具\n\n![Git](https://img.shields.io/badge/-Git-F05032?style=flat-square&logo=git&logoColor=ffffff)![Linux](https://img.shields.io/badge/-Linux-333333?style=flat-square&logo=linux&logoColor=ffffff)\n\n---\n\n## 🚀 项目经历\n\n### 立里博客 (liliblog)\n\n> 全栈开发 · 个人项目\n\n一个分享技术、生活和思考的个人博客网站\n\n**技术栈：** Vue3 + Element Plus + Java Spring Boot\n\n- 前端：基于 Vue3 + vue-design-plus 构建响应式博客界面\n- 后端：Spring Boot 提供 RESTFul API\n- 特性：文章发布、分类管理、评论互动\n\n**源码：** [前端](https://github.com/LiliCould/liliblog-frontend) · [后端](https://github.com/LiliCould/liliblog-backend)\n\n---\n\n## 🌟 个人主页\n\n### 🎯 立里博客\n\n**技术与生活的分享空间**\n\n[访问网站](https://lilicould.cn) · [关于我](https://lilicould.cn/about)\n\n*持续学习，热爱分享*\n\n---\n\n## 📝 自我评价\n\n- 🧑‍💻 对前端技术充满热情，喜欢探索新技术\n- 📚 热爱技术分享，通过博客记录学习心得\n- 🤝 具有良好的团队协作能力和沟通能力\n- 📖 持续学习，关注前端生态发展\n\n---\n\n*最后更新：2025年5月*\n', '<h1 id=\"我的一些信息\">我的一些信息</h1>\n<hr />\n<h2 id=\"-你好我是立里可\">👋 你好，我是立里可</h2>\n<p>一名来自江西某本科大学的软件工程学生，热衷于全栈开发与技术分享。</p>\n<blockquote>\n  <p>🎯 目前状态：<strong>2027届毕业生，寻求Java后端实习岗位</strong></p>\n</blockquote>\n<hr />\n<h2 id=\"-基本信息\">📋 基本信息</h2>\n<table>\n  <thead>\n    <tr><th>项目</th><th>内容</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>姓名</strong></td><td>立里可</td></tr>\n    <tr><td><strong>学历</strong></td><td>江西某院校</td></tr>\n    <tr><td><strong>毕业时间</strong></td><td>2027年6月</td></tr>\n    <tr><td><strong>邮箱</strong></td><td><a href=\"mailto:lilicould@qq.com\">lilicould@qq.com</a></td></tr>\n    <tr><td><strong>电话</strong></td><td>***</td></tr>\n    <tr><td><strong>个人网站</strong></td><td><a href=\"https://lilicould.cn\">lilicould.cn</a></td></tr>\n    <tr><td><strong>GitHub</strong></td><td><a href=\"https://github.com/LiliCould\">github.com/LiliCould</a></td></tr>\n  </tbody>\n</table>\n<hr />\n<h2 id=\"-技术栈\">💻 技术栈</h2>\n<h3 id=\"前端\">前端</h3>\n<p><img src=\"https://img.shields.io/badge/-Vue3-4FC08D?style=flat-square&amp;logo=vue.js&amp;logoColor=ffffff\" alt=\"Vue\" /><img src=\"https://img.shields.io/badge/-JavaScript-F7DF1E?style=flat-square&amp;logo=javascript&amp;logoColor=000000\" alt=\"JavaScript\" /><img src=\"https://img.shields.io/badge/-TypeScript-3178C6?style=flat-square&amp;logo=typescript&amp;logoColor=ffffff\" alt=\"TypeScript\" /><img src=\"https://img.shields.io/badge/-HTML%2FCSS-E34F26?style=flat-square&amp;logo=html5&amp;logoColor=ffffff\" alt=\"HTML/CSS\" /></p>\n<h3 id=\"后端\">后端</h3>\n<p><img src=\"https://img.shields.io/badge/-Java-007396?style=flat-square&amp;logo=java&amp;logoColor=ffffff\" alt=\"Java\" /><img src=\"https://img.shields.io/badge/-Spring%20Boot-6DB33F?style=flat-square&amp;logo=springboot&amp;logoColor=ffffff\" alt=\"Spring Boot\" /></p>\n<h3 id=\"工具\">工具</h3>\n<p><img src=\"https://img.shields.io/badge/-Git-F05032?style=flat-square&amp;logo=git&amp;logoColor=ffffff\" alt=\"Git\" /><img src=\"https://img.shields.io/badge/-Linux-333333?style=flat-square&amp;logo=linux&amp;logoColor=ffffff\" alt=\"Linux\" /></p>\n<hr />\n<h2 id=\"-项目经历\">🚀 项目经历</h2>\n<h3 id=\"立里博客-liliblog\">立里博客 (liliblog)</h3>\n<blockquote>\n  <p>全栈开发 · 个人项目</p>\n</blockquote>\n<p>一个分享技术、生活和思考的个人博客网站</p>\n<p><strong>技术栈：</strong> Vue3 + Element Plus + Java Spring Boot</p>\n<ul>\n  <li>前端：基于 Vue3 + vue-design-plus 构建响应式博客界面</li>\n  <li>后端：Spring Boot 提供 RESTFul API</li>\n  <li>特性：文章发布、分类管理、评论互动</li>\n</ul>\n<p><strong>源码：</strong> <a href=\"https://github.com/LiliCould/liliblog-frontend\">前端</a> · <a href=\"https://github.com/LiliCould/liliblog-backend\">后端</a></p>\n<hr />\n<h2 id=\"-个人主页\">🌟 个人主页</h2>\n<h3 id=\"-立里博客\">🎯 立里博客</h3>\n<p><strong>技术与生活的分享空间</strong></p>\n<p><a href=\"https://lilicould.cn\">访问网站</a> · <a href=\"https://lilicould.cn/about\">关于我</a></p>\n<p><em>持续学习，热爱分享</em></p>\n<hr />\n<h2 id=\"-自我评价\">📝 自我评价</h2>\n<ul>\n  <li>🧑‍💻 对前端技术充满热情，喜欢探索新技术</li>\n  <li>📚 热爱技术分享，通过博客记录学习心得</li>\n  <li>🤝 具有良好的团队协作能力和沟通能力</li>\n  <li>📖 持续学习，关注前端生态发展</li>\n</ul>\n<hr />\n<p><em>最后更新：2025年5月</em></p>\n', 'https://oss.lilicould.cn/cover/9a974035-766a-4e04-b9f6-81f325c260b5_小黄人.png', 1, 100, 2, '2026-05-18 11:00:15', '2026-05-18 22:18:37', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (23, '小叮当播报', 'dingdang', '小叮当播报', '现在濂溪区只有11℃，今日最高16℃，大风天气，多穿衣服，注意防寒保暖。出门在外记得保持警惕，手机在外面不要静音。今天只有一节课，但是下午有大例会，上课时间较晚，不要忘了吃早餐，这个点应该会更好抢一点。昨天我可能给你传递了一些负面情绪，这几天应该都有一点，希望你不要介意。不管前面怎么样，生活不会只有蹉跎，即使风再大，也不能把我们吹走。提醒几个重要的事，今天优先把这几个事情做了：1.对照着课表把工时算清楚了2.早些把单词背了3.检查有没有作业，有的话趁今天课少完成下作业希望臭丫头凡事有规划，做事有方法。以后会更好，天天开心。', '<p>现在濂溪区只有11℃，今日最高16℃，大风天气，多穿衣服，注意防寒保暖。出门在外记得保持警惕，手机在外面不要静音。今天只有一节课，但是下午有大例会，上课时间较晚，不要忘了吃早餐，这个点应该会更好抢一点。昨天我可能给你传递了一些负面情绪，这几天应该都有一点，希望你不要介意。不管前面怎么样，生活不会只有蹉跎，即使风再大，也不能把我们吹走。提醒几个重要的事，今天优先把这几个事情做了：1.对照着课表把工时算清楚了2.早些把单词背了3.检查有没有作业，有的话趁今天课少完成下作业希望臭丫头凡事有规划，做事有方法。以后会更好，天天开心。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 2, 1, 2, '2026-01-03 19:05:41', '2026-05-19 09:32:01', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (24, '小叮当播报', '2025-10-14-9-07', '2025年10月14日9时07分报', '濂溪区今天最低18℃，会很冷，注意加衣保暖，感冒还没有完全好。今天上午两节课，下午还要出去，记得要吃饭。天气预报显示阴天，不确定是否会下雨，下午出去建议带伞。还有三天见面了，养好状态哦。四级不要焦虑，一难皆难，多练下写作翻译，其次阅读。最后再次提醒，天冷加衣，注意保暖。可恶的小莹丫头。', '<p>濂溪区今天最低18℃，会很冷，注意加衣保暖，感冒还没有完全好。今天上午两节课，下午还要出去，记得要吃饭。天气预报显示阴天，不确定是否会下雨，下午出去建议带伞。还有三天见面了，养好状态哦。四级不要焦虑，一难皆难，多练下写作翻译，其次阅读。最后再次提醒，天冷加衣，注意保暖。可恶的小莹丫头。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 2, 5, 2, '2026-01-03 19:42:20', '2026-05-19 09:47:28', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (25, '小叮当播报', '2025-1-3-dingdang', '2025年1月3日报​', '一整天都没你的什么消息，心里有些空落落的。应该还要一个多小时，你就会回学校了吧。这几天特别冷，平均温度都只有五六度的样子，在季季红里面上班时候应该没什么问题，回来的时候还是要注意点，不要动着了。这几天上班给你吃饭时间都整坏了，晚上别忘记买点东西吃，明天只有一节课，这几天泡在火锅店不知道有没有变成红油小莹，明天好好洗个澡吧。可恶的小莹，明天濂溪区可能会下雨，记得带把伞以防万一，不要变成落汤红油臭小莹了。这是小叮当升级测试版，小叮当plus0.0.1，如有疑问，欢迎致电立里可。', '<p>一整天都没你的什么消息，心里有些空落落的。应该还要一个多小时，你就会回学校了吧。这几天特别冷，平均温度都只有五六度的样子，在季季红里面上班时候应该没什么问题，回来的时候还是要注意点，不要动着了。这几天上班给你吃饭时间都整坏了，晚上别忘记买点东西吃，明天只有一节课，这几天泡在火锅店不知道有没有变成红油小莹，明天好好洗个澡吧。可恶的小莹，明天濂溪区可能会下雨，记得带把伞以防万一，不要变成落汤红油臭小莹了。这是小叮当升级测试版，小叮当plus0.0.1，如有疑问，欢迎致电立里可。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 2, 3, 2, '2026-01-03 20:55:34', '2026-05-19 09:38:17', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (26, '小叮当播报', '2025-1-4-dingdang', '2025年1月4日报​', '元旦终于结束了，臭小莹刚结束工作就熬夜这么晚，我看你是想造反了。下午抽个时间睡一觉，可恶的女人。今天下雨，濂溪区温度3-7℃，没事的话还是不要出去了，累了三天好好补个觉。刮风下雨，还是要注意身体，现在已经头晕了，别整成大傻莹了。明天又要上课了，调整一下状态吧，上学的话还是挺冷的，戴好你那顶小帽子。', '<p>元旦终于结束了，臭小莹刚结束工作就熬夜这么晚，我看你是想造反了。下午抽个时间睡一觉，可恶的女人。今天下雨，濂溪区温度3-7℃，没事的话还是不要出去了，累了三天好好补个觉。刮风下雨，还是要注意身体，现在已经头晕了，别整成大傻莹了。明天又要上课了，调整一下状态吧，上学的话还是挺冷的，戴好你那顶小帽子。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 2, 3, 2, '2026-01-04 14:02:59', '2026-05-19 09:32:08', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (31, '富文本编辑器', 'full-text-editor', '尝试使用富文本编辑器', '之前使用过WangEditor作为富文本编辑器，但是今天访问官网的时候怎么都打不开了，尝试用了一下加速器发现也无济于事，于是只能考虑去使用别的富文本编辑器了。首先考虑的自然是百度的UEDITOR，虽然听说他好久不更新了，不过还是想试一下，结果该死的百度对UEDITOR十分不在意，甚至不便在Vue3中直接导入，于是我又选择了放弃。最后选择的Quill，因为他相对来说比较轻量而且比较好配置吧，跟着文档以及AI折腾了挺久，最后终于也是初步配置上了，不过还是有一些没整好的，还有就是只配置了一些基础的东西，后面或许会准备折腾上其他的配置项吧，也可能不会，毕竟我是整后端的，没必要费尽心里去研究这些前端的东西。实话实说前端也算是不简单的，最起码折腾了我不少时间。不论如何，这个富文本编辑器总算是上线了，虽然很勉强，现在可以正常新建文章并且以富文本的形式存储到数据库了，这个博客系统终于算是实现了最最基础的功能了，”读“和”写“。当然，其他的一大堆功能都还没弄，不过先这样吧，我实在是折腾不动前端这死东西了。以后的事以后再说吧，有了这个基础的富文本编辑器，这个东西就暂时到此为止吧，我或许要去折腾后端了。该死。', '之前使用过WangEditor作为富文本编辑器，但是今天访问官网的时候怎么都打不开了，尝试用了一下加速器发现也无济于事，于是只能考虑去使用别的富文本编辑器了。首先考虑的自然是百度的UEDITOR，虽然听说他好久不更新了，不过还是想试一下，结果该死的百度对UEDITOR十分不在意，甚至不便在Vue3中直接导入，于是我又选择了放弃。最后选择的Quill，因为他相对来说比较轻量而且比较好配置吧，跟着文档以及AI折腾了挺久，最后终于也是初步配置上了，不过还是有一些没整好的，还有就是只配置了一些基础的东西，后面或许会准备折腾上其他的配置项吧，也可能不会，毕竟我是整后端的，没必要费尽心里去研究这些前端的东西。实话实说前端也算是不简单的，最起码折腾了我不少时间。不论如何，这个富文本编辑器总算是上线了，虽然很勉强，现在可以正常新建文章并且以富文本的形式存储到数据库了，这个博客系统终于算是实现了最最基础的功能了，”读“和”写“。当然，其他的一大堆功能都还没弄，不过先这样吧，我实在是折腾不动前端这死东西了。以后的事以后再说吧，有了这个基础的富文本编辑器，这个东西就暂时到此为止吧，我或许要去折腾后端了。该死。', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 19, 2, '2026-01-04 23:31:18', '2026-05-19 09:46:46', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (32, '小叮当播报', 'dingdang-2025-1-5', '2025年1月5日报', '今天是2025年1月5号，出于我的突发决定，于是有了明天早上的车票。今天最低温度只有0℃了，非常冷喔，今天三节课，下午上完课应该会很冷喔，还是要注意一点。臭小莹的红油麻辣头没冻硬吧，明天可别拿来熏我。今天应该没有什么需要提醒你的吧，不过昨天睡到倒是挺早，今天继续保持，别明天见你的时候无精打采的，你可还得带我去吃海底捞呢。当然，既然是我来找你，自然是不会让你光出不进的，准备好愿望清单喔。', '<p>今天是2025年1月5号，出于我的突发决定，于是有了明天早上的车票。今天最低温度只有0℃了，非常冷喔，今天三节课，下午上完课应该会很冷喔，还是要注意一点。臭小莹的红油麻辣头没冻硬吧，明天可别拿来熏我。今天应该没有什么需要提醒你的吧，不过昨天睡到倒是挺早，今天继续保持，别明天见你的时候无精打采的，你可还得带我去吃海底捞呢。当然，既然是我来找你，自然是不会让你光出不进的，准备好愿望清单喔。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 2, 5, 2, '2026-01-05 11:30:05', '2026-05-19 09:32:14', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (33, '无意味', 'non-of', '测试用', '点击跳转至首页', '点击跳转至首页', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 11, 2, '2026-01-05 22:15:42', '2026-05-19 09:46:24', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (34, '从SSM架构到SpringBoot 4', 'ssm-switch-to-springboot', '后端项目从SSM架构转换为SpringBoot', 'SpringBoot1.0于2014年就正式发布了，如今已经2026年了，传统的SSM架构属实有点落后了。这个项目纯粹是为了练手做的，由于没人帮我搞前端，所以界面也是相当的丑陋。\n\n因为这是刚学完Spring基础的练手项目，所以架构自然而然采取SSM了，光是配置信息，为了实现全注解开发，包括容器配置，Spring的启动实现类替代web.xml，MyBatis的配置等等，配置这些东西就花了两天的时间，当然也是因为干了点别的。现在SpringBoot发布已经十多年了，去年都更新到4.0版本了，我们当然是要与时俱进的，并且这个练手项目又十分简单，于是昨天就把这个项目改为SpringBoot 4.0.1版本了。\n\n由于之前为了实现全注解开发，通过一大堆配置信息，结构与SpringBoot模式已经没太大差异了，毕竟SpringBoot也只是为了简化配置，所以自然而然不会有太大差异。于是我只是把pom.xml的大部分依赖替换了一下，然后把之前写的一些配置信息文件全部删除了就好了，毕竟SpringBoot已经自动配置好了。当然不可能那么简单的，项目是使用了lombok的，然而当我更新完pom.xml之后，却发现所有的Java bean的setter和getter都出问题了，最后折腾了好久才发现是lombok的版本问题导致它不生效，最后是指定了lombok的版本才终于成功run起来了。\n\n虽然只是简单进行了一下架构的替换，但前前后后也花费了不少的时间，今天又完善了一下分类的功能，这个简陋的小项目也算是又稍微完整了一点点。不过今天写的时候倒是发现有好多代码一坨屎，最开始就没设计好，有些东西完全可以AOP代理的，还有些依赖到处乱注入，不过毕竟是简陋小项目，也不管那么多，直接三七二十一，能run就行。\n', '<p>SpringBoot1.0于2014年就正式发布了，如今已经2026年了，传统的SSM架构属实有点落后了。这个项目纯粹是为了练手做的，由于没人帮我搞前端，所以界面也是相当的丑陋。</p>\n<p>因为这是刚学完Spring基础的练手项目，所以架构自然而然采取SSM了，光是配置信息，为了实现全注解开发，包括容器配置，Spring的启动实现类替代web.xml，MyBatis的配置等等，配置这些东西就花了两天的时间，当然也是因为干了点别的。现在SpringBoot发布已经十多年了，去年都更新到4.0版本了，我们当然是要与时俱进的，并且这个练手项目又十分简单，于是昨天就把这个项目改为SpringBoot 4.0.1版本了。</p>\n<p>由于之前为了实现全注解开发，通过一大堆配置信息，结构与SpringBoot模式已经没太大差异了，毕竟SpringBoot也只是为了简化配置，所以自然而然不会有太大差异。于是我只是把pom.xml的大部分依赖替换了一下，然后把之前写的一些配置信息文件全部删除了就好了，毕竟SpringBoot已经自动配置好了。当然不可能那么简单的，项目是使用了lombok的，然而当我更新完pom.xml之后，却发现所有的Java bean的setter和getter都出问题了，最后折腾了好久才发现是lombok的版本问题导致它不生效，最后是指定了lombok的版本才终于成功run起来了。</p>\n<p>虽然只是简单进行了一下架构的替换，但前前后后也花费了不少的时间，今天又完善了一下分类的功能，这个简陋的小项目也算是又稍微完整了一点点。不过今天写的时候倒是发现有好多代码一坨屎，最开始就没设计好，有些东西完全可以AOP代理的，还有些依赖到处乱注入，不过毕竟是简陋小项目，也不管那么多，直接三七二十一，能run就行。</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 47, 1, '2026-01-13 21:56:10', '2026-05-19 09:34:43', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (35, '下雨', 'rain-bad', '回南昌，下大雨，淋成落汤鸡', '今天回南昌，下大雨，难受\n\n棉袄全湿了累\n', '<p>今天回南昌，下大雨，难受</p>\n<p>棉袄全湿了累</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 2, 2, '2026-03-08 22:37:31', '2026-05-19 09:32:22', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (36, 'XSS攻击测试', 'xss-attack', '测试xss攻击', '&nbsp; &lt;div class=\"test\"&gt;&nbsp; &nbsp; &nbsp; &lt;h2&gt;测试区域&lt;/h2&gt;&nbsp; &nbsp; &nbsp; &lt;p&gt;这里可以放一些测试内容，或者调试用的组件。&lt;/p&gt;&nbsp; &nbsp; &nbsp; &lt;p onload=\"alert(\'XSS攻击！\')\"&gt;&nbsp; &nbsp; &nbsp; &nbsp; XSS测试：&lt;br&gt;&nbsp; &nbsp; &nbsp; &lt;/p&gt;&nbsp; &lt;/div&gt;', '<p>  &lt;div class=&quot;test&quot;&gt;      &lt;h2&gt;测试区域&lt;/h2&gt;      &lt;p&gt;这里可以放一些测试内容，或者调试用的组件。&lt;/p&gt;      &lt;p onload=&quot;alert(\'XSS攻击！\')&quot;&gt;        XSS测试：&lt;br&gt;      &lt;/p&gt;  &lt;/div&gt;</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 1, 2, '2026-03-13 14:31:33', '2026-05-19 09:46:14', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (37, 'XSS攻击测试2', 'xss-attack2', '测试xss攻击2', '&nbsp;&lt;div class=\"test\"&gt;&nbsp;&nbsp;&nbsp;&lt;h2&gt;测试区域&lt;/h2&gt;&nbsp;&nbsp;&nbsp;&lt;p&gt;这里可以放一些测试内容，或者调试用的组件。&lt;/p&gt;&nbsp;&nbsp;&nbsp;&lt;p onload=\"alert(\'XSS攻击！\')\"&gt;&nbsp;&nbsp;&nbsp;&nbsp;XSS测试：&lt;br&gt;&nbsp;&nbsp;&nbsp;&lt;/p&gt;&nbsp;&lt;/div&gt;', '<p> &lt;div class=&quot;test&quot;&gt;   &lt;h2&gt;测试区域&lt;/h2&gt;   &lt;p&gt;这里可以放一些测试内容，或者调试用的组件。&lt;/p&gt;   &lt;p onload=&quot;alert(\'XSS攻击！\')&quot;&gt;    XSS测试：&lt;br&gt;   &lt;/p&gt; &lt;/div&gt;</p>\n', 'https://oss.lilicould.cn/cover/cf23f6c0-7fdd-4057-95a9-94b11d4fd50e_xiaodingdang.ico', 1, 5, 2, '2026-03-13 14:40:34', '2026-05-19 09:46:08', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (39, '测试', 'test', '新前端页面测试', '[立里可](https://lilicould.cn)\n\n\n```java\npublic class static void main\n\n```\n> 这是引用\n> 这是引用\n\n# 标题\n## 饼图\n```mermaid\npie\n  \"Dogs\" : 386\n  \"Cats\" : 85\n  \"Rats\" : 15\n```\n', '<p data-line=\"0\"><a href=\"https://lilicould.cn\">立里可</a></p>\n\n        <details  data-line=\"3\" class=\"md-editor-code\" open=\"\">\n          <summary class=\"md-editor-code-head\">\n            <div class=\"md-editor-code-flag\"><span></span><span></span><span></span></div>\n            <div class=\"md-editor-code-action\">\n              <span class=\"md-editor-code-lang\">java</span>\n              <span class=\"md-editor-copy-button\" data-tips=\"复制代码\">复制代码</span>\n              \n              <span class=\"md-editor-collapse-tips\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"lucide lucide-circle-chevron-left md-editor-icon\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m14 16-4-4 4-4\"/></svg></span>\n            </div>\n          </summary>\n          <pre><code class=\"language-java\" language=java><span class=\"md-editor-code-block\"><span class=\"hljs-keyword\">public</span> <span class=\"hljs-keyword\">class</span> <span class=\"hljs-title class_\">static</span> <span class=\"hljs-keyword\">void</span> main</span><span rn-wrapper aria-hidden=\"true\"><span></span></span></code></pre>\n\n        </details>\n      <blockquote data-line=\"7\">\n<p data-line=\"7\">这是引用<br>\n这是引用</p>\n</blockquote>\n<h1 data-line=\"10\" id=\"标题\">标题</h1>\n<h2 data-line=\"11\" id=\"饼图\">饼图</h2>\n<p  data-line=\"12\" class=\"md-editor-mermaid\" data-mermaid-theme=\"light\" data-closed=\"true\" data-processed=\"\" data-content=\"pie\n  &quot;Dogs&quot; : 386\n  &quot;Cats&quot; : 85\n  &quot;Rats&quot; : 15\"><svg id=\"mn9pqupm5bzuemflvfg\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" viewBox=\"0 0 546.96875 450\" style=\"max-width: 546.96875px;\" role=\"graphics-document document\" aria-roledescription=\"pie\"><style>#mn9pqupm5bzuemflvfg{font-family:\"trebuchet ms\",verdana,arial,sans-serif;font-size:16px;fill:#1f2329;}@keyframes edge-animation-frame{from{stroke-dashoffset:0;}}@keyframes dash{to{stroke-dashoffset:0;}}#mn9pqupm5bzuemflvfg .edge-animation-slow{stroke-dasharray:9,5!important;stroke-dashoffset:900;animation:dash 50s linear infinite;stroke-linecap:round;}#mn9pqupm5bzuemflvfg .edge-animation-fast{stroke-dasharray:9,5!important;stroke-dashoffset:900;animation:dash 20s linear infinite;stroke-linecap:round;}#mn9pqupm5bzuemflvfg .error-icon{fill:#f7f8fa;}#mn9pqupm5bzuemflvfg .error-text{fill:#080705;stroke:#080705;}#mn9pqupm5bzuemflvfg .edge-thickness-normal{stroke-width:1px;}#mn9pqupm5bzuemflvfg .edge-thickness-thick{stroke-width:3.5px;}#mn9pqupm5bzuemflvfg .edge-pattern-solid{stroke-dasharray:0;}#mn9pqupm5bzuemflvfg .edge-thickness-invisible{stroke-width:0;fill:none;}#mn9pqupm5bzuemflvfg .edge-pattern-dashed{stroke-dasharray:3;}#mn9pqupm5bzuemflvfg .edge-pattern-dotted{stroke-dasharray:2;}#mn9pqupm5bzuemflvfg .marker{fill:#596273;stroke:#596273;}#mn9pqupm5bzuemflvfg .marker.cross{stroke:#596273;}#mn9pqupm5bzuemflvfg svg{font-family:\"trebuchet ms\",verdana,arial,sans-serif;font-size:16px;}#mn9pqupm5bzuemflvfg p{margin:0;}#mn9pqupm5bzuemflvfg .pieCircle{stroke:black;stroke-width:2px;opacity:0.7;}#mn9pqupm5bzuemflvfg .pieOuterCircle{stroke:black;stroke-width:2px;fill:none;}#mn9pqupm5bzuemflvfg .pieTitleText{text-anchor:middle;font-size:25px;fill:#1f2329;font-family:\"trebuchet ms\",verdana,arial,sans-serif;}#mn9pqupm5bzuemflvfg .slice{font-family:\"trebuchet ms\",verdana,arial,sans-serif;fill:#1f2329;font-size:17px;}#mn9pqupm5bzuemflvfg .legend text{fill:#1f2329;font-family:\"trebuchet ms\",verdana,arial,sans-serif;font-size:17px;}#mn9pqupm5bzuemflvfg :root{--mermaid-font-family:\"trebuchet ms\",verdana,arial,sans-serif;}</style><g></g><g transform=\"translate(225,225)\"><circle cx=\"0\" cy=\"0\" r=\"186\" class=\"pieOuterCircle\"></circle><path d=\"M0,-185A185,185,0,1,1,-177.899,-50.763L0,0Z\" fill=\"#ffffff\" class=\"pieCircle\"></path><path d=\"M-177.899,-50.763A185,185,0,0,1,-35.652,-181.532L0,0Z\" fill=\"#f7f8fa\" class=\"pieCircle\"></path><path d=\"M-35.652,-181.532A185,185,0,0,1,0,-185L0,0Z\" fill=\"#f7f8fa\" class=\"pieCircle\"></path><text transform=\"translate(83.57344705444068,110.75667676234512)\" class=\"slice\" style=\"text-anchor: middle;\">79%</text><text transform=\"translate(-93.90333582091016,-102.14561185731559)\" class=\"slice\" style=\"text-anchor: middle;\">17%</text><text transform=\"translate(-13.432508310066218,-138.09826291630174)\" class=\"slice\" style=\"text-anchor: middle;\">3%</text><text x=\"0\" y=\"-200\" class=\"pieTitleText\"></text><g class=\"legend\" transform=\"translate(216,-33)\"><rect width=\"18\" height=\"18\" style=\"fill: rgb(255, 255, 255); stroke: rgb(255, 255, 255);\"></rect><text x=\"22\" y=\"14\">Dogs</text></g><g class=\"legend\" transform=\"translate(216,-11)\"><rect width=\"18\" height=\"18\" style=\"fill: rgb(247, 248, 250); stroke: rgb(247, 248, 250);\"></rect><text x=\"22\" y=\"14\">Cats</text></g><g class=\"legend\" transform=\"translate(216,11)\"><rect width=\"18\" height=\"18\" style=\"fill: rgb(247, 248, 250); stroke: rgb(247, 248, 250);\"></rect><text x=\"22\" y=\"14\">Rats</text></g></g></svg></p>', NULL, 1, 10, 2, '2026-03-28 10:31:50', '2026-05-19 09:33:08', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (40, '博客更新', 'blog-update', '利用AI给前端页面进行了更新', '> 2026年3月28日\n## 一些变化\n- 更完全的展示\n- 更优雅的界面\n- markdown编辑器\n\n## 代码块展示\n\n```java\npublic static class main（）{\n  test();\n}\n```\n', '<blockquote>\n  <p>2026年3月28日</p>\n</blockquote>\n<h2 id=\"一些变化\">一些变化</h2>\n<ul>\n  <li>更完全的展示</li>\n  <li>更优雅的界面</li>\n  <li>markdown编辑器</li>\n</ul>\n<h2 id=\"代码块展示\">代码块展示</h2>\n<pre><code class=\"language-java\">public static class main（）{\n  test();\n}\n</code></pre>\n', NULL, 1, 36, 1, '2026-03-28 12:44:59', '2026-05-19 09:45:51', 2, 2, 0);
